/**
 * 渲染层源码常量（自动生成，请勿手改）。
 *
 * 来源：src/video-remotion/src/character、src/video-remotion/src/three
 * 重生成：cd src/backend && npm run sync:three-stage
 *
 * 生成任务目录时由 video-generation-agent.service.ts 逐个写入（路径与源目录一致），
 * 模板只负责 import。用 JSON 字符串字面量而不是模板字符串：源码里的反引号、
 * ${}、反斜杠都不用再转义。
 */

export type StageTemplateFile = { path: string; content: string };

export const STAGE_TEMPLATE_FILES: StageTemplateFile[] = [
  {
    "path": "character/pose.ts",
    "content": "/**\r\n * 姿态中枢：与渲染器无关的动作解算\r\n *\r\n * 这个文件是\"角色怎么动\"的唯一真源。它只输出关节目标点，不碰任何渲染 API：\r\n *  - 3D 舞台（three/ThreeActionStage.tsx）把目标点映射到圆柱与四元数；\r\n *  - 2D 角色（character/Puppet2D.tsx）把目标点投影到 SVG 分片；\r\n *  - 以后要加渲染器，只写投影，不写动作。\r\n *\r\n * 坐标系（两个渲染器共用，2D 只取 x/y 并翻转 y）：\r\n *  - 原点在髋部中心，y 向上，单位是\"角色高度\"的归一化世界单位；\r\n *  - 站立时髋部在 y=0.66，脚底约 -0.64；\r\n *  - z 只影响景深与遮挡顺序，2D 用它做左右/前后的小幅错位。\r\n *\r\n * 为什么动作写死在代码里、而参数开放给模型：\r\n * pose() 每帧都要算、必须确定、出错必须可降级——这类东西交给模型现算，\r\n * 换来的是不确定的渲染结果和静默失败。模型该做的是选原语、给参数、给关键帧，\r\n * 那是\"编排\"；这里提供的是\"运动学词汇表\"。新增原语 = 在这个文件加一个函数。\r\n */\r\n\r\nexport type Tri = [number, number, number];\r\n\r\nexport const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));\r\nexport const lerp = (a: number, b: number, t: number) => a + (b - a) * t;\r\nexport const smooth = (t: number) => t * t * (3 - 2 * t);\r\n\r\n/** 角色尺寸（局部坐标，原点在髋部中心） */\r\nexport const SPEC = {\r\n  hipY: 0,\r\n  torsoR: 0.3,\r\n  shoulder: [0.28, 0.42, 0.02] as Tri,\r\n  hipJoint: [0.14, -0.12, 0] as Tri,\r\n  /** 手臂/腿的最大伸展（站姿距离约 0.45 / 0.50，留一点余量，否则会被钳制） */\r\n  armLen: 0.54,\r\n  legLen: 0.52,\r\n  headY: 0.72,\r\n  headR: 0.29,\r\n  /** 站立时髋部离地高度：脚底 -0.64 + 0.02 间隙 */\r\n  standHipY: 0.66,\r\n};\r\n\r\n/**\r\n * 角色尺度基线：**布景尺寸的唯一来源**。\r\n *\r\n * 为什么布景要由角色导出，而不是各写一套数字：\r\n *   - 梯子曾经 2D 宽 0.92、3D 宽 0.56（railHalf 0.46 vs 0.28），同一个\"梯子\"\r\n *     两种宽度，因为两组数字各自凭手感定的；\r\n *   - 0.92 是角色身宽的 1.5 倍，画出来不是梯子而是一面格子墙——这是\"比例\r\n *     脱离了主体\"的典型症状，只调一个常量解决不了：下次改角色体型又会错。\r\n *\r\n * 所以布景只允许使用这里的量（身宽、肩宽、身高等）作为单位。规则写在\r\n * setpiece.ts 顶部，并由 stage-layout.spec.ts 的比例守卫自动检查。\r\n */\r\nexport const ACTOR = {\r\n  /** 躯干外缘宽度（椭圆长轴的两倍） */\r\n  bodyWidth: SPEC.torsoR * 2,\r\n  /** 双肩关节间距 */\r\n  shoulderWidth: SPEC.shoulder[0] * 2,\r\n  /** 站立总高（脚底 0.02 → 头顶） */\r\n  standHeight: SPEC.standHipY + SPEC.headY + SPEC.headR,\r\n  /**\r\n   * 攀爬时的双手横向间距。\r\n   * 手要落在立杆**内侧**，所以梯子宽度由它反推，而不是反过来给梯子定一个\r\n   * 好看的数字再把手摆上去——那样手会漂在杆外。\r\n   */\r\n  gripWidth: SPEC.torsoR * 2 * 1.1,\r\n} as const;\r\n\r\n/**\r\n * 攀爬动作的两个关键高度（相对髋部，向上为正）。\r\n *\r\n * 布景要用它们算\"梯子该比角色高出多少\"，动作要用它们摆手的位置——\r\n * 同一个数只写一份，否则\"手够得着\"和\"梯子够长\"会各自漂移，\r\n * 表现就是爬到顶手悬在半空。\r\n */\r\nexport const CLIMB = {\r\n  /** 抓握点的最高处（离髋部） */\r\n  gripY: 0.88,\r\n  /** 换手时的收手高度 */\r\n  reachY: 0.46,\r\n  /** 一阶的高度。梯子横档间距必须等于它，手脚才会正好落在横档上 */\r\n  step: 0.21,\r\n} as const;\r\n\r\n/** 球半径（注册表是权威值，这里只给渲染兜底） */\r\nexport const BALL_RADIUS = 0.26;\r\n\r\n/**\r\n * 坐滑梯时髋部沿滑面法线抬起的距离（躯干底 -0.28 刚好压在滑面上）。\r\n * 布景注册表要算\"坐在平台上的角色头顶有多高\"，必须用同一个数，\r\n * 所以从这里导出，不在 setpiece.ts 里另抄一份。\r\n */\r\nexport const SLIDE_SEAT_LIFT = 0.27;\r\n\r\n/** 角色造型参数：两个渲染器共用同一份，造型改一次两边一起变 */\r\nexport type ActorRig = {\r\n  fur: string;\r\n  belly: string;\r\n  ears: 'round' | 'long' | 'pointy' | 'flap' | 'none';\r\n  tail: 'stub' | 'long' | 'bushy';\r\n  scale: number;\r\n};\r\n\r\nexport type Pose = {\r\n  root: Tri;\r\n  /** 躯干倾角（弧度），正数为前倾 */\r\n  rotZ: number;\r\n  /** 朝向：0 正对镜头，±π 背对；2D 用它决定左右翻转 */\r\n  rotY: number;\r\n  /** 以下四点都是相对髋部的局部坐标 */\r\n  handL: Tri;\r\n  handR: Tri;\r\n  footL: Tri;\r\n  footR: Tri;\r\n  tailSwing: number;\r\n  headTilt: number;\r\n  squash: number;\r\n};\r\n\r\n/** 静止站姿的四肢位置，所有动作都以它为基准混合 */\r\nexport const STAND_POSE: Omit<Pose, \"root\"> = {\r\n  rotZ: 0,\r\n  rotY: 0,\r\n  handL: [-0.36, -0.02, 0.06],\r\n  handR: [0.36, -0.02, 0.06],\r\n  footL: [-0.16, -0.62, 0.02],\r\n  footR: [0.16, -0.62, 0.02],\r\n  tailSwing: 0,\r\n  headTilt: 0,\r\n  squash: 1,\r\n};\r\n\r\n/**\r\n * 双手中点（相对髋部的局部坐标）。**手里那件东西的挂点**。\r\n *\r\n * 递给 / 合抬的道具位置必须是\"手算出来的\"，不能是\"屏幕上挑一个点\"。\r\n * 前者在换角色体型、换动作、换景别时都自动跟着手；后者只能对上某一帧，\r\n * 于是全片里道具一会儿贴着手、一会儿离手半尺。\r\n */\r\nexport function gripLocal(pose: Pose): Tri {\r\n  /**\r\n   * 挂点是**前伸的那只手**（局部 +x），不是两手的中点。\r\n   *\r\n   * 中点只对\"双手捧在胸前\"成立；双人动作的手是一伸一垂，中点会落回肚皮，\r\n   * 东西就贴在身上而不是递在两人之间。朝向由 facing 镜像，所以这只手\r\n   * 永远朝着对方——两个人各自伸出的手之间的空隙，正是道具该在的位置。\r\n   */\r\n  return [pose.handR[0], pose.handR[1], pose.handR[2]];\r\n}\r\n\r\n/**\r\n * 局部点 → 世界点：施加躯干倾角，再按朝向镜像。\r\n *\r\n * 与 Puppet2D 的投影是同一套约定（先绕髋旋转、再翻左右），所以这里算出的\r\n * \"手在世界里的位置\"和画面上画出来的手是同一个位置。分成两处算就会出现\r\n * \"道具在手的右边一指远\"——因为有一步忘了镜像。\r\n */\r\nexport function localToWorld(root: Tri, pose: Pose, local: Tri, facing: 1 | -1): Tri {\r\n  const c = Math.cos(pose.rotZ);\r\n  const s = Math.sin(pose.rotZ);\r\n  return [\r\n    root[0] + (local[0] * c - local[1] * s) * facing,\r\n    root[1] + local[0] * s + local[1] * c,\r\n    root[2] + local[2],\r\n  ];\r\n}\r\n\r\n/**\r\n * 两个姿态之间的线性混合（t=0 取 a，t=1 取 b）。\r\n *\r\n * 用途是一幕多动作的**段落接缝**：走路末帧手臂在体侧，point 首帧手臂已平举，\r\n * 硬切会\"啪\"地跳一下。混合的是关节目标点，不是渲染结果——所以 2D 的两段肢体\r\n * 求解、3D 的圆柱朝向都会自动跟上，不需要各自再写一份过渡。\r\n *\r\n * 不做弧线插值、不处理重心偏移：姿态差本来就是给人看的过渡，8 帧内线性足够；\r\n * 弧线会让\"抬手\"变成\"绕身体划一圈\"，反而更假。\r\n */\r\nexport function blendPose(a: Pose, b: Pose, t: number): Pose {\r\n  const k = clamp(t, 0, 1);\r\n  const mix = (x: number, y: number) => x + (y - x) * k;\r\n  const mixPoint = (x: Tri, y: Tri): Tri => [mix(x[0], y[0]), mix(x[1], y[1]), mix(x[2], y[2])];\r\n  return {\r\n    root: mixPoint(a.root, b.root),\r\n    rotZ: mix(a.rotZ, b.rotZ),\r\n    rotY: mix(a.rotY, b.rotY),\r\n    handL: mixPoint(a.handL, b.handL),\r\n    handR: mixPoint(a.handR, b.handR),\r\n    footL: mixPoint(a.footL, b.footL),\r\n    footR: mixPoint(a.footR, b.footR),\r\n    tailSwing: mix(a.tailSwing, b.tailSwing),\r\n    headTilt: mix(a.headTilt, b.headTilt),\r\n    squash: mix(a.squash, b.squash),\r\n  };\r\n}\r\n\r\n/**\r\n * 动作原语。这是有限集，也是\"字母表\"：\r\n * 位移 5 个、操作 5 个、手势 4 个、状态 4 个，约 18 个足以覆盖儿童教学场景。\r\n * 新动作优先走\"组合 + 参数 + 关键帧\"，只有真正新的运动学拓扑才加到这里。\r\n */\r\nexport const MOTION_OPS = [\r\n  'idle',\r\n  'speak',\r\n  'point',\r\n  'walk',\r\n  'enter',\r\n  'climb',\r\n  'slide',\r\n  'dribble',\r\n  'cheer',\r\n  'sit',\r\n  /**\r\n   * 双手在身前托着一件东西。递给与合抬都用它。\r\n   *\r\n   * 这不是\"站着手抬一点\"的同义反复：这两个动作的语义是\"东西在谁手里\"，\r\n   * 所以手必须有一个**确定的目标点**，道具才能挂上去。手势一旦是浮动的，\r\n   * 道具就得另算一条时间线，两条线迟早会错开（\"东西悬在离手一掌远的地方\"）。\r\n   */\r\n  'hold',\r\n] as const;\r\nexport type MotionOp = (typeof MOTION_OPS)[number];\r\n\r\n/** 动作输入：只含运动学需要的字段，渲染相关的（配色/名条/素材）不在这里 */\r\nexport type MotionInput = {\r\n  motion: MotionOp;\r\n  durationFrames: number;\r\n  /** 世界坐标轨迹端点，y 向上 */\r\n  start?: Tri;\r\n  end?: Tri;\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  /** climb：阶梯数量 */\r\n  steps?: number;\r\n};\r\n\r\nconst mixTri = (a: Tri, b: Tri, t: number): Tri => [\r\n  lerp(a[0], b[0], t),\r\n  lerp(a[1], b[1], t),\r\n  lerp(a[2], b[2], t),\r\n];\r\n\r\n/** 把一段位移曲线（0..1）映射到起终点之间 */\r\nconst alongPath = (start: Tri, end: Tri, t: number): Tri => mixTri(start, end, t);\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 状态类：站着、说话、欢呼、坐下\r\n * ------------------------------------------------------------------ */\r\n\r\nfunction idlePose(frame: number, amp = 1): Pose {\r\n  // 呼吸：4 秒一个来回，起伏 1.2cm，肉眼刚好能看出\"活着\"\r\n  const breath = Math.sin(frame / 14) * 0.012 * amp;\r\n  return {\r\n    root: [0, SPEC.standHipY + breath, 0],\r\n    rotZ: 0,\r\n    rotY: 0,\r\n    handL: [STAND_POSE.handL[0], STAND_POSE.handL[1] + breath * 0.5, STAND_POSE.handL[2]],\r\n    handR: [STAND_POSE.handR[0], STAND_POSE.handR[1] + breath * 0.5, STAND_POSE.handR[2]],\r\n    footL: STAND_POSE.footL,\r\n    footR: STAND_POSE.footR,\r\n    tailSwing: Math.sin(frame / 11) * 0.25,\r\n    headTilt: Math.sin(frame / 20) * 0.03,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\nfunction speakPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.8);\r\n  // 说话的手势：右手抬起做强调，跟着语气分句起伏（不是匀速摆）\r\n  const beat = Math.sin(frame / 6);\r\n  const lift = Math.max(0, Math.sin(frame / 9));\r\n  return {\r\n    ...base,\r\n    handR: [0.4, -0.02 + lift * 0.26, 0.14 + beat * 0.03],\r\n    // 点头幅度比 idle 大：说话时头部是最先被注意到的地方\r\n    headTilt: Math.sin(frame / 8) * 0.06,\r\n  };\r\n}\r\n\r\n/**\r\n * 指认：右臂向侧前方平伸，指尖略高于肩，手腕有细小抖动。\r\n *\r\n * 单独一个原语而不是复用 speak 的抬手，因为两者在孩子眼里是两件事：\r\n * speak 是\"我在说\"，手在身前比划；point 是\"看那个\"，手臂明确指向画面另一侧\r\n * 的道具。合成一个动作会让\"指着滑梯\"看起来像\"在滑梯旁边自言自语\"。\r\n */\r\nfunction pointPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.7);\r\n  // 持续平举会像假人，加一个幅度很小、周期较慢的呼吸式浮动\r\n  const drift = Math.sin(frame / 16) * 0.025;\r\n  const wobble = Math.sin(frame / 9) * 0.012;\r\n  return {\r\n    ...base,\r\n    // 手臂要接近水平（肩在 y=0.42），并且 x 伸到躯干轮廓之外（半径 0.3），\r\n    // 否则手掌会被躯干吃掉，画面上只剩躯干侧面鼓出一个疙瘩。\r\n    handR: [0.78, 0.34 + drift, 0.2 + wobble],\r\n    // 左臂自然下垂略后摆：x 不能收到 -0.26 以内，那会让上臂折进身体\r\n    handL: [-0.34, -0.06, 0.04],\r\n    // 上半身朝指向侧轻微侧倾：孩子读\"指着那边\"主要看身体朝向，不看手指\r\n    rotZ: -0.04 + drift * 0.4,\r\n    headTilt: -0.04,\r\n  };\r\n}\r\n\r\nfunction cheerPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.6);\r\n  // 双手举高 + 弹跳，庆祝类分镜用\r\n  const hop = Math.abs(Math.sin(frame / 7));\r\n  return {\r\n    ...base,\r\n    root: [0, SPEC.standHipY + hop * 0.12, 0],\r\n    handL: [-0.42, 0.5 + hop * 0.08, 0.1],\r\n    handR: [0.42, 0.5 + hop * 0.08, 0.1],\r\n    footL: [-0.18, -0.62 + hop * 0.1, 0.02],\r\n    footR: [0.18, -0.62 + hop * 0.1, 0.02],\r\n    headTilt: -0.1,\r\n    tailSwing: Math.sin(frame / 6) * 0.5,\r\n  };\r\n}\r\n\r\nfunction sitPose(frame: number): Pose {\r\n  const swing = Math.sin(frame / 9) * 0.05;\r\n  return {\r\n    root: [0, SPEC.standHipY - 0.26, 0],\r\n    rotZ: 0,\r\n    rotY: 0,\r\n    handL: [-0.34, 0.06 + swing * 0.4, 0.18],\r\n    handR: [0.34, 0.06 - swing * 0.4, 0.18],\r\n    // 坐着时腿向前伸，脚落在身体前方\r\n    footL: [0.24, -0.3, -0.12],\r\n    footR: [0.24, -0.3, 0.12],\r\n    tailSwing: Math.sin(frame / 10) * 0.3,\r\n    headTilt: 0,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/**\r\n * 托举：**朝向对方的那只手臂前伸**，另一只自然垂在体侧。\r\n *\r\n * 为什么不是\"双手在胸前捧着\"（第一版就是这么写的）：\r\n * 正面视角里，双手收到身前画出来是\"抱胸/比划\"，因为手臂在投影上只能往\r\n * 身体中线折——两道弯都朝内，看着像在跟自己的肚子较劲。而双人动作要表达的是\r\n * \"把东西递到对方面前\"，能读出来的只有**伸出去的那条手臂**。\r\n *\r\n * 两个约束决定了手的位置：\r\n *   - 肩到手 0.46，接近臂长 0.54：再近手臂就折成\"抱胸\"，再远会被 clampReach 钳制，\r\n *     画面上是手停在半空、前臂不跟着走；\r\n *   - 手在身体轮廓之外（局部 x 0.72 > 躯干半径 0.3）：东西才不在肚皮上，\r\n *     而是在两人之间的空当里。\r\n */\r\nfunction holdPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.6);\r\n  const breathe = Math.sin(frame / 15) * 0.012;\r\n  return {\r\n    ...base,\r\n    // 局部 +x 是\"角色前方\"（由 facing 镜像）：两个人各自把这条手臂伸向对方\r\n    handR: [0.72, 0.29 + breathe, 0.26],\r\n    // 另一侧自然下垂略前摆：抬到胸口就变成\"双手捧\"，那是另一种语义\r\n    handL: [-0.34, -0.04 + breathe, 0.1],\r\n    rotZ: 0.05,\r\n    headTilt: 0.05,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 位移类：走、入场、爬\r\n * ------------------------------------------------------------------ */\r\n\r\n/**\r\n * 走路：双腿反相摆动，双臂与对侧腿同相。\r\n * 关键不是\"位移多少\"，而是\"支撑脚在地面不动、摆动脚离地\"——\r\n * 前者决定看起来像不像滑行，后者决定有没有\"一步一步\"的节奏。\r\n */\r\nfunction walkPose(input: MotionInput, frame: number, cycles = 2.4): Pose {\r\n  const dur = Math.max(12, input.durationFrames || 90);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  const start = input.start ?? [0, SPEC.standHipY, 0];\r\n  const end = input.end ?? [0, SPEC.standHipY, 0];\r\n  // 起止各留 12% 做加减速：匀速走像传送带\r\n  const travel = smooth(clamp((u - 0.06) / 0.86, 0, 1));\r\n  const root = alongPath(start, end, travel);\r\n\r\n  const legPhase = 2 * Math.PI * cycles * u;\r\n  const swingL = Math.sin(legPhase);\r\n  const swingR = Math.sin(legPhase + Math.PI);\r\n  // 抬脚只取正半周：脚在地面时不上下飘\r\n  const liftL = Math.max(0, swingL) * 0.15;\r\n  const liftR = Math.max(0, swingR) * 0.15;\r\n  // 身体上下：一个步幅两次起伏（双脚各一次支撑）\r\n  const bob = Math.abs(Math.sin(legPhase)) * 0.022;\r\n\r\n  return {\r\n    root: [root[0], root[1] + bob, root[2]],\r\n    rotZ: 0.04,\r\n    rotY: 0,\r\n    handL: [-0.36 + swingR * 0.12, -0.02 + Math.abs(swingR) * 0.03, 0.06],\r\n    handR: [0.36 + swingL * 0.12, -0.02 + Math.abs(swingL) * 0.03, 0.06],\r\n    // 2D 是正面视角，\"前后\"没有第三个维度可表现：脚如果左右摆到 ±0.2，\r\n    // 会和 ±0.16 的基础站距抵消、两腿交叉成一坨。所以横向几乎不动，\r\n    // 走路全靠\"抬脚交替\"与身体起伏来读——这是正面视角唯一诚实的手段。\r\n    footL: [-0.17, -0.62 + liftL, 0.02],\r\n    footR: [0.17, -0.62 + liftR, 0.02],\r\n    tailSwing: Math.sin(legPhase * 0.5) * 0.35,\r\n    headTilt: Math.sin(legPhase) * 0.04,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/** 入场：和走路同一套腿部节奏，但带淡入感——前 8 帧重心略低，像刚迈进来 */\r\nfunction enterPose(input: MotionInput, frame: number): Pose {\r\n  const walk = walkPose(input, frame, 2.0);\r\n  const settle = smooth(clamp(frame / 18, 0, 1));\r\n  return {\r\n    ...walk,\r\n    root: [walk.root[0], walk.root[1] - (1 - settle) * 0.05, walk.root[2]],\r\n    headTilt: walk.headTilt - (1 - settle) * 0.1,\r\n  };\r\n}\r\n\r\n/**\r\n * 爬梯子：这是\"爬上滑梯\"需要的那个动作，也是 2D 之前完全缺失的表达。\r\n *\r\n * 三条规则让它读起来像\"爬\"而不是\"向上飘\"：\r\n *  1. 上升是离散的——重心按阶跳，每阶内部用 smooth 过渡，视觉上有停顿；\r\n *  2. 手脚交替——一侧脚抬起时，对侧手在向上够（同手同脚会像僵尸）；\r\n *  3. 身体前倾——贴着梯子，不是直立在旁边。\r\n */\r\nfunction climbPose(input: MotionInput, frame: number): Pose {\r\n  const dur = Math.max(24, input.durationFrames || 120);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  const steps = Math.max(1, Math.round(input.steps ?? 4));\r\n  // 末 12% 停在顶端站稳，不然最后一帧还在动\r\n  const p = clamp(u / 0.88, 0, 1) * steps;\r\n  const k = Math.min(steps - 1, Math.floor(p));\r\n  const phase = clamp(p - k, 0, 1);\r\n  const progress = clamp((k + smooth(phase)) / steps, 0, 1);\r\n\r\n  const start = input.start ?? [-0.55, SPEC.standHipY, 0];\r\n  const end = input.end ?? [-0.55, SPEC.standHipY + CLIMB.step * steps, 0];\r\n  const root = alongPath(start, end, progress);\r\n  const stepH = Math.max(0.05, (end[1] - start[1]) / steps);\r\n\r\n  // 每阶换主导侧：同手同脚看起来像僵尸\r\n  const lead = k % 2 === 0 ? 1 : -1;\r\n  // 两只手脚各有相位，副侧落后半阶，形成\"抓—拉—换\"的交替\r\n  const phaseLead = phase;\r\n  const phaseTrail = (phase + 0.5) % 1;\r\n\r\n  /**\r\n   * 手为什么不是\"相对髋部固定\"：\r\n   * 手抓住横档之后，横档在世界里不动，身体往上走 → 手相对髋部越来越低，\r\n   * 手臂从伸直变成弯曲；跨到下一阶时手跳到上一根横档，重新伸直。\r\n   * 如果让 hand 相对髋部恒定，画面上就是\"手黏在梯子上跟身体一起滑\"，\r\n   * 完全没有\"一把一把往上抓\"的感觉。这是爬梯最关键的一条。\r\n   */\r\n  const gripY = (ph: number) => CLIMB.gripY - ph * stepH;\r\n  // 另一只手在换手：从上一档松手，收到胸前再抓上去\r\n  const reachY = (ph: number) => CLIMB.reachY - ph * stepH * 0.6;\r\n\r\n  /**\r\n   * 手的横向位置来自\"攀爬握距\"，梯子立杆间距再由它反推（setpiece.LADDER）。\r\n   * 反过来先定梯子宽度、再把手摆上去，就会出现手落在立杆外侧——画面上是\r\n   * 熊抱着梯子的两边，抓空。0.96 让掌心落在立杆内侧而不压线。\r\n   */\r\n  const handX = (ACTOR.gripWidth / 2) * 0.96;\r\n  const handLead: Tri = [lead * handX, gripY(phaseLead), 0.18];\r\n  const handTrail: Tri = [-lead * handX, reachY(phaseTrail), 0.12];\r\n\r\n  // 脚：踩住的那只不抬，抬起的那只收到脚踝高度再踩下一档\r\n  const stepLift = (ph: number) => Math.max(0, Math.sin(Math.PI * ph)) * 0.2;\r\n  const footLeadY = -0.62 + stepLift(phaseLead) * (phaseLead < 0.5 ? 1 : 0.2);\r\n  const footTrailY = -0.62 + stepLift(phaseTrail) * (phaseTrail < 0.5 ? 1 : 0.2);\r\n\r\n  return {\r\n    root: [root[0], root[1], root[2]],\r\n    // 倾角只能很小：gripY 是按\"局部 y 差\"算的，而投影会施加 rotZ，\r\n    // 倾 18° 会把手的实际高度抬高 0.065（约两根横档间距的一半），\r\n    // 手脚于是落在横档之间——看起来就是\"手悬在半空\"。\r\n    // 爬直梯本来也接近直立，前倾由手/脚的前后位置表达，不靠整体旋转。\r\n    rotZ: 0.05 + Math.sin(p * Math.PI) * 0.02,\r\n    rotY: 0,\r\n    handL: lead > 0 ? handLead : handTrail,\r\n    handR: lead > 0 ? handTrail : handLead,\r\n    footL: [-0.17, lead > 0 ? footLeadY : footTrailY, 0.04],\r\n    footR: [0.17, lead > 0 ? footTrailY : footLeadY, 0.04],\r\n    tailSwing: Math.sin(p * Math.PI) * 0.3,\r\n    headTilt: -0.14 + phase * 0.04,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 滑滑梯（原有 3D 动作，逻辑一字未改，只把入参类型收窄到运动学字段）\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function slidePose(input: MotionInput, frame: number): Pose {\r\n  const dur = Math.max(24, input.durationFrames || 90);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  // 加速度曲线：起滑慢、中段快、到底前不再加速（u^1.5 而不是线性）\r\n  const travel = Math.pow(u, 1.5);\r\n\r\n  const start = input.start ?? [-3.1, 2.7, 0];\r\n  const end = input.end ?? [2.9, 0.3, 0];\r\n  const sx = start[0];\r\n  const sy = start[1];\r\n  const ex = end[0];\r\n  const ey = end[1];\r\n  const dx = ex - sx;\r\n  const dy = ey - sy;\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 1;\r\n  const nx = -dy / len;\r\n  const ny = dx / len;\r\n  const angle = Math.atan2(dy, dx);\r\n\r\n  // 沿滑面 4% → 96%：起点落在平台上，终点停在滑面底端\r\n  const p = lerp(0.04, 0.96, travel);\r\n  const px = sx + dx * p;\r\n  const py = sy + dy * p;\r\n\r\n  // 坐姿：髋部沿法线抬起 SLIDE_SEAT_LIFT（躯干底 -0.28 刚好压在滑面上），双腿沿滑面\r\n  // 向前伸出而不是垂到板下面——垂下去会被滑板挡住，看起来像\"浮在板上\"。\r\n  const slideRoot: Tri = [px + nx * SLIDE_SEAT_LIFT, py + ny * SLIDE_SEAT_LIFT, 0];\r\n  const swing = Math.sin(frame / 5) * 0.06;\r\n  const sitting: Omit<Pose, \"root\"> = {\r\n    rotZ: angle + 0.1,\r\n    rotY: 0,\r\n    handL: [-0.4, 0.74 + swing, 0.2],\r\n    handR: [0.4, 0.74 - swing, 0.2],\r\n    footL: [0.5, 0.12 + swing * 0.5, -0.14],\r\n    footR: [0.5, 0.12 - swing * 0.5, 0.14],\r\n    tailSwing: Math.sin(frame / 8) * 0.5,\r\n    headTilt: -0.12,\r\n    squash: 1,\r\n  };\r\n\r\n  // 最后一程站起来：坐姿 → 站姿，位置从滑面底端落到地面\r\n  const standT = smooth(clamp((u - 0.9) / 0.1, 0, 1));\r\n  // 落地点要离开滑道末端：贴着末端站会和斜板叠在一起，像被插穿\r\n  const standRoot: Tri = [ex + 0.8, SPEC.standHipY, 0];\r\n  const root: Tri = [\r\n    lerp(slideRoot[0], standRoot[0], standT),\r\n    lerp(slideRoot[1], standRoot[1], standT),\r\n    lerp(slideRoot[2], standRoot[2], standT),\r\n  ];\r\n\r\n  return {\r\n    root,\r\n    rotZ: lerp(sitting.rotZ, STAND_POSE.rotZ, standT),\r\n    rotY: 0,\r\n    handL: mixTri(sitting.handL, STAND_POSE.handL, standT),\r\n    handR: mixTri(sitting.handR, STAND_POSE.handR, standT),\r\n    footL: mixTri(sitting.footL, STAND_POSE.footL, standT),\r\n    footR: mixTri(sitting.footR, STAND_POSE.footR, standT),\r\n    tailSwing: lerp(sitting.tailSwing, 0, standT),\r\n    headTilt: lerp(sitting.headTilt, 0, standT),\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 拍球\r\n *\r\n * 接触关系是这一段的核心：球的 Y 由周期函数给出，接触帧固定在周期边界；\r\n * 熊掌目标点 = 球心 + 0.9R（搭在球顶），手臂用\"肩→目标\"定向自动跟手。\r\n * 因此\"掌球同帧接触\"不是靠调参对齐两条时间线，而是同一个变量算出来的。\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function dribblePose(\r\n  input: MotionInput,\r\n  frame: number,\r\n): { pose: Pose; ball: Tri; squash: number; spin: number } {\r\n  const period = Math.max(6, input.bounce?.periodFrames ?? 18);\r\n  const height = Math.max(0.2, input.bounce?.height ?? 0.62);\r\n  const rest = input.ballRestY ?? 0.27;\r\n  const radius = BALL_RADIUS;\r\n\r\n  const cyclePhase = (((frame % period) + period) % period) / period;\r\n  const lift = Math.abs(Math.sin(Math.PI * cyclePhase));\r\n  const ballY = rest + height * lift;\r\n\r\n  // 球在小熊右侧、同一景深平面内：再往前放会让手臂藏在球后面，\r\n  // 孩子看到的是\"一颗球悬在耳边\"，不是\"熊掌在拍球\"。\r\n  const ballX = 0.72;\r\n  const ballZ = 0.15;\r\n  const ball: Tri = [ballX, ballY, ballZ];\r\n\r\n  // 落地附近压扁，最高点恢复\r\n  const contact = clamp(1 - (ballY - rest) / 0.14, 0, 1);\r\n  const squash = 1 - 0.12 * contact;\r\n  const spin = frame * 0.1;\r\n\r\n  // 身体随球起伏：球到手边时微微下蹲，球飞起时站直\r\n  const hipY = SPEC.standHipY - 0.07 * (1 - lift);\r\n  const root: Tri = [0, hipY, 0];\r\n\r\n  // 右掌搭在球顶靠前的一侧（z 比球心大 0.11）：既真实接触又不被球挡住。\r\n  // 目标点 = 球心 + 0.9R，臂长 0.54 覆盖得了这个范围，所以不会被拉伸。\r\n  const handR: Tri = [ballX, ballY + radius * 0.9 - hipY, ballZ + 0.11];\r\n  // 左臂自然摆动配平\r\n  const handL: Tri = [-0.38, -0.02 + Math.sin(frame / 7) * 0.05, 0.08];\r\n  // 脚随下蹲略微屈膝\r\n  const kneeDrop = 0.07 * (1 - lift);\r\n  const footL: Tri = [-0.16, -0.62 + kneeDrop, 0.02];\r\n  const footR: Tri = [0.16, -0.62 + kneeDrop, 0.02];\r\n\r\n  return {\r\n    pose: {\r\n      root,\r\n      rotZ: 0,\r\n      // 身体正对镜头：转身体会把手臂目标点一起转走，掌心就贴不到球了\r\n      rotY: 0,\r\n      handL,\r\n      handR,\r\n      footL,\r\n      footR,\r\n      tailSwing: Math.sin(frame / 9) * 0.35,\r\n      headTilt: 0.18 + lift * 0.05,\r\n      squash: 1,\r\n    },\r\n    ball,\r\n    squash,\r\n    spin,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 分发：新增原语只在这里加一行，渲染器不动\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function poseAt(input: MotionInput, frame: number): Pose {\r\n  switch (input.motion) {\r\n    case 'slide':\r\n      return slidePose(input, frame);\r\n    case 'dribble':\r\n      return dribblePose(input, frame).pose;\r\n    case 'walk':\r\n      return walkPose(input, frame);\r\n    case 'enter':\r\n      return enterPose(input, frame);\r\n    case 'climb':\r\n      return climbPose(input, frame);\r\n    case 'speak':\r\n      return speakPose(frame);\r\n    case 'point':\r\n      return pointPose(frame);\r\n    case 'cheer':\r\n      return cheerPose(frame);\r\n    case 'sit':\r\n      return sitPose(frame);\r\n    case 'hold':\r\n      return holdPose(frame);\r\n    case 'idle':\r\n    default:\r\n      return idlePose(frame);\r\n  }\r\n}\r\n\r\n/** 这个原语需要哪些运动学参数（给后端做可演性校验用） */\r\nexport const MOTION_REQUIRES: Record<MotionOp, Array<keyof MotionInput>> = {\r\n  idle: [],\r\n  speak: [],\r\n  point: [],\r\n  cheer: [],\r\n  sit: [],\r\n  hold: [],\r\n  walk: ['start', 'end'],\r\n  enter: ['start', 'end'],\r\n  climb: ['start', 'end'],\r\n  slide: ['start', 'end'],\r\n  dribble: ['bounce'],\r\n};\r\n"
  },
  {
    "path": "character/stage-layout.ts",
    "content": "/**\n * 景别层（shot）：把\"画什么\"和\"画多大\"分开\n *\n * 这个文件解决的是同一类事故的**结构**问题，不是某一帧好看不好看：\n *\n *   - 梯子顶端被标题胶囊压住（实测：标题白底覆盖 42..121px，梯子顶端 114px）。\n *     根因不是\"梯子画高了\"，而是缩放系数 265 是个硬编码常量，和\"标题占多高\"\n *     没有任何关系——只要动作再高一点，画面就会撞上去，而改这个常量又会牵连\n *     所有场景的大小。\n *   - 二维地面 856、三维地面（lookY 反推）约 827。两边各自写死，切镜头时\n *     角色会上下跳一小格，观众说不出哪里不对，但会觉得\"闪\"。\n *   - 没有\"景别\"概念：滑梯要装下整个结构、拍球只需要装下熊、头像只需要脸，\n *     三种需求共用一套取景，只能取折中值，谁都不合适。\n *\n * 做法是一条取景定律，而不是一堆特例：\n *\n *   ppu（每世界单位多少像素）\n *     = min( 可用带高 × 该景别占比 ÷ 主体高度,\n *            可用带高 ÷ 内容世界高度 )\n *\n * 前一项决定\"主体看起来多大\"，后一项决定\"布景一次能装多高\"。\"内容世界高度\"\n * 由布景/姿态给出（见 setpiece.ts），\"可用带高\"由标题与地面给出（本文件）。\n * 于是\"主体不能高过标题\"不再是需要记得遵守的约定，而是算不出来就越界的量——\n * 内容再高，缩放自动变小。\n *\n * 三维相机不是另一套参数：给定 ppu 与地面线，相机距离与 lookY 由公式反推，\n * 保证 3D 的地面**也**落在 STAGE.groundY。这是\"2D/3D 同源\"的第一层。\n *\n * 第二层是横向：取景吃的不是\"内容多高\"，而是**内容包围盒**（Bounds）。有了盒，\n * \"内容偏左\"\"内容太宽\"才有地方表达，才能靠公式而不是靠逐个调坐标解决：\n *   - ppu 同时被\"纵向装得下\"和\"横向装得下（含两侧留白）\"约束；\n *   - 画面按内容中心对齐，而不是把世界原点硬按在画面中线。\n * 所以渲染器只需要回答\"这一幕占了世界上哪一块\"，不需要知道取景怎么算。\n */\n\nimport { ACTOR } from './pose';\n\n/** 画面尺寸。与 Remotion composition 一致，渲染器不做第二次取整 */\nexport const STAGE = {\n  width: 1920,\n  height: 1080,\n  /** 角色横向锚点（滑梯/梯子/球都围绕它） */\n  centerX: 960,\n  /**\n   * 标题胶囊底边。不是估的：对 1080p 抽帧做像素扫描，中心 700..1250 区间里\n   * 连续白底出现在 y=42..121。改标题字号/内边距必须重测这个值。\n   */\n  titleBandBottom: 121,\n  /**\n   * 主体与标题之间至少留这么多像素。\n   * 30 而不是 20：2D 立杆是 round cap 的描边，**视觉**顶边会比几何顶端高\n   * 半个线宽（实测约 7px），只留 20 的话看起来还是贴着标题。\n   */\n  titleGap: 30,\n  /** 地面线：2D 投影与 3D 相机都对齐到这一行，切换渲染器时脚不会跳 */\n  groundY: 856,\n};\n\n/** 主体可用区域的上边界 */\nexport const SUBJECT_TOP = STAGE.titleBandBottom + STAGE.titleGap;\n/** 主体可用带高（像素） */\nexport const SUBJECT_BAND = STAGE.groundY - SUBJECT_TOP;\n\n/**\n * 画面左右的安全留白（像素）。\n *\n * 为什么留白要参与**缩放**而不是只做平移：滑梯横跨 7.7 个世界单位，按高度\n * 算出来的 ppu 让它在屏幕上占 1367px，落在 960 中心时左端只剩 115px、右端\n * 剩 437px——左边像被裁掉了，右边空一大块。只平移能居中，但两个边距都会\n * 变小；只有让留白成为 ppu 的上限约束，\"装得下且两边都有呼吸\"才是算出来的。\n */\nexport const SAFE_X = 72;\n\n/**\n * 内容包围盒（世界单位）。取景只吃这一个东西，不认识具体是梯子还是滑梯。\n *\n * 引入它之前，取景只有\"内容高度\"一个数：所以\"内容偏左/偏右\"\"横向太宽\"\n * 这类问题根本无处表达，只能靠人眼看出来再逐个调坐标——那正是\"针对某个\n * 场景特定优化\"。有了盒，新增任何布景/道具只要报告自己的范围，取景自动\n * 把它算进去：装不下就后退，偏了就平移。\n */\nexport type Bounds = { minX: number; maxX: number; minY: number; maxY: number };\n\n/** 空盒（用于 reduce 起点）。宽高为负，union 任何真盒后即被覆盖 */\nexport const EMPTY_BOUNDS: Bounds = {\n  minX: Infinity,\n  maxX: -Infinity,\n  minY: Infinity,\n  maxY: -Infinity,\n};\n\nexport function unionBounds(a: Bounds, b: Bounds): Bounds {\n  return {\n    minX: Math.min(a.minX, b.minX),\n    maxX: Math.max(a.maxX, b.maxX),\n    minY: Math.min(a.minY, b.minY),\n    maxY: Math.max(a.maxY, b.maxY),\n  };\n}\n\nexport function unionAll(boxes: Bounds[]): Bounds {\n  return boxes.reduce(unionBounds, EMPTY_BOUNDS);\n}\n\nexport const boundsWidth = (b: Bounds) => b.maxX - b.minX;\nexport const boundsHeight = (b: Bounds) => b.maxY - b.minY;\nexport const boundsCenterX = (b: Bounds) => (b.minX + b.maxX) / 2;\n\n/**\n * 景别。取值不多，因为每多一档就多一组要维护的取舍：\n *  - wide：动作幕。主体仍是\"中景大小\"，但**必须装下布景**（梯子、滑梯），\n *    装不下就自动往后退——全景是\"为布景让路\"的结果，不是无条件缩小。\n *  - medium：单角色动作的默认档，角色约占可用带高 62%（与既有成片一致）。\n *  - close：面孔/情绪/说话。角色占满带高，脚仍踩在地面线上。\n */\nexport type Shot = 'wide' | 'medium' | 'close';\n\n/** 每个景别里\"主体占可用带高的比例\" */\nconst SHOT_FILL: Record<Shot, number> = { wide: 0.62, medium: 0.62, close: 0.92 };\n\n/** 缩放安全区：太小看不清，太大等于把角色糊在镜头上 */\nconst PPU_LIMIT = { min: 110, max: 560 };\n\n/** 三维相机：与 three/ThreeActionStage 共用，勿在别处再写一份 */\nexport const CAMERA_FOV = 40;\n\nexport type Framing = {\n  shot: Shot;\n  /** 每世界单位对应多少屏幕像素（2D 直接用它当缩放） */\n  ppu: number;\n  /** 地面在屏幕上的行（像素） */\n  groundY: number;\n  /** 世界原点（x=0）落在屏幕第几列。投影就是 originX + x*ppu，别再写 960 */\n  originX: number;\n  /** 内容中心的世界 x（三维持景按它整体平移，与 originX 同源） */\n  worldCenterX: number;\n  /** 三维相机参数：由 ppu/地面行/内容中心反推，保证与 2D 落在同一位置 */\n  camera: { fov: number; z: number; lookY: number; lookX: number };\n};\n\nconst clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));\n\nexport type FramingInput = {\n  /** 必须完整可见的内容盒。给了它就能同时管住\"装得下\"和\"居中\" */\n  bounds?: Bounds;\n  /**\n   * 只有高度、没有横向要求时的简写（兼容旧调用）。\n   * 注意它**不会**约束宽度——不知道内容的横向范围时，假装它很窄反而会让\n   * 宽布景被裁，所以宁可不管。\n   */\n  contentHeight?: number;\n  /** 主体的世界高度（角色站高）。不给就与内容高度相同 */\n  subjectHeight?: number;\n};\n\n/**\n * 取景：ppu = min(带高 × 景别占比 ÷ 主体高度, 带高 ÷ 内容高度, 可用宽 ÷ 内容宽度)\n *\n * 三个约束分别对应三件事：\n *  - 第一项是\"主体看起来多大\"（景别意图）；\n *  - 第二项是\"纵向不许裁掉布景\"（物理约束）；\n *  - 第三项是\"横向不许裁掉布景，且两边都留出安全留白\"。\n * 取小者，于是\"内容太宽/太高\"时全景会自然后退，而不是把两侧切掉。\n *\n * 平移：内容中心不再被强行按到画面中线。滑梯的几何中心在 x=-0.9，硬按到\n * 中线会让左端贴边、右端空出一大块；现在按内容中心对齐，两边留白相等。\n */\nexport function framingFor(input: FramingInput, shot: Shot): Framing {\n  // 空盒（全是 ±Infinity 或还没并出任何内容）当作\"没给\"，否则中心会算出 NaN，\n  // 整块 transform 变成 NaN 后画面是空白——这种故障比\"稍微裁一点\"难查得多。\n  const box =\n    input.bounds && Number.isFinite(input.bounds.minX) && Number.isFinite(input.bounds.maxX)\n      ? input.bounds\n      : undefined;\n  const contentH = Math.max(0.2, box ? boundsHeight(box) : (input.contentHeight ?? 1));\n  const subject = Math.max(0.2, input.subjectHeight ?? contentH);\n  const ppuFitWidth = box\n    ? (STAGE.width - 2 * SAFE_X) / Math.max(0.4, boundsWidth(box))\n    : Infinity;\n  const ppu = clamp(\n    Math.min(\n      (SUBJECT_BAND * SHOT_FILL[shot]) / subject,\n      SUBJECT_BAND / contentH,\n      ppuFitWidth,\n    ),\n    PPU_LIMIT.min,\n    PPU_LIMIT.max,\n  );\n  const worldCenterX = box ? boundsCenterX(box) : 0;\n  const tanHalf = Math.tan((CAMERA_FOV * Math.PI) / 360);\n  // 屏幕Y = H/2 + lookY * ppu ⇒ lookY = (地面行 - H/2) / ppu\n  // 屏幕X = W/2 - (lookX - x) * ppu ⇒ 世界平移量就是内容中心\n  return {\n    shot,\n    ppu,\n    groundY: STAGE.groundY,\n    originX: STAGE.centerX - worldCenterX * ppu,\n    worldCenterX,\n    camera: {\n      fov: CAMERA_FOV,\n      z: STAGE.height / (2 * ppu * tanHalf),\n      lookY: (STAGE.groundY - STAGE.height / 2) / ppu,\n      lookX: worldCenterX,\n    },\n  };\n}\n\n/**\n * 动作 → 景别。\n *\n * 判断依据是\"这个动作要装下多大的东西\"，不是\"动作名字眼熟\"：\n * 爬（梯子高过角色一倍）与滑（整条滑道）必须 wide，其余单角色动作 medium。\n * 新增动作时**必须**在这里表态，否则会落到 medium——这是刻意的：\n * 默认取\"装下角色\"，最坏情况是布景被裁一点，而不是压住标题。\n */\nconst WIDE_MOTIONS: ReadonlySet<string> = new Set(['climb', 'slide']);\n\nexport function shotForMotion(motion: string): Shot {\n  return WIDE_MOTIONS.has(motion) ? 'wide' : 'medium';\n}\n\n/**\n * 道具槽位（**世界单位**，不是屏幕像素）。\n *\n * 以前返回的是屏幕坐标（x = centerX ± 470、size = 带高 × 0.4）。两个后果：\n *   - 取景一旦平移（内容偏左就整体右移），屏幕坐标的道具不会跟着动，\n *     角色和道具会错位；\n *   - 尺寸按\"带高比例\"给，与角色大小无关，换景别后要么压住角色，要么小得\n *     像贴在背景上的图标。\n * 改成世界单位后，道具与角色、布景在同一套坐标里，由取景统一投影；它也\n * 自动进入内容包围盒，\"被指着的东西\"永远不会落在画面外。\n *\n * 尺寸与间距都由 ACTOR 导出：道具高约 0.57 个角色，横向留出一个身宽的\n * 空隙，于是无论角色多大，道具都不会糊到脸上。\n */\nconst PROP_SIZE = ACTOR.standHeight * 0.57;\nconst PROP_GAP = ACTOR.bodyWidth / 2 + PROP_SIZE / 2 + ACTOR.bodyWidth * 0.8;\n\n/**\n * side: -1 放左侧，+1 放右侧。调用方按\"角色走/站的方向\"决定，别把道具摆在\n * 角色脸前。y 是道具**中心**离地高度（= 半个高，底边正好贴地）。\n */\nexport function propSlot(side: 1 | -1): { x: number; y: number; size: number } {\n  return { x: side * PROP_GAP, y: PROP_SIZE / 2, size: PROP_SIZE };\n}\n\n/** 道具的包围盒：底边贴地，宽度等于绘制尺寸 */\nexport function propBounds(slot: { x: number; y: number; size: number }): Bounds {\n  return {\n    minX: slot.x - slot.size / 2,\n    maxX: slot.x + slot.size / 2,\n    minY: 0,\n    maxY: slot.size,\n  };\n}\n\n/**\n * 头像/徽章分支的取景。\n *\n * 徽章不是世界坐标里的角色（没有脚、没有地面），所以不吃 ppu；但它同样不能\n * 侵入标题带。返回的是**布局盒**（未缩放）的位置与缩放系数：\n * 盒子底边贴地，缩放原点在底边中点，于是放大只会往上长，下沿永远在地面线上，\n * 上沿由\"带高 × 92%\"决定。模板按这个摆，别再写 top:330 / scale:1.4。\n */\nexport function portraitFraming(): {\n  /** 布局盒的上边（**缩放前**的 CSS top） */\n  top: number;\n  /** 缩放后的视觉高度 */\n  height: number;\n  /** 缩放系数，配合 transform-origin: 50% 100% */\n  scale: number;\n  centerY: number;\n} {\n  // 徽章容器的设计尺寸（Template 里 TopicVisual 的外框高度）\n  const BOX = 470;\n  const height = SUBJECT_BAND * SHOT_FILL.close;\n  return {\n    top: STAGE.groundY - BOX,\n    height,\n    scale: height / BOX,\n    centerY: STAGE.groundY - height / 2,\n  };\n}\n"
  },
  {
    "path": "character/setpiece.ts",
    "content": "/**\n * 布景注册表（setpiece）：角色能接触的东西，几何只有一份\n *\n * 为什么要有这个文件：\n *\n *   - 二维的梯子写在 Puppet2D 里、三维的滑梯写在 ThreeActionStage 里，同一个\n *     \"梯子\"两处各有一套立杆间距、横档起点、顶端余量。改一处另一处不知道，\n *     于是\"爬\"和\"滑\"看起来像两个世界的规则。\n *   - 更直接的后果是取景：要保证\"主体不越界\"，渲染层必须知道\"这一幕最高的\n *     东西有多高\"。以前这个高度是各自估的（2D 写死 1.55 上限、3D 写死 z=8），\n *     估错的直接表现就是梯子顶进标题胶囊。\n *\n * 这里的职责边界很窄：**只回答几何问题**（多高、横档多密、接触面在哪、\n * 占世界上哪一块）。不画东西、不读 frame、不做插值——渲染器各自把数字翻译\n * 成 SVG 或 mesh。\n *\n * 两条规则，新增布景必须遵守（测试里有守卫）：\n *  1. **尺寸从 ACTOR 导出**，不写\"看起来合适\"的独立数字。梯子宽度来自攀爬\n *     握距，握距来自身宽——同一套数字既决定手摆在哪，也决定杆立在哪。\n *  2. **必须提供 bounds()**。取景只吃包围盒，漏报的布景会被裁掉或压在边上。\n *\n * 坐标系与 pose.ts 一致：y 向上、地面 y=0、单位是\"角色高度\"的归一化世界单位。\n */\n\nimport { ACTOR, CLIMB, SPEC, SLIDE_SEAT_LIFT } from './pose';\nimport type { Bounds } from './stage-layout';\n\n/* ------------------------------------------------------------------ *\n * 梯子（2D climb 的布景；3D 滑梯自带的爬梯也从这里取参数）\n * ------------------------------------------------------------------ */\n\nexport const LADDER = {\n  /**\n   * 两根立杆到中心的距离。**由攀爬握距反推**，两个渲染器共用同一个宽度：\n   * 以前 2D 用 0.46、3D 用 0.28，同一个梯子两种宽度，因为两组数字各自凭\n   * 手感定；0.92 的世界宽度是角色身宽的 1.5 倍，画出来是一面格子墙。\n   * 现在宽度 = 握距，手刚好落在立杆内侧，比例跟着角色走。\n   */\n  railHalf: ACTOR.gripWidth / 2,\n  /** 首根横档离地：脚底 -0.64、髋部 0.66 时，最下面那根正好在脚下方 0.06 */\n  rungStart: 0.04,\n  /** 横档再密就成了实心板：两倍杆粗是下限，再小手脚塞不进去 */\n  minRungSpacing: 0.058 * 2,\n  /**\n   * 立杆顶端高出\"最后一次握杆\"的距离：至少还要留两阶，否则爬到顶就没有\n   * 可抓的了。由 CLIMB.gripY 导出，不再是一个孤立的 1.25。\n   */\n  topHeadroom: CLIMB.gripY + 2 * CLIMB.step,\n  /** 立杆粗细（世界单位），2D 按缩放乘 */\n  railWidth: 0.058,\n  rungWidthRatio: 0.78,\n  /** 3D 侧视爬梯：杆径、横档长（= 两杆间距，同一把梯子）。\n   *  横档根数与位置**不在这里**——由 ladderRungYs() 按平台高度生成，\n   *  以前这里写死 sideRungs: 5 均匀铺五根，二维却画十几根，同一个梯子\n   *  两种密度，切换渲染器时梯子会整个换一个样子。 */\n  sidePostRadius: 0.05,\n  sideRungRadius: 0.04,\n  sideRungLength: ACTOR.gripWidth,\n} as const;\n\n/**\n * 梯子顶端的世界高度。\n *\n * 注意这里是\"布景高度\"，不是\"角色到达高度\"——两者差 topHeadroom，正是这个差\n * 把梯子顶送进了标题带（角色 1.5 + 头顶 1.01 = 2.51 没事，梯子 2.76 撞上）。\n */\nexport function ladderTopY(climbEndY: number): number {\n  return climbEndY + LADDER.topHeadroom;\n}\n\n/**\n * 爬梯的横档高度列表。\n *\n * 2D 与 3D **必须**用这一份：以前二维按 `CLIMB.step` 画十几根，三维按\n * `sideRungs: 5` 均匀铺五根——同一个梯子两种密度，切换渲染器时梯子会\n * 整个换一个样子。间距必须等于攀爬每上一阶的高度，手脚才落在横档上。\n */\nexport function ladderRungYs(topY: number): number[] {\n  const count = Math.max(2, Math.floor((topY - LADDER.rungStart) / CLIMB.step) + 1);\n  return Array.from({ length: count }, (_, i) => LADDER.rungStart + i * CLIMB.step);\n}\n\n/** 梯子在某处立起来时占据的世界范围（含描边，round cap 多出半个线宽） */\nexport function ladderBounds(x: number, topY: number): Bounds {\n  const half = LADDER.railHalf + LADDER.railWidth / 2;\n  return {\n    minX: x - half,\n    maxX: x + half,\n    minY: 0,\n    maxY: topY + LADDER.railWidth / 2,\n  };\n}\n\n/* ------------------------------------------------------------------ *\n * 滑梯（3D slide 的布景）\n * ------------------------------------------------------------------ */\n\nexport const SLIDE = {\n  /** 滑面厚度 */\n  deckThickness: 0.12,\n  /** 滑面宽度（z 方向） */\n  deckWidth: 1.4,\n  /** 两侧护边 */\n  railHalf: 0.72,\n  railHeight: 0.18,\n  railThickness: 0.1,\n  railLift: 0.09,\n  /** 顶端平台 */\n  platformWidth: 1.6,\n  platformThickness: 0.12,\n  platformInset: 0.75,\n  /** 顶端支柱：只留两根，四根会把左侧糊成栅栏 */\n  topPostRadius: 0.08,\n  topPostInset: 1.2,\n  topPostHalfZ: 0.6,\n  topPostFoot: 0.1,\n  /** 支柱中心下移一点，柱底才不会悬空 */\n  postLift: 0.06,\n  /** 底端支柱：滑道末端离地 0.3，不撑起来就是一块悬空的板 */\n  endPostRadius: 0.07,\n  endPostInset: 0.3,\n  endPostHalfZ: 0.5,\n  endPostFoot: 0.06,\n  /** 爬梯（挂在平台后侧） */\n  ladderInset: 1.5,\n  ladderFoot: 0.12,\n} as const;\n\n/**\n * 滑梯结构的最高点：平台面 + 护边。\n * 平台中心在 start[1] + platformThickness/2，护边再高出 railHeight。\n */\nexport function slideTopY(startY: number): number {\n  return startY + SLIDE.platformThickness + SLIDE.railHeight;\n}\n\n/** 滑道倾角（弧度）。二维画斜板、三维转 mesh、梯子定向都用它，别各算一次。 */\nexport function slideDeckAngle(start: readonly [number, number, number], end: readonly [number, number, number]): number {\n  return Math.atan2(end[1] - start[1], end[0] - start[0]);\n}\n\n/**\n * 爬梯在世界里的 x。\n *\n * 这个位置以前被算了三次：三维 SlideRig 里算一次（start - cos*inset）、\n * 二维梯子用\"动作起点\"当 x、爬梯动作的起点又是注册表写死的 -0.55。\n * 三个值互不相干，于是画面上的梯子和角色手里的梯子可以是两把。\n * 现在只在这里算一次：三维立杆、二维横档、爬梯动作的落点全部取自它。\n */\nexport function slideLadderX(\n  start: readonly [number, number, number],\n  end: readonly [number, number, number],\n): number {\n  return start[0] - Math.cos(slideDeckAngle(start, end)) * SLIDE.ladderInset;\n}\n\n/* ------------------------------------------------------------------ *\n * 内容包围盒\n *\n * 取景唯一需要的东西。算错的后果不是\"画面丑一点\"，而是主体被标题盖住、\n * 布景被切掉半截，所以这里逐项写清楚来源，不留魔法数字。\n *\n * 横向也必须算：滑梯从平台到落点横跨 7.7 个世界单位，只报高度的话取景\n * 会把两侧切掉——这正是\"滑梯贴边\"那次的根因。\n * ------------------------------------------------------------------ */\n\n/** 角色头顶的时间点高度（髋部 + 头顶，含造型缩放） */\nexport function actorHeadTop(rootY: number, scale: number): number {\n  return rootY + (SPEC.headY + SPEC.headR) * scale;\n}\n\ntype Vec3 = readonly [number, number, number];\n\n/**\n * 滑梯整组（滑面 + 护边 + 平台 + 支柱 + 爬梯 + 滑下来的人）占据的世界范围。\n *\n * 每一项都对应渲染器里真实画出来的 mesh，不是估算：护栏的 railLift、支柱\n * 从地面立起到平台、爬梯宽 = 两杆间距。少算一项，取景就会把它裁在边上。\n */\nexport function slideBounds(start: Vec3, end: Vec3, scale = 1): Bounds {\n  const [sx, sy] = start;\n  const [ex, ey] = end;\n  const dx = ex - sx;\n  const dy = ey - sy;\n  const len = Math.sqrt(dx * dx + dy * dy) || 1;\n  const cos = dx / len;\n  const sin = dy / len;\n\n  // 滑面是旋转过的盒子：轴向投影要带上厚度\n  const midX = (sx + ex) / 2;\n  const midY = (sy + ey) / 2;\n  const halfX = (len / 2) * Math.abs(cos) + (SLIDE.deckThickness / 2) * Math.abs(sin);\n  const halfY = (len / 2) * Math.abs(sin) + (SLIDE.deckThickness / 2) * Math.abs(cos);\n\n  let minX = midX - halfX;\n  let maxX = midX + halfX;\n  let minY = 0;\n  let maxY = Math.max(midY + halfY, slideTopY(sy));\n\n  const addBox = (cx: number, cy: number, hx: number, hy: number) => {\n    minX = Math.min(minX, cx - hx);\n    maxX = Math.max(maxX, cx + hx);\n    minY = Math.min(minY, cy - hy);\n    maxY = Math.max(maxY, cy + hy);\n  };\n\n  // 两侧护边：抬高 railLift，自身还高 railHeight\n  addBox(midX, midY + SLIDE.railLift, halfX, halfY + SLIDE.railHeight / 2);\n  // 顶端平台\n  addBox(\n    sx - cos * SLIDE.platformInset,\n    sy + SLIDE.platformThickness / 2,\n    SLIDE.platformWidth / 2,\n    SLIDE.platformThickness / 2,\n  );\n  // 顶端支柱：从地面立起到平台\n  addBox(sx - cos * SLIDE.topPostInset, sy / 2, SLIDE.topPostRadius, sy / 2);\n  // 底端支柱\n  addBox(\n    ex - SLIDE.endPostInset,\n    ey / 2,\n    SLIDE.endPostRadius,\n    Math.max(0.12, ey - SLIDE.endPostFoot) / 2,\n  );\n  // 爬梯：横向半宽 = 横档长的一半（两杆正立在这两个位置）\n  addBox(sx - cos * SLIDE.ladderInset, sy / 2, LADDER.sideRungLength / 2, sy / 2);\n\n  // 平台上坐着的角色比结构还高；滑到底站起来还要往前迈一步\n  const seated = actorHeadTop(sy + SLIDE_SEAT_LIFT, scale);\n  const standing = actorHeadTop(Math.max(ey, SPEC.standHipY), scale);\n  maxY = Math.max(maxY, seated, standing);\n  const standX = ex + 0.8;\n  maxX = Math.max(maxX, standX + (ACTOR.bodyWidth / 2) * scale);\n  minX = Math.min(minX, standX - (ACTOR.bodyWidth / 2) * scale);\n\n  return { minX, maxX, minY, maxY };\n}\n\n/** 滑梯幕：必须完整可见的世界高度（= 包围盒高度） */\nexport function slideWorldHeight(start: Vec3, end: Vec3, scale: number): number {\n  return slideBounds(start, end, scale).maxY;\n}\n"
  },
  {
    "path": "character/venue-recipes.ts",
    "content": "/**\n * 场地配方（venue recipes）：**场景是数据，不是代码**。\n *\n * 这里回答\"这个场地长什么样\"，`WorldLayer.tsx` 只回答\"每一层怎么画\"。\n * 两者分开之后，加一处场地 = 加一份配方；只有加一种**新的渲染原语**\n * （比如水面）才需要动渲染器，而原语是有限的。\n *\n * 为什么要这么分：\n *   以前 `WorldLayer` 里同时写着\"层\"（天空/地面/装饰）和\"具体场地\"\n *   （摩天轮只在 playground、沙坑在 playground 和 riverside），于是每加一处\n *   场地都要改 4 个文件（类型 / 配色 / 装饰 / JSX），而且没有任何东西会提醒\n *   你\"漏了一层\"。场地内容会无限增长，不该由代码枚举。\n *\n * 配方的两条硬规则（`normalizeRecipe` 会检查）：\n *   1. 必须有 `ground` 层——没有地面，角色就悬在半空，这是唯一\"缺了必然出\n *      画面事故\"的层；\n *   2. `world` 坐标层禁止出现像素值。一旦允许像素坐标，背景就又变回\"贴在\n *      后面的屏保\"，和角色不在同一个空间——那正是上一次修掉的问题。\n *\n * 坐标空间只有两种：\n *   `screen` —— 天空、太阳、云。它们不随镜头平移（那是\"天\"）。\n *   `world`  —— 其余全部。由 camera 的 ppu / originX 投影，跟角色同一把尺。\n */\n\n/* ------------------------------------------------------------------ *\n * 配色\n * ------------------------------------------------------------------ */\n\nexport type VenueTheme = {\n  skyTop: string;\n  skyBottom: string;\n  sun: string;\n  cloud: string;\n  hillFar: string;\n  hillNear: string;\n  ground: string;\n  groundTop: string;\n  path: string;\n  wood: string;\n  woodDark: string;\n  metal: string;\n  leaf: string;\n  leafDark: string;\n  /** 水面颜色。没有水的场地不写，`water` 层会退回 hillNear */\n  water?: string;\n};\n\n/**\n * 配色仍按场地给，但**不再是白名单**：配方自带 `theme`，没登记的场地也放得进。\n * 键是开放字符串，理由同 `VENUE_RECIPES`。\n */\nexport const VENUE_THEMES: Record<string, VenueTheme> = {\n  playground: {\n    skyTop: '#a9e4ff',\n    skyBottom: '#e8f7ff',\n    sun: '#ffd76a',\n    cloud: '#ffffff',\n    hillFar: '#b7e3c6',\n    hillNear: '#96d6ae',\n    ground: '#8ed47a',\n    groundTop: '#a6df8e',\n    path: '#e9d3a8',\n    wood: '#c98a5a',\n    woodDark: '#8d5524',\n    metal: '#9fb3c8',\n    leaf: '#57b96a',\n    leafDark: '#3e8f52',\n  },\n  meadow: {\n    skyTop: '#bfeaff',\n    skyBottom: '#f0f9ff',\n    sun: '#ffe08a',\n    cloud: '#ffffff',\n    hillFar: '#c6e8c9',\n    hillNear: '#a4d9ab',\n    ground: '#8ed47a',\n    groundTop: '#a9e094',\n    path: '#e6d2ac',\n    wood: '#c08b5c',\n    woodDark: '#8a5a2f',\n    metal: '#a8b8c6',\n    leaf: '#5bbb6c',\n    leafDark: '#41904f',\n  },\n  riverside: {\n    skyTop: '#a7e8ff',\n    skyBottom: '#eaf9ff',\n    sun: '#ffdf85',\n    cloud: '#ffffff',\n    hillFar: '#a9dcc2',\n    hillNear: '#8ecfae',\n    ground: '#7fc97a',\n    groundTop: '#95d78c',\n    path: '#d9c39b',\n    wood: '#bb8a5e',\n    woodDark: '#84562f',\n    metal: '#9fb3c8',\n    leaf: '#55b46a',\n    leafDark: '#3d8a4e',\n  },\n  forest: {\n    skyTop: '#bfe6ff',\n    skyBottom: '#eef9ff',\n    sun: '#ffe08a',\n    cloud: '#ffffff',\n    hillFar: '#a8d6bd',\n    hillNear: '#87c4a1',\n    ground: '#79c073',\n    groundTop: '#8ed083',\n    path: '#cdb894',\n    wood: '#b98456',\n    woodDark: '#7d5029',\n    metal: '#9aa9b8',\n    leaf: '#4faf63',\n    leafDark: '#357a46',\n  },\n  night: {\n    skyTop: '#13233f',\n    skyBottom: '#29456f',\n    sun: '#f2f0d8',\n    cloud: '#3a5170',\n    hillFar: '#22384f',\n    hillNear: '#1b2d40',\n    ground: '#2c4636',\n    groundTop: '#35533f',\n    path: '#3d4a3f',\n    wood: '#6f523c',\n    woodDark: '#4a3527',\n    metal: '#7d8b99',\n    leaf: '#2f5c41',\n    leafDark: '#234631',\n  },\n};\n\n/* ------------------------------------------------------------------ *\n * 图层\n * ------------------------------------------------------------------ */\n\n/**\n * 渲染原语。**这是唯一可以枚举的东西**，而且它不会随题材增长：\n * 户外与室内都能用这 6 种描述完（室内 = 纯色 backdrop + 地板 + 墙/家具装饰）。\n */\nexport type LayerKind = 'sky' | 'horizon' | 'ground' | 'water' | 'fence' | 'decor';\n\n/** 装饰资产 id。开放字符串：加资产只写组件 + 注册一行 */\nexport type DecorAssetId = string;\n\nexport type DecorItem = {\n  asset: DecorAssetId;\n  /** 世界坐标 x（不是像素） */\n  x: number;\n  /** 整体透明度，缺省 1 */\n  opacity?: number;\n  /**\n   * 资产私有参数（墙高、水宽、灯高……），由资产自己解释。\n   * 例如 `{ asset: 'wall', x: 0, params: { height: 3.2, from: -12, to: 12 } }`\n   */\n  params?: Record<string, number | string>;\n};\n\nexport type SkyLayer = {\n  kind: 'sky';\n  /**\n   * `gradient`（户外天空）或 `solid`（室内：用 theme.skyTop 铺满）。\n   * 室内没有\"天空\"，所以太阳与云必须是可选的——缺了太阳云，这一层就是一块\n   * 纯色背景，不叫 sky 也不影响它工作。\n   */\n  fill?: 'gradient' | 'solid';\n  sun?: { x: number; y: number; r: number; glowR: number };\n  clouds?: { x: number; y: number; s: number }[];\n};\n\nexport type HorizonLayer = {\n  kind: 'horizon';\n  hills: { x: number; r: number; tone: 'far' | 'near' }[];\n};\n\nexport type GroundPatch =\n  /** 滑梯脚下的土地。`when: 'slide'` ⇒ 只有这一幕有滑梯时才画 */\n  | { asset: 'dirtPatch'; when: 'slide'; rx: number; ry: number; opacity: number }\n  /** 草簇：确定性按索引摆（不用随机），重渲逐像素一致 */\n  | { asset: 'tuft'; from: number; count: number; step: number };\n\nexport type GroundLayer = {\n  kind: 'ground';\n  /** 地面材质语义（渲染只看 theme，这个字段给未来区分草地/地板/沙地留口） */\n  asset: 'grass' | 'floor' | 'sand';\n  /** 上沿那条把\"地面\"和\"空气\"分开的浅色边，室内一般给 0 */\n  topBand: number;\n  /** 贴在地面上的附加元素，**数组顺序 = 绘制顺序**：先沙地椭圆，再草簇 */\n  patches?: GroundPatch[];\n};\n\nexport type WaterLayer = {\n  kind: 'water';\n  from: number;\n  to: number;\n  /** 水面上沿的世界 y（略高于 0 才是\"远处的水\"，等于 0 就成了脚边水坑） */\n  surfaceY: number;\n  /** 水带高度（世界单位） */\n  depth: number;\n  opacity?: number;\n};\n\nexport type FenceLayer = {\n  kind: 'fence';\n  from: number;\n  posts: number;\n  spacing: number;\n  /** 横杆跨度（不等于 posts 覆盖范围，历史上就是 20） */\n  railSpan: number;\n  railYs: number[];\n  postHeight: number;\n  postWidth: number;\n  railHeight: number;\n};\n\nexport type DecorLayer = { kind: 'decor'; items: DecorItem[] };\n\nexport type LayerSpec =\n  | SkyLayer\n  | HorizonLayer\n  | GroundLayer\n  | WaterLayer\n  | FenceLayer\n  | DecorLayer;\n\nexport type VenueRecipe = {\n  /** 配方 id。**开放字符串**，不是字面量联合 */\n  id: string;\n  theme: VenueTheme;\n  /** 数组顺序 = 绘制顺序 = 遮挡顺序。同一 kind 可以出现多次（见 playground 的 wheel 与 fence） */\n  layers: LayerSpec[];\n};\n\n/* ------------------------------------------------------------------ *\n * 配方\n * ------------------------------------------------------------------ */\n\n/**\n * 内置场地。**这不是类型来源**，只是\"回归基线清单\"：测试要求这里每一个都\n * 有配方，反过来不要求——加新场地不需要动这个数组。\n */\nexport const BUILTIN_VENUES: readonly string[] = [\n  'playground',\n  'meadow',\n  'riverside',\n  'forest',\n  'night',\n];\n\n/** 兜底场地：未知 id 落到这里，宁可画面普通，也不要空白 */\nexport const DEFAULT_VENUE = 'meadow';\n\n/**\n * 户外共用的天空与远山。\n *\n * 抽成常量不是为了省字节，而是为了让\"这一处场地和那一处看起来是同一片天\"\n * 变成结构性的：改天空只改一处，所有户外场地一起变。\n */\nconst OUTDOOR_SKY: SkyLayer = {\n  kind: 'sky',\n  fill: 'gradient',\n  sun: { x: 1560, y: 230, r: 78, glowR: 210 },\n  clouds: [\n    { x: 320, y: 200, s: 1 },\n    { x: 980, y: 150, s: 0.75 },\n    { x: 1420, y: 300, s: 0.55 },\n  ],\n};\n\nconst OUTDOOR_HILLS: HorizonLayer = {\n  kind: 'horizon',\n  hills: [\n    { x: -1.5, r: 6.2, tone: 'far' },\n    { x: 6.5, r: 5.4, tone: 'far' },\n    { x: 2.4, r: 4.4, tone: 'near' },\n  ],\n};\n\n/** 草地 + 草簇。滑梯脚下的沙地在有滑梯时由渲染器补 x（它属于滑梯，不属于场地） */\nconst GRASS_GROUND: GroundLayer = {\n  kind: 'ground',\n  asset: 'grass',\n  topBand: 0.055,\n  patches: [\n    { asset: 'dirtPatch', when: 'slide', rx: 2.9, ry: 0.3, opacity: 0.55 },\n    { asset: 'tuft', from: -3.4, count: 34, step: 0.42 },\n  ],\n};\n\n/** 游乐园/牧场那种横贯全画面的木栅栏 */\nconst PADDOCK_FENCE: FenceLayer = {\n  kind: 'fence',\n  from: -9,\n  posts: 34,\n  spacing: 0.62,\n  railSpan: 20,\n  railYs: [0.24, 0.46],\n  postHeight: 0.58,\n  postWidth: 0.09,\n  railHeight: 0.07,\n};\n\nexport const VENUE_RECIPES: Record<string, VenueRecipe> = {\n  /**\n   * 游乐园。\n   *\n   * 两个顺序细节来自旧实现，不能\"整理\"：\n   *  - 摩天轮画在**围栏之前**：围栏要挡住轮子的斜撑，否则两根斜柱横在草地上\n   *    像脚手架，把\"远景\"读成\"前景障碍物\"；\n   *  - 树先于长椅、长椅先于沙坑：它们之间的遮挡关系写在这个数组里。\n   *\n   * 这也是为什么 `layers` 允许 `decor` 出现两次——摩天轮必须在 fence 之前，\n   * 其余装饰在之后。按 kind 分组的写法表达不了这件事。\n   */\n  playground: {\n    id: 'playground',\n    theme: VENUE_THEMES.playground,\n    layers: [\n      OUTDOOR_SKY,\n      OUTDOOR_HILLS,\n      GRASS_GROUND,\n      { kind: 'decor', items: [{ asset: 'wheel', x: 3.4, opacity: 0.42 }] },\n      PADDOCK_FENCE,\n      {\n        kind: 'decor',\n        items: [\n          { asset: 'tree', x: -3.2 },\n          { asset: 'tree', x: 6.6 },\n          { asset: 'tree', x: 8.2 },\n          { asset: 'bench', x: 5.6 },\n          { asset: 'sandbox', x: -2.6 },\n        ],\n      },\n    ],\n  },\n\n  meadow: {\n    id: 'meadow',\n    theme: VENUE_THEMES.meadow,\n    layers: [\n      OUTDOOR_SKY,\n      OUTDOOR_HILLS,\n      GRASS_GROUND,\n      PADDOCK_FENCE,\n      {\n        kind: 'decor',\n        items: [\n          { asset: 'tree', x: -3.2 },\n          { asset: 'tree', x: 6.6 },\n          { asset: 'tree', x: 8.2 },\n          { asset: 'bench', x: 5.6 },\n        ],\n      },\n    ],\n  },\n\n  /**\n   * 河边。现在**还没有水**（旧实现的 riverside 只是\"带沙坑的草地\"），\n   * 水面是独立一步加进来的：它是新原语，配方里加一行 `water` 即可。\n   */\n  riverside: {\n    id: 'riverside',\n    theme: VENUE_THEMES.riverside,\n    layers: [\n      OUTDOOR_SKY,\n      OUTDOOR_HILLS,\n      GRASS_GROUND,\n      PADDOCK_FENCE,\n      {\n        kind: 'decor',\n        items: [\n          { asset: 'tree', x: -3.2 },\n          { asset: 'tree', x: 6.6 },\n          { asset: 'tree', x: 8.2 },\n          { asset: 'bench', x: 5.6 },\n          { asset: 'sandbox', x: -2.6 },\n        ],\n      },\n    ],\n  },\n\n  /**\n   * 森林/夜晚：没有围栏。围栏是游乐园/牧场的语汇，森林里画一条横贯全画面的\n   * 木栅栏就变成\"一个有围栏的空地\"。两侧改由树与灌木填住，否则镜头一平移\n   * 就是一块空地。\n   */\n  forest: {\n    id: 'forest',\n    theme: VENUE_THEMES.forest,\n    layers: [\n      OUTDOOR_SKY,\n      OUTDOOR_HILLS,\n      GRASS_GROUND,\n      {\n        kind: 'decor',\n        items: [\n          { asset: 'bush', x: -1.6 },\n          { asset: 'bush', x: 4.4 },\n          { asset: 'bush', x: 9.4 },\n          { asset: 'tree', x: -3.2 },\n          { asset: 'tree', x: 6.6 },\n          { asset: 'tree', x: 8.2 },\n          { asset: 'tree', x: -5.4 },\n          { asset: 'tree', x: -7.2 },\n          { asset: 'tree', x: 10.4 },\n          { asset: 'bench', x: 5.6 },\n        ],\n      },\n    ],\n  },\n\n  night: {\n    id: 'night',\n    theme: VENUE_THEMES.night,\n    layers: [\n      OUTDOOR_SKY,\n      OUTDOOR_HILLS,\n      GRASS_GROUND,\n      {\n        kind: 'decor',\n        items: [\n          { asset: 'bush', x: -1.6 },\n          { asset: 'bush', x: 4.4 },\n          { asset: 'bush', x: 9.4 },\n          { asset: 'tree', x: -3.2 },\n          { asset: 'tree', x: 6.6 },\n          { asset: 'tree', x: 8.2 },\n          { asset: 'tree', x: -5.4 },\n          { asset: 'tree', x: -7.2 },\n          { asset: 'tree', x: 10.4 },\n          { asset: 'bench', x: 5.6 },\n        ],\n      },\n    ],\n  },\n};\n\n/**\n * 已知装饰资产清单。\n *\n * 与 `venue-assets.tsx` 的注册表是两处，但测试会断言\"注册表覆盖这张表\"，\n * 所以漏注册会红。放在数据文件里是因为配方校验（`normalizeRecipe`）需要它，\n * 而数据文件不能 import tsx。\n */\nexport const DECOR_ASSET_IDS: readonly string[] = [\n  'tree',\n  'bush',\n  'bench',\n  'sandbox',\n  'wheel',\n  'wall',\n  'floor',\n  'desk',\n  'lamp',\n  'shelf',\n];\n\n/* ------------------------------------------------------------------ *\n * 取用与校验\n * ------------------------------------------------------------------ */\n\nconst warned = new Set<string>();\n\n/**\n * 取配方。未知 id 回落 `meadow` 并**警告一次**。\n *\n * 静默回落是\"场地悄悄缩水\"的来源：少画一层，画面照样出得来，没人会发现，\n * 直到某一节课看起来莫名其妙地空。拼错的 id 必须留一条日志。\n */\nexport function venueRecipe(venue: string): VenueRecipe {\n  const recipe = VENUE_RECIPES[venue];\n  if (recipe) return recipe;\n  if (!warned.has(venue)) {\n    warned.add(venue);\n    // eslint-disable-next-line no-console\n    console.warn(`[venue] 未登记的场地 \"${venue}\"，回落到 ${DEFAULT_VENUE}`);\n  }\n  return VENUE_RECIPES[DEFAULT_VENUE];\n}\n\n/** 像素坐标字段名。世界层出现这些，说明有人又把背景写回了屏幕空间 */\nconst PIXEL_KEYS = new Set(['px', 'py', 'left', 'top', 'widthPx', 'heightPx']);\n\nexport type RecipeIssue =\n  | { kind: 'missing-ground' }\n  | { kind: 'pixel-coordinate'; path: string }\n  | { kind: 'unknown-asset'; path: string; asset: string }\n  | { kind: 'bad-layer'; path: string };\n\n/**\n * 配方校验。\n *\n * 三条规则对应三种真实事故：\n *  - 没有 ground：角色悬空；\n *  - 世界层出现像素坐标：背景变回\"贴在后面的屏保\"，比例对不上；\n *  - 未知 asset：静默跳过 ⇒ 某一侧空掉。\n *\n * 返回问题清单而不是直接抛，是为了让调用方决定\"开发期抛 / 运行期降级 + warn\"。\n */\nexport function normalizeRecipe(raw: unknown, path = 'recipe'): RecipeIssue[] {\n  const issues: RecipeIssue[] = [];\n  if (!raw || typeof raw !== 'object') return [{ kind: 'bad-layer', path }];\n\n  const recipe = raw as Partial<VenueRecipe>;\n  const layers = Array.isArray(recipe.layers) ? recipe.layers : [];\n  if (!layers.some((layer) => layer && layer.kind === 'ground')) {\n    issues.push({ kind: 'missing-ground' });\n  }\n\n  layers.forEach((layer, i) => {\n    const at = `${path}.layers[${i}]`;\n    if (!layer || typeof layer !== 'object' || typeof layer.kind !== 'string') {\n      issues.push({ kind: 'bad-layer', path: at });\n      return;\n    }\n    scanPixels(layer, at, issues);\n    if (layer.kind === 'decor') {\n      const items = (layer as DecorLayer).items;\n      if (!Array.isArray(items)) {\n        issues.push({ kind: 'bad-layer', path: `${at}.items` });\n        return;\n      }\n      items.forEach((item, j) => {\n        if (!item || typeof item.asset !== 'string') {\n          issues.push({ kind: 'bad-layer', path: `${at}.items[${j}]` });\n          return;\n        }\n        if (!DECOR_ASSET_IDS.includes(item.asset)) {\n          issues.push({ kind: 'unknown-asset', path: `${at}.items[${j}]`, asset: item.asset });\n        }\n      });\n    }\n  });\n\n  return issues;\n}\n\nfunction scanPixels(value: unknown, path: string, issues: RecipeIssue[]): void {\n  if (!value || typeof value !== 'object') return;\n  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {\n    if (PIXEL_KEYS.has(key)) issues.push({ kind: 'pixel-coordinate', path: `${path}.${key}` });\n    if (child && typeof child === 'object') scanPixels(child, `${path}.${key}`, issues);\n  }\n}\n"
  },
  {
    "path": "character/world.ts",
    "content": "/**\r\n * 场地层（world）：整节课共用的一个\"地方\"\r\n *\r\n * 为什么需要它——上一版每一幕都是一个独立的立体模型：\r\n *\r\n *   - 取景按\"这一幕自己装得下\"算缩放，于是滑梯幕的角色被推远、说话幕的角色\r\n *     被拉近，同一个角色在不同幕里忽大忽小；滑梯与小熊的比例也跟着幕变化。\r\n *   - 布景只在需要它的那一幕出现：爬梯子时画一把孤零零的梯子，梯子后面\r\n *     没有平台、没有滑道、没有公园——因为\"梯子\"是这一幕的道具，不是世界里的东西。\r\n *   - 背景是按 habitat 画的一张屏保（太阳、云、一排树），它不跟着镜头动，\r\n *     也不参与世界坐标，所以永远只是\"贴在后面的图\"。\r\n *\r\n * 这里的做法是把\"世界\"和\"镜头\"分开：\r\n *\r\n *   世界：一处场地 + 一组固定装置（滑梯含爬梯与平台、沙坑、长椅、围栏、树、\r\n *         远处的摩天轮）。位置是绝对的，整节课不变。\r\n *   镜头：**一个基准缩放 + 有限变焦 + 平移**。基准缩放由\"整个世界里最高的\r\n *         装置\"算出，整节课只算一次；变焦只允许 1.0~1.5 倍，所有世界物体\r\n *         一起缩放，所以任何一幕里\"熊与滑梯的比例\"都是同一个值。\r\n *\r\n * 这条分工是本次修复的核心：**比例一致性不是靠每幕拟合，而是靠世界只定义一次**。\r\n * 装不下时不再缩小世界（那会改变比例），而是选择更大的景别或让画面裁掉边缘——\r\n * 就像真实拍摄里镜头不会因为道具太高就把整个世界缩小。\r\n *\r\n * 坐标系与 pose.ts 一致：y 向上、地面 y=0、单位 = 角色身高（1.67）。\r\n */\r\n\r\nimport { ACTOR } from './pose';\r\nimport { slideBounds, slideLadderX } from './setpiece';\r\nimport { BUILTIN_VENUES, VENUE_RECIPES, venueRecipe } from './venue-recipes';\r\nimport {\r\n  CAMERA_FOV,\r\n  SAFE_X,\r\n  STAGE,\r\n  SUBJECT_BAND,\r\n  boundsCenterX,\r\n  unionAll,\r\n  type Bounds,\r\n  type Shot,\r\n} from './stage-layout';\r\n\r\nexport type Tri3 = readonly [number, number, number];\r\n\r\n/**\r\n * 场地 id。\r\n *\r\n * **开放字符串，不是字面量联合**。场地是内容，会无限增长；用联合类型等于让\r\n * 类型系统替内容做白名单——每加一处场地都要改类型定义，\"零改代码\"就断了。\r\n * 换来的类型安全由 `normalizeRecipe` + 遍历 `Object.keys(VENUE_RECIPES)` 的\r\n * 全量测试补，覆盖面比编译期穷举更全。\r\n */\r\nexport type Venue = string;\r\n\r\n/**\r\n * 内置场地清单。**不再是类型来源**，只是\"回归基线\"：测试要求这里每一个都有\r\n * 配方，反过来不要求——加新场地不需要动这个数组。\r\n */\r\nexport const VENUES: readonly Venue[] = BUILTIN_VENUES;\r\n\r\n/**\r\n * 世界里的一处滑梯：平台（start）到滑道末端（end）。\r\n *\r\n * 爬梯不单独存在——它挂在 platform 后方（见 setpiece.slideLadderX）。\r\n * 这就是\"梯子必须和游乐园结合\"的结构性回答：**梯子是滑梯的一部分**，\r\n * 谁画滑梯谁画梯子，位置由同一个函数给出，不可能分开。\r\n */\r\nexport type WorldSlide = { start: Tri3; end: Tri3 };\r\n\r\nexport type WorldView = {\r\n  venue: Venue;\r\n  /** 本节课里有滑梯（爬 / 滑 / 提到滑梯）时给出。整节课只定义一次。 */\r\n  slide?: WorldSlide;\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 场地配色与配方\r\n *\r\n * 数据全部在 `venue-recipes.ts`：这里只做转发，保持旧调用点（测试、模板）\r\n * 的 import 路径不变。加场地不需要动这个文件。\r\n * ------------------------------------------------------------------ */\r\n\r\nexport { VENUE_THEMES } from './venue-recipes';\r\nexport type { VenueRecipe, VenueTheme } from './venue-recipes';\r\nexport { VENUE_RECIPES };\r\n\r\nexport function venueFromHabitat(habitat?: string): Venue {\r\n  const value = String(habitat || '').trim().toLowerCase();\r\n  return VENUE_RECIPES[value] ? value : 'meadow';\r\n}\r\n\r\n/**\r\n * 渲染层对 world 的校验。\r\n *\r\n * props 来自 JSON（后端生成 / 旧任务缓存），可能整份缺失、坐标可能是字符串。\r\n * 任一必需项不合法就返回 null，让调用方退回\"按幕取景\"的旧路径——\r\n * 宁可画面普通，也不要带着 NaN 去投影（整块 transform 变 NaN 的画面是空白的）。\r\n */\r\nexport function normalizeWorld(raw: unknown): WorldView | null {\r\n  if (!raw || typeof raw !== 'object') return null;\r\n  const source = raw as Record<string, unknown>;\r\n  const venue = venueFromHabitat(String(source.venue ?? ''));\r\n  const slideRaw = source.slide as Record<string, unknown> | undefined;\r\n  const slide = slideRaw ? toSlide(slideRaw) : null;\r\n  if (!slide) return { venue };\r\n  return { venue, slide };\r\n}\r\n\r\nfunction toSlide(raw: Record<string, unknown>): WorldSlide | null {\r\n  const start = toTri(raw.start);\r\n  const end = toTri(raw.end);\r\n  if (!start || !end) return null;\r\n  // 滑梯必须向下向右：方向反了会让滑面朝天、支撑柱穿到地面以上\r\n  if (end[1] >= start[1]) return null;\r\n  return { start, end };\r\n}\r\n\r\nfunction toTri(value: unknown): [number, number, number] | null {\r\n  if (!Array.isArray(value) || value.length !== 3) return null;\r\n  const nums = value.map((n) => Number(n));\r\n  if (nums.some((n) => !Number.isFinite(n) || Math.abs(n) > 100)) return null;\r\n  return [nums[0], nums[1], nums[2]];\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 可演区域\r\n *\r\n * 取景只需要一个盒：这个世界里\"必须完整可见\"的范围。刻意**不含**装饰\r\n * （围栏、树、摩天轮）——它们是远景，允许被裁。把它们算进来会让基准缩放\r\n * 被一整座公园拉到很小，角色变成米粒。\r\n * ------------------------------------------------------------------ */\r\n\r\n/** 没有滑梯的场地：一段可走的草地 + 一个站在里面的人 */\r\nconst OPEN_VENUE_BOUNDS: Bounds = {\r\n  minX: -3.1,\r\n  maxX: 3.1,\r\n  minY: 0,\r\n  maxY: (ACTOR.standHeight * 1.24),\r\n};\r\n\r\nexport function worldBounds(world: WorldView): Bounds {\r\n  if (!world.slide) return OPEN_VENUE_BOUNDS;\r\n  return unionAll([slideBounds(world.slide.start, world.slide.end, 1), OPEN_VENUE_BOUNDS]);\r\n}\r\n\r\n/**\r\n * 基准缩放（px / 世界单位）：**整节课只算一次，任何一幕都不许改**。\r\n *\r\n * 两个约束取小：\r\n *  - 纵向：可演区域的顶端不能越过标题带（顶部留 10px 给描边）；\r\n *  - 横向：可演区域要装得下，两侧各留 SAFE_X。\r\n *\r\n * 这是\"比例一致\"的唯一来源。以前这段计算在每一幕里各算一次，输入是\"这一幕\r\n * 自己装了多大东西\"，所以同一只熊在滑梯幕 360px、在说话幕 437px。\r\n */\r\nexport function worldScale(world: WorldView): number {\r\n  const box = worldBounds(world);\r\n  const height = Math.max(0.4, box.maxY - box.minY);\r\n  const width = Math.max(0.4, box.maxX - box.minX);\r\n  const byHeight = (SUBJECT_BAND - 10) / height;\r\n  const byWidth = (STAGE.width - 2 * SAFE_X) / width;\r\n  return Math.min(byHeight, byWidth);\r\n}\r\n\r\n/**\r\n * 景别 = 在基准缩放上乘一个镜头焦距系数。\r\n *\r\n * 关键：它作用于**整个世界**（角色、滑梯、树、摩天轮一起放大），所以\r\n * 变焦不会改变任何两个物体的比例——那正是上一版\"滑梯和小熊对不上\"的成因。\r\n * 1.5 封顶：再大就只剩一张脸，孩子看不出\"他在哪儿\"。\r\n */\r\nexport const SHOT_ZOOM: Record<Shot, number> = { wide: 1, medium: 1.18, close: 1.5 };\r\n\r\nexport type WorldCamera = {\r\n  shot: Shot;\r\n  /** 每世界单位多少像素 */\r\n  ppu: number;\r\n  groundY: number;\r\n  /** 世界原点（x=0）落在屏幕第几列：投影 = originX + x*ppu */\r\n  originX: number;\r\n  /** 镜头对准的世界 x（三维相机 lookX 用同一个值） */\r\n  focusX: number;\r\n  camera: { fov: number; z: number; lookY: number; lookX: number; focal: number };\r\n};\r\n\r\n/**\r\n * 镜头：**基准缩放 × 景别变焦**，按\"这一幕要装的东西\"取景。\r\n *\r\n * 三段取值，顺序就是这条规则的语义：\r\n *\r\n *   fit = 让 focusBox（角色 + 他正在用的装置）**完整装进画面**所需的缩放；\r\n *   ppu = clamp(fit, 基准缩放, 基准缩放 × 景别焦距)\r\n *\r\n *  - 下限 = 基准缩放：这是\"整个场地装得下\"的缩放。低于它就等于把世界缩小，\r\n *    比例会变——所以永远不越过它。\r\n *  - 上限 = 基准缩放 × 焦距：不允许为了拍一张脸把镜头推到 3 倍。孩子需要\r\n *    看清楚\"他在公园的哪里\"。\r\n *  - 中间取 fit：一幕里东西多（角色 + 滑梯）就退到基准缩放，只有角色时就\r\n *    稍微推近一点。两者差 18%~50%，但**所有物体同乘一个 ppu**，\r\n *    所以熊与滑梯的比例在任何一幕都相同。\r\n *\r\n * 焦点按 focusBox 中心，并夹在场地范围内——镜头可以跟着角色走过公园，\r\n * 但不会走出公园。\r\n */\r\nexport function cameraForWorld(\r\n  world: WorldView,\r\n  shot: Shot,\r\n  focusBox?: Bounds,\r\n): WorldCamera {\r\n  const base = worldScale(world);\r\n  const zoom = SHOT_ZOOM[shot];\r\n  const box = worldBounds(world);\r\n  const focus = isUsableBox(focusBox) ? focusBox : box;\r\n\r\n  const height = Math.max(0.4, focus.maxY - focus.minY);\r\n  const width = Math.max(0.4, focus.maxX - focus.minX);\r\n  // 与 worldScale 同一把尺：纵向避开标题带，横向两侧各留 SAFE_X\r\n  const fit = Math.min((SUBJECT_BAND - 10) / height, (STAGE.width - 2 * SAFE_X) / width);\r\n  const ppu = Math.min(base * zoom, Math.max(base, fit));\r\n\r\n  const targetX = Math.min(box.maxX, Math.max(box.minX, boundsCenterX(focus)));\r\n  const tanHalf = Math.tan((CAMERA_FOV * Math.PI) / 360);\r\n  return {\r\n    shot,\r\n    ppu,\r\n    groundY: STAGE.groundY,\r\n    originX: STAGE.centerX - targetX * ppu,\r\n    focusX: targetX,\r\n    camera: {\r\n      fov: CAMERA_FOV,\r\n      z: STAGE.height / (2 * ppu * tanHalf),\r\n      lookY: (STAGE.groundY - STAGE.height / 2) / ppu,\r\n      lookX: targetX,\r\n      focal: zoom,\r\n    },\r\n  };\r\n}\r\n\r\n/** 包围盒是否可用：空盒（±Infinity）与 NaN 都不能拿去算中心 */\r\nfunction isUsableBox(box?: Bounds): box is Bounds {\r\n  return (\r\n    !!box &&\r\n    Number.isFinite(box.minX) &&\r\n    Number.isFinite(box.maxX) &&\r\n    Number.isFinite(box.maxY) &&\r\n    box.maxX > box.minX\r\n  );\r\n}\r\n\r\n/** 与 stage-layout 共用同一个 FOV：相机公式只写一处，2D/3D 才可能落在同一位置 */\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 世界里的固定装置（装饰 + 可交互）\r\n *\r\n * 坐标是绝对的。不同幕之间的连续性来自\"它们一直在那儿\"，而不是来自\r\n * 每幕重新摆一遍——这正是\"局部场景\"与\"一个地方\"的区别。\r\n * ------------------------------------------------------------------ */\r\n\r\nexport type Decor = { kind: 'tree' | 'fence' | 'bench' | 'sandbox' | 'wheel' | 'bush'; x: number };\r\n\r\n/**\r\n * 这处场地有没有围栏。\r\n *\r\n * 围栏是**游乐园/牧场**的语汇，不是所有户外的语汇。上一版无条件画一条横贯\r\n * 全画面的木栅栏，于是\"森林里的小松鼠\"也站在一道公园围栏后面——场地词汇\r\n * 和主题对不上时，孩子读到的不是\"森林\"，是\"一个有围栏的空地\"。\r\n */\r\nexport function venueHasFence(venue: Venue): boolean {\r\n  return venueRecipe(venue).layers.some((layer) => layer.kind === 'fence');\r\n}\r\n\r\n/**\r\n * 装饰布局。\r\n *\r\n * **从配方派生**，不再在这里用 if 判断场地。这样\"森林没有围栏\"\"游乐园有摩天轮\"\r\n * 这类断言自动变成\"对配方的断言\"——测试不用重写，而且以后加场地时它会继续守着。\r\n *\r\n * 只用固定值，不用随机：同一节课重渲必须逐像素一致（Remotion 的硬要求）。\r\n */\r\nexport function venueDecor(world: WorldView): Decor[] {\r\n  const decor: Decor[] = [];\r\n  for (const layer of venueRecipe(world.venue).layers) {\r\n    if (layer.kind !== 'decor') continue;\r\n    for (const item of layer.items) {\r\n      if ((DECOR_KINDS as readonly string[]).includes(item.asset)) {\r\n        decor.push({ kind: item.asset as Decor['kind'], x: item.x });\r\n      }\r\n    }\r\n  }\r\n  return decor;\r\n}\r\n\r\n/** `venueDecor` 认识的资产（室内资产不进这个函数：它是 3D 侧与旧测试的接口） */\r\nconst DECOR_KINDS = ['tree', 'bush', 'bench', 'sandbox', 'wheel'] as const;\r\n\r\n/* 摩天轮尺寸随资产走（`venue-assets.tsx` 的 `WHEEL`）：它是\"画出来的东西\"的\r\n * 参数，不是世界几何。放在这里会让 world.ts 反过来依赖美术层。 */\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 滑梯的二维几何（WorldLayer 用；三维 SlideRig 用同一组参数）\r\n * ------------------------------------------------------------------ */\r\n\r\n/**\r\n * 爬梯顶端：**平台面**。\r\n *\r\n * 不沿用 ladderTopY(climbEndY)——那是\"只有一把梯子\"时的算法（爬到 1.5 还要\r\n * 再留两阶）。现在梯子是滑梯的一部分，它的顶端由平台决定：爬梯必须够到平台，\r\n * 多出来的部分是凭空长在天上的栏杆，三维那边也没有对应的 mesh。\r\n */\r\nexport function slideLadderTop(world: WorldSlide): number {\r\n  return world.start[1];\r\n}\r\n\r\n/**\r\n * 世界里的爬梯 x：与三维 SlideRig 同一个函数，避免\"2D 梯子 3D 梯子\"两把。\r\n * 横档高度用 setpiece.ladderRungYs(顶端)，两个渲染器不各自铺密度。\r\n */\r\nexport function worldLadderX(world: WorldView): number | null {\r\n  if (!world.slide) return null;\r\n  return slideLadderX(world.slide.start, world.slide.end);\r\n}\r\n\r\n/** 双人站位之间的距离（两人中心间距，世界单位）。约 0.66 个角色身高 */\r\nconst DUO_SPAN = 1.75;\r\n\r\n/**\r\n * 两个角色的站位（世界 x）。\r\n *\r\n * 双人动作不是\"把两个头像摆在画面两端\"：递给需要两只手在中缝相遇，\r\n * 一起抬需要两人各托住东西的一侧。间距由**手臂够得着**决定——1.75 个世界单位\r\n * 时，两条 0.72 的前伸手臂之间还剩 0.3 左右的空当，正好放一件道具，\r\n * 而且道具要走的那段距离在画面上看得见（太近就成了\"原地换个手\"）。\r\n *\r\n * 有滑梯时整对平移到爬梯左侧的空地：站着的地方不能落在滑梯的立柱与爬梯里，\r\n * 否则画面上是\"两个人穿在一副铁架子里递苹果\"。站位只依赖场地几何，\r\n * 与\"这一节课讲什么\"无关。\r\n */\r\nexport function duoStations(world: WorldView): [number, number] {\r\n  const half = DUO_SPAN / 2;\r\n  const ladder = worldLadderX(world);\r\n  if (ladder === null) return [-half, half];\r\n  // 爬梯外侧再留一个身位：1.15 ≈ 身宽的一半 + 一点余地\r\n  const center = Math.max(OPEN_VENUE_BOUNDS.minX + half, ladder - 1.15);\r\n  return [center - half, center + half];\r\n}\r\n"
  },
  {
    "path": "character/venue-assets.tsx",
    "content": "/**\n * 场地装饰资产。\n *\n * 每个资产是一个**纯绘制组件**：给世界坐标、配色、帧号，画自己。它们不知道\n * \"这是哪个场地\"，也不知道自己排第几——那属于配方（`venue-recipes.ts`）。\n *\n * 为什么要单独一个文件：加一件装饰只应该改这里（写组件 + 注册一行）和配方\n * （摆位置），**不该打开 `WorldLayer.tsx`**。渲染器只认 `DECOR_RENDERERS`\n * 这张表，所以\"加资产\"和\"加场地\"是两条互不干扰的路。\n *\n * 所有动画都由 `frame` 推，不用 `Math.random` / `Date.now`：同一帧重渲必须\n * 逐像素一致，这是 Remotion 的硬要求。\n */\n\nimport React from 'react';\nimport type { DecorItem, VenueTheme } from './venue-recipes';\n\nexport type AssetProj = {\n  px: (x: number) => number;\n  py: (y: number) => number;\n  u: (n: number) => number;\n};\n\nexport type AssetProps = AssetProj & {\n  item: DecorItem;\n  theme: VenueTheme;\n  frame: number;\n};\n\nexport type DecorRenderer = React.FC<AssetProps>;\n\n/** 统一的\"被风吹\"位移。树与灌木共用，才有\"同一阵风\"的感觉 */\nexport const swayOf = (frame: number, u: (n: number) => number) => Math.sin(frame / 46) * u(0.02);\n\n/**\n * 摩天轮尺寸。写在世界单位里而不是像素里：半径 2.2 个世界单位 ≈ 4 米，\n * 与滑梯（平台 2.6）是同一处公园的量级。换成像素写死的话，镜头一变焦它就\n * 和滑梯对不上，又回到\"贴图背景\"。\n */\nexport const WHEEL = { radius: 2.2, centerY: 1.35 } as const;\n\nconst Tree: DecorRenderer = ({ item, theme, frame, px, py, u }) => {\n  const x = item.x;\n  const sway = swayOf(frame, u);\n  return (\n    <g>\n      <rect x={px(x) - u(0.075)} y={py(1.45)} width={u(0.15)} height={u(1.45)} rx={u(0.05)} fill={theme.woodDark} />\n      <circle cx={px(x) - u(0.42) + sway} cy={py(1.9)} r={u(0.56)} fill={theme.leaf} />\n      <circle cx={px(x) + u(0.44) + sway} cy={py(1.98)} r={u(0.5)} fill={theme.leaf} />\n      <circle cx={px(x) + sway} cy={py(2.32)} r={u(0.62)} fill={theme.leaf} />\n      <circle cx={px(x) - u(0.16) + sway} cy={py(2.16)} r={u(0.4)} fill={theme.leafDark} opacity={0.55} />\n    </g>\n  );\n};\n\n/**\n * 灌木：没有围栏的场地（森林、夜）用它填两侧。\n * 尺寸比树小一档、贴地，作用是\"视线尽头不是一块空草地\"。\n */\nconst Bush: DecorRenderer = ({ item, theme, frame, px, py, u }) => {\n  const x = item.x;\n  const sway = swayOf(frame, u);\n  return (\n    <g>\n      <ellipse cx={px(x) - u(0.22) + sway} cy={py(0.2)} rx={u(0.32)} ry={u(0.24)} fill={theme.leafDark} />\n      <ellipse cx={px(x) + u(0.24) + sway} cy={py(0.18)} rx={u(0.3)} ry={u(0.22)} fill={theme.leaf} />\n      <ellipse cx={px(x) + sway} cy={py(0.26)} rx={u(0.34)} ry={u(0.26)} fill={theme.leaf} />\n    </g>\n  );\n};\n\nconst Bench: DecorRenderer = ({ item, theme, px, py, u }) => {\n  const x = item.x;\n  return (\n    <g>\n      {/* 靠背 */}\n      <rect x={px(x) - u(0.8)} y={py(0.86)} width={u(1.6)} height={u(0.12)} rx={u(0.05)} fill={theme.wood} />\n      <rect x={px(x) - u(0.8)} y={py(0.72)} width={u(1.6)} height={u(0.1)} rx={u(0.04)} fill={theme.wood} />\n      {/* 座面 */}\n      <rect x={px(x) - u(0.84)} y={py(0.46)} width={u(1.68)} height={u(0.1)} rx={u(0.04)} fill={theme.woodDark} />\n      {/* 腿 */}\n      {[-0.66, 0.66].map((dx) => (\n        <rect key={dx} x={px(x) + u(dx) - u(0.05)} y={py(0.46)} width={u(0.1)} height={u(0.46)} fill={theme.woodDark} />\n      ))}\n    </g>\n  );\n};\n\nconst Sandbox: DecorRenderer = ({ item, theme, px, py, u }) => {\n  const x = item.x;\n  return (\n    <g>\n      <rect x={px(x) - u(0.85)} y={py(0.3)} width={u(1.7)} height={u(0.3)} rx={u(0.06)} fill={theme.wood} />\n      <rect x={px(x) - u(0.74)} y={py(0.3)} width={u(1.48)} height={u(0.22)} fill={theme.path} opacity={0.9} />\n      {/* 小桶与铲子：告诉孩子\"这里可以玩沙\"，比一块空沙子更可读 */}\n      <path\n        d={`M ${px(x) + u(0.12)} ${py(0.28)} l ${u(0.16)} 0 l ${-u(0.02)} ${u(0.2)} l ${-u(0.12)} 0 Z`}\n        fill=\"#ef5f58\"\n      />\n      <line\n        x1={px(x) - u(0.2)}\n        y1={py(0.28)}\n        x2={px(x) - u(0.34)}\n        y2={py(0.5)}\n        stroke=\"#5b8ba6\"\n        strokeWidth={u(0.035)}\n        strokeLinecap=\"round\"\n      />\n    </g>\n  );\n};\n\n/**\n * 摩天轮：读作\"公园的另一头\"，不是前景道具。\n * 轮子转得很慢，但它是确定性的（frame 推）。透明度由配方给（0.42），\n * 压暗之后它才不会抢角色的注意力。\n */\nconst Wheel: DecorRenderer = ({ item, theme, px, py, u, frame }) => {\n  const spin = (frame / 360) * Math.PI * 2;\n  const cx = px(item.x);\n  const cy = py(WHEEL.centerY);\n  return (\n    <g opacity={item.opacity ?? 1}>\n      <circle cx={cx} cy={cy} r={u(WHEEL.radius)} fill=\"none\" stroke={theme.metal} strokeWidth={u(0.07)} />\n      <circle cx={cx} cy={cy} r={u(WHEEL.radius * 0.78)} fill=\"none\" stroke={theme.metal} strokeWidth={u(0.03)} opacity={0.7} />\n      {Array.from({ length: 8 }).map((_, i) => {\n        const a = spin + (Math.PI * 2 * i) / 8;\n        const sx = cx + Math.cos(a) * u(WHEEL.radius);\n        const sy = cy + Math.sin(a) * u(WHEEL.radius);\n        return (\n          <g key={`spoke-${i}`}>\n            <line x1={cx} y1={cy} x2={sx} y2={sy} stroke={theme.metal} strokeWidth={u(0.025)} opacity={0.7} />\n            <rect x={sx - u(0.12)} y={sy - u(0.1)} width={u(0.24)} height={u(0.2)} rx={u(0.06)} fill={theme.metal} opacity={0.85} />\n          </g>\n        );\n      })}\n      {/* 支架：两根斜柱落地，轮子才不会悬空 */}\n      <line x1={cx - u(0.9)} y1={py(0)} x2={cx} y2={cy} stroke={theme.metal} strokeWidth={u(0.06)} />\n      <line x1={cx + u(0.9)} y1={py(0)} x2={cx} y2={cy} stroke={theme.metal} strokeWidth={u(0.06)} />\n    </g>\n  );\n};\n\n/**\n * 资产注册表。**加资产 = 在这里加一行**，加场地不用碰它，反之亦然。\n * 测试会断言\"这张表覆盖 DECOR_ASSET_IDS\"，漏注册会红。\n */\nexport const DECOR_RENDERERS: Record<string, DecorRenderer> = {\n  tree: Tree,\n  bush: Bush,\n  bench: Bench,\n  sandbox: Sandbox,\n  wheel: Wheel,\n};\n"
  },
  {
    "path": "character/WorldLayer.tsx",
    "content": "/**\n * 场地渲染（WorldLayer）：**只负责\"每一层怎么画\"，不管\"这个场地有什么\"**。\n *\n * 场地内容全在 `venue-recipes.ts`（数据），装饰细节全在 `venue-assets.tsx`\n * （组件）。这里是一台很笨的放映机：按配方给的顺序，逐层调对应分支画出来。\n *\n * 为什么这么分——加一处场地、加一件装饰都不该改这个文件。以前这里既有\"层\"\n * 又有\"具体场地\"（摩天轮只在 playground），于是每加一处场地都要改 4 个文件，\n * 而且没有任何东西会提醒你\"漏了一层\"。\n *\n * 与上一版背景的区别仍然成立，而且现在由配方结构保证：\n *  - `sky` 是屏幕空间（云不跟着镜头跑，那是\"天\"）；\n *  - 其余全部是世界坐标，跟角色同一把尺（camera 的 ppu / originX）；\n *  - 所以镜头一变焦，树、滑梯、熊一起变大；角色走过去，树不会\"贴着他平移\"。\n *\n * 绘制顺序 = 配方 `layers` 的顺序 = 遮挡关系。`decor` 允许出现多次，\n * 因为\"摩天轮在围栏之前、树在围栏之后\"这件事没法在一个 decor 层里表达。\n */\n\nimport React from 'react';\nimport { LADDER, SLIDE, ladderRungYs, slideDeckAngle } from './setpiece';\nimport { slideLadderTop, worldLadderX, type WorldCamera, type WorldView } from './world';\nimport { DECOR_RENDERERS } from './venue-assets';\nimport {\n  venueRecipe,\n  type DecorLayer,\n  type FenceLayer,\n  type GroundLayer,\n  type HorizonLayer,\n  type LayerSpec,\n  type SkyLayer,\n  type VenueTheme,\n  type WaterLayer,\n} from './venue-recipes';\n\n/** 滑梯配色与三维 SlideRig 同一组：切换渲染器时道具不能\"换了个颜色\" */\nconst SLIDE_DECK = '#ffb347';\nconst SLIDE_RAIL = '#ff8f4d';\nconst SLIDE_POST = '#cf9a63';\n\ntype RenderCtx = {\n  frame: number;\n  theme: VenueTheme;\n  world: WorldView;\n  px: (x: number) => number;\n  py: (y: number) => number;\n  u: (n: number) => number;\n};\n\n/* ------------------------------------------------------------------ *\n * 六个稳定分支。**以后不会再长**：新场地是数据，新装饰是资产组件。\n * ------------------------------------------------------------------ */\n\nfunction renderLayer(layer: LayerSpec, ctx: RenderCtx): React.ReactNode {\n  switch (layer.kind) {\n    case 'sky':\n      return renderSky(layer, ctx);\n    case 'horizon':\n      return renderHorizon(layer, ctx);\n    case 'ground':\n      return renderGround(layer, ctx);\n    case 'water':\n      return renderWater(layer, ctx);\n    case 'fence':\n      return renderFence(layer, ctx);\n    case 'decor':\n      return renderDecor(layer, ctx);\n    default:\n      return null;\n  }\n}\n\n/**\n * 天空：屏幕空间，永不随平移移动——它们是\"天\"，不属于地面世界。\n *\n * `fill: 'solid'` 是室内用的：没有太阳云，这一层就是一块纯色背景。\n * 所以它叫 sky 只是一种历史命名，实际语义是\"背景层\"。\n */\nfunction renderSky(layer: SkyLayer, { frame, theme }: RenderCtx) {\n  const drift = Math.sin(frame / 220) * 18;\n  const sun = layer.sun;\n  return (\n    <>\n      <rect\n        x={0}\n        y={0}\n        width={1920}\n        height={1080}\n        fill={layer.fill === 'solid' ? theme.skyTop : 'url(#world-sky)'}\n      />\n      {sun ? (\n        <>\n          <circle cx={sun.x + drift * 0.3} cy={sun.y} r={sun.glowR} fill=\"url(#world-sun-glow)\" />\n          <circle cx={sun.x + drift * 0.3} cy={sun.y} r={sun.r} fill={theme.sun} />\n        </>\n      ) : null}\n      {(layer.clouds ?? []).map((c, i) => (\n        <g key={`cloud-${i}`} transform={`translate(${c.x + drift * (0.6 + i * 0.2)} ${c.y}) scale(${c.s})`}>\n          <ellipse cx={0} cy={0} rx={96} ry={44} fill={theme.cloud} opacity={0.92} />\n          <ellipse cx={78} cy={10} rx={70} ry={34} fill={theme.cloud} opacity={0.92} />\n          <ellipse cx={-72} cy={14} rx={58} ry={28} fill={theme.cloud} opacity={0.92} />\n        </g>\n      ))}\n    </>\n  );\n}\n\n/** 远山：世界坐标，落在同一个地平线上。用大圆挖出弧顶 */\nfunction renderHorizon(layer: HorizonLayer, { theme, px, py, u }: RenderCtx) {\n  return (\n    <>\n      {layer.hills.map((h, i) => (\n        <circle\n          key={`hill-${i}`}\n          cx={px(h.x)}\n          cy={py(0) + u(h.r) * 0.86}\n          r={u(h.r)}\n          fill={h.tone === 'far' ? theme.hillFar : theme.hillNear}\n          opacity={0.75}\n        />\n      ))}\n    </>\n  );\n}\n\n/**\n * 地面：从地平线铺到底。上沿一条浅色边，把\"地面\"和\"空气\"分开。\n *\n * 层内顺序有意义：铺面 → 滑梯脚下的沙地椭圆 → 草簇。草簇贴在地上、沙地压在地面\n * 上，顺序反了草就\"浮在沙上\"。\n */\nfunction renderGround(layer: GroundLayer, { frame, theme, world, px, py, u }: RenderCtx) {\n  const slide = world.slide;\n  const sway = Math.sin(frame / 46) * u(0.02);\n  return (\n    <>\n      <rect x={0} y={py(0)} width={1920} height={1080 - py(0)} fill={theme.ground} />\n      {layer.topBand > 0 ? (\n        <rect x={0} y={py(0)} width={1920} height={u(layer.topBand)} fill={theme.groundTop} />\n      ) : null}\n      {(layer.patches ?? []).map((patch, i) => {\n        if (patch.asset === 'dirtPatch') {\n          // 沙地属于滑梯，不属于场地：没有滑梯就没人踩出这块地\n          if (!slide) return null;\n          return (\n            <ellipse\n              key={`patch-${i}`}\n              cx={px((slide.start[0] + slide.end[0]) / 2)}\n              cy={py(0)}\n              rx={u(patch.rx)}\n              ry={u(patch.ry)}\n              fill={theme.path}\n              opacity={patch.opacity}\n            />\n          );\n        }\n        // 草簇：确定性地按索引摆，重渲逐像素一致\n        return (\n          <React.Fragment key={`tuft-${i}`}>\n            {Array.from({ length: patch.count }).map((_, j) => {\n              const x = patch.from + j * patch.step;\n              const h = 0.12 + ((j * 7) % 5) * 0.02;\n              return (\n                <path\n                  key={`tuft-${i}-${j}`}\n                  d={`M ${px(x)} ${py(0)} q ${u(0.04) + sway * 0.2} ${-u(h) * 0.6} ${u(0.02)} ${-u(h)}`}\n                  stroke={theme.leafDark}\n                  strokeWidth={Math.max(1.5, u(0.014))}\n                  fill=\"none\"\n                  opacity={0.35}\n                  strokeLinecap=\"round\"\n                />\n              );\n            })}\n          </React.Fragment>\n        );\n      })}\n    </>\n  );\n}\n\n/**\n * 水面：世界坐标的一条水带。\n *\n * 这是**新的渲染原语**，不是新场地：今后\"湖\"\"水池\"\"海边\"都复用它，只改\n * `from/to/surfaceY/depth`。这正是\"原语可枚举、内容不可枚举\"的收益。\n */\nfunction renderWater(layer: WaterLayer, { theme, px, py, u }: RenderCtx) {\n  const fill = theme.water ?? theme.hillNear;\n  return (\n    <>\n      <rect\n        x={px(layer.from)}\n        y={py(layer.surfaceY)}\n        width={u(layer.to - layer.from)}\n        height={u(layer.depth)}\n        fill={fill}\n        opacity={layer.opacity ?? 0.85}\n      />\n      {/* 水面上沿一道亮边：没有它，水带和草地只是两块颜色不同的矩形 */}\n      <rect\n        x={px(layer.from)}\n        y={py(layer.surfaceY)}\n        width={u(layer.to - layer.from)}\n        height={Math.max(1.5, u(0.03))}\n        fill={theme.cloud}\n        opacity={0.55}\n      />\n    </>\n  );\n}\n\n/**\n * 围栏：**按场地给**。它是游乐园/牧场的语汇，森林里画一条横贯全画面的\n * 木栅栏就变成了\"一个有围栏的空地\"。\n */\nfunction renderFence(layer: FenceLayer, { theme, px, py, u }: RenderCtx) {\n  return (\n    <g opacity={0.9}>\n      {Array.from({ length: layer.posts }).map((_, i) => {\n        const x = layer.from + i * layer.spacing;\n        return (\n          <rect\n            key={`fence-post-${i}`}\n            x={px(x) - u(layer.postWidth / 2)}\n            y={py(layer.postHeight)}\n            width={u(layer.postWidth)}\n            height={u(layer.postHeight)}\n            rx={u(0.03)}\n            fill={theme.wood}\n          />\n        );\n      })}\n      {layer.railYs.map((y) => (\n        <rect\n          key={`fence-rail-${y}`}\n          x={px(layer.from)}\n          y={py(y)}\n          width={u(layer.railSpan)}\n          height={u(layer.railHeight)}\n          fill={theme.woodDark}\n          opacity={0.85}\n        />\n      ))}\n    </g>\n  );\n}\n\n/** 装饰：数组顺序即绘制顺序，资产自己知道怎么画 */\nfunction renderDecor(layer: DecorLayer, { frame, theme, px, py, u }: RenderCtx) {\n  return (\n    <>\n      {layer.items.map((item, i) => {\n        const Asset = DECOR_RENDERERS[item.asset];\n        if (!Asset) return null;\n        return (\n          <Asset key={`${item.asset}-${i}`} item={item} theme={theme} frame={frame} px={px} py={py} u={u} />\n        );\n      })}\n    </>\n  );\n}\n\n/* ------------------------------------------------------------------ *\n * 世界层\n * ------------------------------------------------------------------ */\n\nexport const WorldLayer: React.FC<{\n  world: WorldView;\n  camera: WorldCamera;\n  frame: number;\n  /**\n   * 是否由这里画滑梯。三维舞台自己用 mesh 画滑梯（要参与光影与遮挡），\n   * 这时只画背景，否则会出现两座滑梯叠在一起。\n   */\n  withSlide?: boolean;\n}> = ({ world, camera, frame, withSlide = true }) => {\n  const recipe = venueRecipe(world.venue);\n  const theme = recipe.theme;\n  const { ppu, originX, groundY } = camera;\n  /** 世界 → 屏幕 */\n  const px = (x: number) => originX + x * ppu;\n  const py = (y: number) => groundY - y * ppu;\n  const u = (n: number) => n * ppu;\n\n  const slide = withSlide ? world.slide : undefined;\n  const ladderX = slide ? worldLadderX(world) : null;\n\n  const ctx: RenderCtx = { frame, theme, world, px, py, u };\n\n  return (\n    <div style={{ position: 'absolute', inset: 0, overflow: 'hidden' }}>\n      <svg width={1920} height={1080} viewBox=\"0 0 1920 1080\" style={{ position: 'absolute', inset: 0 }}>\n        <defs>\n          <linearGradient id=\"world-sky\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0%\" stopColor={theme.skyTop} />\n            <stop offset=\"100%\" stopColor={theme.skyBottom} />\n          </linearGradient>\n          <radialGradient id=\"world-sun-glow\" cx=\"0.5\" cy=\"0.5\" r=\"0.5\">\n            <stop offset=\"0%\" stopColor={theme.sun} stopOpacity=\"0.55\" />\n            <stop offset=\"100%\" stopColor={theme.sun} stopOpacity=\"0\" />\n          </radialGradient>\n        </defs>\n\n        {recipe.layers.map((layer, i) => (\n          <React.Fragment key={i}>{renderLayer(layer, ctx)}</React.Fragment>\n        ))}\n\n        {/* 滑梯：平台 + 立柱 + 滑道 + 爬梯，一个整体。它是装置槽，不进入配方 */}\n        {slide ? (\n          <Slide2D\n            start={slide.start}\n            end={slide.end}\n            px={px}\n            py={py}\n            u={u}\n            ladderX={ladderX ?? slide.start[0]}\n            ladderTop={slideLadderTop(slide)}\n          />\n        ) : null}\n      </svg>\n    </div>\n  );\n};\n\n/* ------------------------------------------------------------------ *\n * 滑梯（装置槽）\n * ------------------------------------------------------------------ */\n\ntype Proj = {\n  px: (x: number) => number;\n  py: (y: number) => number;\n  u: (n: number) => number;\n};\n\n/**\n * 滑梯（二维侧视）。\n *\n * 所有数字来自 setpiece：平台宽度、护边高度、立柱位置、爬梯间距。\n * 这里不做\"看起来差不多\"的近似——三维 SlideRig 用的是同一组常量，\n * 所以同一节课里 2D 幕与 3D 幕的滑梯是同一个滑梯。\n */\nconst Slide2D: React.FC<Proj & {\n  start: readonly [number, number, number];\n  end: readonly [number, number, number];\n  ladderX: number;\n  ladderTop: number;\n}> = ({ start, end, px, py, u, ladderX, ladderTop }) => {\n  const angle = slideDeckAngle(start, end);\n  const cos = Math.cos(angle);\n  const sin = Math.sin(angle);\n  const half = SLIDE.deckThickness / 2;\n  // 滑道四角：沿法线（-sin, cos）上下各偏移半个厚度\n  const quad = [\n    [start[0] - sin * half, start[1] + cos * half],\n    [start[0] + sin * half, start[1] - cos * half],\n    [end[0] + sin * half, end[1] - cos * half],\n    [end[0] - sin * half, end[1] + cos * half],\n  ];\n  const deckPath = quad\n    .map(([x, y], i) => `${i === 0 ? 'M' : 'L'} ${px(x)} ${py(y)}`)\n    .join(' ') + ' Z';\n\n  const platformX = start[0] - cos * SLIDE.platformInset;\n  const railOffsetY = SLIDE.railLift + SLIDE.railHeight / 2;\n\n  return (\n    <g>\n      {/* 平台立柱：从地面到平台面 */}\n      {[start[0] - cos * SLIDE.topPostInset, end[0] - SLIDE.endPostInset].map((x, i) => {\n        const top = i === 0 ? start[1] : end[1];\n        return (\n          <rect\n            key={`post-${i}`}\n            x={px(x) - u(SLIDE.topPostRadius)}\n            y={py(top)}\n            width={u(SLIDE.topPostRadius * 2)}\n            height={u(top)}\n            fill={SLIDE_POST}\n          />\n        );\n      })}\n\n      {/* 平台 */}\n      <rect\n        x={px(platformX - SLIDE.platformWidth / 2)}\n        y={py(start[1] + SLIDE.platformThickness)}\n        width={u(SLIDE.platformWidth)}\n        height={u(SLIDE.platformThickness)}\n        rx={u(0.03)}\n        fill={SLIDE_DECK}\n      />\n\n      {/* 滑道 + 两侧护边（侧视只看得见朝镜头这一侧，所以画一条粗线） */}\n      <path d={deckPath} fill={SLIDE_DECK} />\n      <line\n        x1={px(start[0])}\n        y1={py(start[1] + railOffsetY)}\n        x2={px(end[0])}\n        y2={py(end[1] + railOffsetY)}\n        stroke={SLIDE_RAIL}\n        strokeWidth={u(SLIDE.railHeight)}\n        strokeLinecap=\"round\"\n      />\n\n      {/* 爬梯：两根立杆 + 横档，间距 = CLIMB.step（与攀爬动作同源） */}\n      <rect x={px(ladderX - LADDER.railHalf) - u(LADDER.railWidth / 2)} y={py(ladderTop)} width={u(LADDER.railWidth)} height={u(ladderTop)} fill={SLIDE_POST} />\n      <rect x={px(ladderX + LADDER.railHalf) - u(LADDER.railWidth / 2)} y={py(ladderTop)} width={u(LADDER.railWidth)} height={u(ladderTop)} fill={SLIDE_POST} />\n      {ladderRungYs(ladderTop).map((y, i) => (\n        <line\n          key={`rung-${i}`}\n          x1={px(ladderX - LADDER.railHalf)}\n          y1={py(y)}\n          x2={px(ladderX + LADDER.railHalf)}\n          y2={py(y)}\n          stroke={SLIDE_POST}\n          strokeWidth={u(LADDER.railWidth * 0.8)}\n          strokeLinecap=\"round\"\n        />\n      ))}\n    </g>\n  );\n};\n"
  },
  {
    "path": "character/Puppet2D.tsx",
    "content": "/**\r\n * 二维全身角色（Puppet2D）\r\n *\r\n * 它解决的是\"头像徽章演不了动作\"这个断层：徽章是一个圆里放一张图，没有躯干、\r\n * 没有腿、没有可动关节，所以\"走进来\"\"爬上去\"在物理上就画不出来。\r\n *\r\n * 这里的分片与三维舞台完全同构，因为它们消费的是同一份 Pose（character/pose.ts）：\r\n *  3D 把关节目标点映射成圆柱 + 四元数，2D 映射成 SVG 线段 + 两段肢体求解。\r\n * 因此\"新增一个动作\"不需要碰这个文件——动作在 pose 层写一次，两个渲染器都能演。\r\n *\r\n * 唯一的投影约定（踩过坑）：**躯干旋转必须作用在四肢上**。\r\n * 如果只给躯干椭圆加 rotate()、四肢各自按世界坐标算，爬/滑时身体转了腿没转，\r\n * 画面上就是\"上身扭过去、下身留在原地\"。所以所有部件都先转成\"相对髋部的\r\n * 局部坐标\"，由同一个 project() 统一施加 rotZ，再翻 y、缩放。\r\n *\r\n * 确定性：只用传入的 frame，不读 useCurrentFrame、不用 Math.random。\r\n */\r\n\r\nimport React from 'react';\r\nimport {\r\n  ACTOR,\r\n  BALL_RADIUS,\r\n  SPEC,\r\n  blendPose,\r\n  clamp,\r\n  dribblePose,\r\n  gripLocal,\r\n  poseAt,\r\n  smooth,\r\n  type ActorRig,\r\n  type MotionInput,\r\n  type MotionOp,\r\n  type Pose,\r\n  type Tri,\r\n} from './pose';\r\nimport {\r\n  framingFor,\r\n  propBounds,\r\n  shotForMotion,\r\n  unionAll,\r\n  type Bounds,\r\n  type Shot,\r\n} from './stage-layout';\r\nimport { LADDER, actorHeadTop, ladderBounds, ladderTopY, slideBounds } from './setpiece';\r\nimport { WorldLayer } from './WorldLayer';\r\nimport { cameraForWorld, duoStations, normalizeWorld, worldLadderX } from './world';\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 取景\r\n *\r\n * 这里**没有** PPU / GROUND_Y 常量了。以前写死 PPU=265、GROUND_Y=856，\r\n * 与\"标题占多高、布景有多高\"毫无关系：梯子顶到 2.75 世界单位时，\r\n * 856 − 2.75×265 = 114px，正好钻进标题胶囊（底边 121）。\r\n *\r\n * 现在缩放由 stage-layout 的取景定律算出来：先问\"这一幕最高的东西有多高\"\r\n * （布景注册表回答），再和\"角色该画多大\"取小者。内容再高，缩放自动变小，\r\n * 撞标题这件事在算术上不成立。\r\n * ------------------------------------------------------------------ */\r\n/** climb 的角色最高点：动作设计值（4 阶 × 0.21），不再承担\"别撞标题\"的职责 */\r\nconst MAX_STAND_Y = 1.55;\r\n\r\n/** 一幕多动作里的一节。帧数由后端的注册表按\"动作自然时长\"分配，渲染层不重算。 */\r\nexport type PuppetSegment = {\r\n  motion: MotionOp;\r\n  durationFrames: number;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n};\r\n\r\n/**\r\n * 同场的第二个角色。\r\n *\r\n * 它不是\"再画一个人\"那么简单：递给与一起抬的语义是**两个身体之间的接触**，\r\n * 单角色骨架演不了，所以这两种动词以前被挡在徽章分支里。给一个人配一份\r\n * 独立的播放表、共用一个相机之后，双人幕与单人幕用的是同一套人物语言。\r\n */\r\nexport type PuppetCoStar = {\r\n  rig: ActorRig;\r\n  motion: MotionOp;\r\n  sequence?: PuppetSegment[];\r\n  durationFrames?: number;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n  /**\r\n   * 朝向。不给就默认\"面对主角色\"——双人动作的语义是对着那个人做事；\r\n   * 按位移方向推会在双方都不动时取 +1，画出来是背对着对方递东西。\r\n   */\r\n  facing?: 1 | -1;\r\n};\r\n\r\n/** 手里拿着的道具：位置由手算，不是屏幕坐标 */\r\nexport type PuppetCarry = {\r\n  node: React.ReactNode;\r\n  /** 世界单位的尺寸（与 props.size 同一套：换算成像素时乘 ppu） */\r\n  size: number;\r\n  label?: string;\r\n  /**\r\n   * 在谁手里：\r\n   *  - `self`：主角色一直拿着；\r\n   *  - `coStar`：副角色拿着；\r\n   *  - `shared`：两人一起托着，停在两手之间（一起抬）；\r\n   *  - `handover`：沿弧线从主角色的手移到副角色的手（递给）。\r\n   * 缺省：有副角色就 `shared`，否则 `self`。\r\n   */\r\n  by?: 'self' | 'coStar' | 'shared' | 'handover';\r\n};\r\n\r\nexport type Puppet2DScene = {\r\n  motion: MotionOp;\r\n  rig: ActorRig;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  durationFrames: number;\r\n  /**\r\n   * 一幕多动作的播放表，按顺序播放。长度大于 1 时 `motion` 只作为兜底\r\n   * （例如序列为空的那一帧），实际姿态由当前所在的段落决定。\r\n   */\r\n  sequence?: PuppetSegment[];\r\n  accent: string;\r\n  label?: string;\r\n  /**\r\n   * 布景道具。坐标是**世界单位**（与角色、布景同一套坐标），node 由调用方\r\n   * 预先渲染成 SVG 片段——组件本身不认识\"滑梯\"\"皮球\"这些业务道具，只负责\r\n   * 把它们按场景需要摆到位。这样新增道具不用改这个文件。\r\n   *\r\n   * 用世界坐标而不是屏幕坐标，是为了让道具跟着取景一起缩放/平移，并且能\r\n   * 参与内容包围盒——否则\"被指着的东西\"会被摆到画面外，或者平板地贴在\r\n   * 背景上不随角色变大。\r\n   */\r\n  props?: Array<{ x: number; y: number; size: number; label?: string; node: React.ReactNode }>;\r\n  /** 漂浮在角色之上的覆盖层（对话气泡等 HTML 元素，不能塞进 SVG） */\r\n  overlay?: React.ReactNode;\r\n  /**\r\n   * overlay 的出场时刻（0..1，按场景进度）。用于一幕多动作：台词气泡要等到\r\n   * 说话那一段再出现，否则\"走过去→指一下→说话\"的顺序在第一帧就被剧透了。\r\n   */\r\n  overlayFrom?: number;\r\n  /**\r\n   * 景别覆盖。不给就按动作自动判定（climb → wide，其余 → medium）。\r\n   * 只影响取景，不影响动作本身：动作的世界坐标由后端定死。\r\n   */\r\n  shot?: Shot;\r\n  /**\r\n   * 场地。整节课共用同一个世界（滑梯在哪、公园长什么样），由后端在每一幕\r\n   * 写同一份数据。给了它就走\"世界 + 镜头\"的取景，没给（旧缓存分镜）仍按\r\n   * 这一幕自己拟合——两条路径的画面不可能一样，但旧任务不会因此崩掉。\r\n   */\r\n  world?: unknown;\r\n  /**\r\n   * 这一幕用到的那件**世界装置**（目前只有滑梯）。\r\n   * 不是\"道具\"：滑梯在场地里本来就在，这一幕要拍的是\"角色与它互动\"，\r\n   * 所以取景要把整座滑梯框进来，而不是在旁边摆一个滑梯图标。\r\n   */\r\n  setpiece?: string;\r\n  /** 同场的第二个角色（双人幕）。缺省时这个文件的行为与只有一个人时完全一致 */\r\n  coStar?: PuppetCoStar;\r\n  /** 手里的道具（递给 / 一起抬）。位置由两个角色的手算出来 */\r\n  carry?: PuppetCarry;\r\n};\r\n\r\n/** 颜色压暗：给每个形状描一圈同色深边，角色不会糊进背景 */\r\nconst shade = (hex: string, k = 0.72): string => {\r\n  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());\r\n  if (!m) return hex;\r\n  const n = parseInt(m[1], 16);\r\n  const r = Math.round(((n >> 16) & 255) * k);\r\n  const g = Math.round(((n >> 8) & 255) * k);\r\n  const b = Math.round((n & 255) * k);\r\n  return `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 两段肢体求解\r\n *\r\n * 给定根关节和末端目标点，求中间关节（肘/膝）。做法是\"中点 + 法向偏移\"，\r\n * 偏移方向由 bend 的符号决定：膝盖朝前（+x），手肘朝后（-x）。\r\n * 不用真正的 IK：2D 画面上多余的自由度只会带来抖动，固定弯向才稳定。\r\n * ------------------------------------------------------------------ */\r\nfunction jointPoint(from: Tri, to: Tri, bend: number): Tri {\r\n  const mx = (from[0] + to[0]) / 2;\r\n  const my = (from[1] + to[1]) / 2;\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 0.0001;\r\n  // 法向（-dy, dx）在\"末端在下方\"时指向 +x\r\n  const nx = -dy / len;\r\n  const ny = dx / len;\r\n  return [mx + nx * bend * len, my + ny * bend * len, (from[2] + to[2]) / 2];\r\n}\r\n\r\ntype Projector = (p: Tri) => [number, number];\r\n\r\n/** 上限钳制：模型/参数给的目标点再离谱，肢体也不会被拉成面条 */\r\nfunction clampReach(from: Tri, to: Tri, maxLen: number): Tri {\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const dz = to[2] - from[2];\r\n  const len = Math.sqrt(dx * dx + dy * dy + dz * dz);\r\n  if (len <= maxLen) return to;\r\n  const k = maxLen / len;\r\n  return [from[0] + dx * k, from[1] + dy * k, from[2] + dz * k];\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 部件\r\n * ------------------------------------------------------------------ */\r\n\r\nconst Limb2D: React.FC<{\r\n  pivot: Tri;\r\n  target: Tri;\r\n  bend: number;\r\n  maxLen: number;\r\n  width: number;\r\n  color: string;\r\n  capColor?: string;\r\n  capRadius?: number;\r\n  project: Projector;\r\n  /** 末端压扁比例：脚掌画扁椭圆，手掌画圆 */\r\n  capFlat?: number;\r\n}> = ({ pivot, target, bend, maxLen, width, color, capColor, capRadius, project, capFlat }) => {\r\n  const to = clampReach(pivot, target, maxLen);\r\n  const joint = jointPoint(pivot, to, bend);\r\n  const cap = capRadius ?? width * 0.62;\r\n  const capP = project(to);\r\n  const a = project(pivot);\r\n  const b = project(joint);\r\n  const c = project(to);\r\n  return (\r\n    <g>\r\n      <line x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke={color} strokeWidth={width} strokeLinecap=\"round\" />\r\n      <line x1={b[0]} y1={b[1]} x2={c[0]} y2={c[1]} stroke={color} strokeWidth={width * 0.9} strokeLinecap=\"round\" />\r\n      {capColor ? (\r\n        capFlat ? (\r\n          <ellipse\r\n            cx={capP[0]}\r\n            cy={capP[1]}\r\n            rx={cap * 1.15}\r\n            ry={cap * capFlat}\r\n            fill={capColor}\r\n            stroke={shade(capColor)}\r\n            strokeWidth={3}\r\n          />\r\n        ) : (\r\n          <circle\r\n            cx={capP[0]}\r\n            cy={capP[1]}\r\n            r={cap}\r\n            fill={capColor}\r\n            stroke={shade(capColor)}\r\n            strokeWidth={3}\r\n          />\r\n        )\r\n      ) : null}\r\n    </g>\r\n  );\r\n};\r\n\r\n/** 头：圆 + 耳 + 口鼻 + 鼻头 + 眼睛，按 headTilt 绕脖子旋转 */\r\nconst Head2D: React.FC<{ rig: ActorRig; head: [number, number]; r: number; tilt: number }> = ({\r\n  rig,\r\n  head,\r\n  r,\r\n  tilt,\r\n}) => {\r\n  const fur = rig.fur;\r\n  const belly = rig.belly;\r\n  const stroke = shade(fur);\r\n  // headTilt 是弧度，绕脖子（头底部）转，不是绕头心——绕头心转会让整颗头平移\r\n  const pivotY = head[1] + r;\r\n  const transform = `rotate(${(tilt * 180) / Math.PI} ${head[0]} ${pivotY})`;\r\n  const earY = head[1] - r * 0.74;\r\n  return (\r\n    <g transform={transform}>\r\n      {rig.ears === 'round' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <circle\r\n              key={side}\r\n              cx={head[0] + side * r * 0.62}\r\n              cy={earY}\r\n              r={r * 0.38}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n          {[-1, 1].map((side) => (\r\n            <circle\r\n              key={`in-${side}`}\r\n              cx={head[0] + side * r * 0.62}\r\n              cy={earY}\r\n              r={r * 0.19}\r\n              fill={belly}\r\n              opacity={0.85}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'long' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <ellipse\r\n              key={side}\r\n              cx={head[0] + side * r * 0.4}\r\n              cy={earY - r * 0.6}\r\n              rx={r * 0.2}\r\n              ry={r * 0.62}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'pointy' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <path\r\n              key={side}\r\n              d={`M ${head[0] + side * r * 0.42} ${earY + r * 0.12} L ${head[0] + side * r * 0.78} ${earY - r * 0.52} L ${head[0] + side * r * 0.9} ${earY + r * 0.2} Z`}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n              strokeLinejoin=\"round\"\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'flap' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <ellipse\r\n              key={side}\r\n              cx={head[0] + side * r * 1.14}\r\n              cy={head[1] + r * 0.06}\r\n              rx={r * 0.34}\r\n              ry={r * 0.5}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n\r\n      <circle cx={head[0]} cy={head[1]} r={r} fill={fur} stroke={stroke} strokeWidth={4} />\r\n      {/* 口鼻 */}\r\n      <ellipse cx={head[0]} cy={head[1] + r * 0.34} rx={r * 0.46} ry={r * 0.34} fill={belly} />\r\n      <ellipse cx={head[0]} cy={head[1] + r * 0.18} rx={r * 0.15} ry={r * 0.11} fill=\"#3b2a20\" />\r\n      {/* 眼睛：略微内倾，比正圆更有神 */}\r\n      {[-1, 1].map((side) => (\r\n        <ellipse\r\n          key={side}\r\n          cx={head[0] + side * r * 0.36}\r\n          cy={head[1] - r * 0.12}\r\n          rx={r * 0.1}\r\n          ry={r * 0.13}\r\n          fill=\"#241812\"\r\n        />\r\n      ))}\r\n    </g>\r\n  );\r\n};\r\n\r\n/**\r\n * 梯子（climb 的布景）\r\n *\r\n * 没有它，\"爬\"在画面上就是一只浮在半空的熊——手脚找不到落点，观众读不出\r\n * 高度变化是在爬。这也是布景锚点的最小形态：道具不只是旁边摆一个图标，\r\n * 它要提供角色能够接触的表面。\r\n *\r\n * 所有几何都来自 setpiece.ts 的 LADDER：横档间距、首根位置、立杆间距。\r\n * 组件只做投影，不持有任何\"这个梯子长什么样\"的数字。\r\n */\r\nconst Ladder: React.FC<{\r\n  x: number;\r\n  baseY: number;\r\n  topY: number;\r\n  /** 横档间距：必须等于 climb 每上一阶的高度，手脚才会正好落在横档上 */\r\n  spacing: number;\r\n  project: Projector;\r\n  s: number;\r\n}> = ({ x, baseY, topY, spacing, project, s }) => {\r\n  const railHalf = LADDER.railHalf;\r\n  const wood = '#c98a5a';\r\n  const dark = '#8d5524';\r\n  const left = project([x - railHalf, baseY, 0]);\r\n  const right = project([x + railHalf, baseY, 0]);\r\n  const leftTop = project([x - railHalf, topY, 0]);\r\n  const rightTop = project([x + railHalf, topY, 0]);\r\n  const width = Math.max(9, LADDER.railWidth * s);\r\n  return (\r\n    <g>\r\n      <line x1={left[0]} y1={left[1]} x2={leftTop[0]} y2={leftTop[1]} stroke={dark} strokeWidth={width} strokeLinecap=\"round\" />\r\n      <line x1={right[0]} y1={right[1]} x2={rightTop[0]} y2={rightTop[1]} stroke={dark} strokeWidth={width} strokeLinecap=\"round\" />\r\n      {Array.from({ length: Math.max(2, Math.floor((topY - baseY) / spacing) + 1) }).map((_, i) => {\r\n        const y = baseY + LADDER.rungStart + spacing * i;\r\n        const a = project([x - railHalf, y, 0]);\r\n        const b = project([x + railHalf, y, 0]);\r\n        return (\r\n          <line\r\n            key={i}\r\n            x1={a[0]}\r\n            y1={a[1]}\r\n            x2={b[0]}\r\n            y2={b[1]}\r\n            stroke={wood}\r\n            strokeWidth={width * LADDER.rungWidthRatio}\r\n            strokeLinecap=\"round\"\r\n          />\r\n        );\r\n      })}\r\n    </g>\r\n  );\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 播放表：一个角色一条\r\n *\r\n * 上一版这段写在组件体里，等于\"这个文件只可能有一个角色\"。后果不是少画一个人，\r\n * 而是\"两个身体之间的动作\"（递给 / 一起抬）被迫留在徽章分支：同一节课里，\r\n * 同一个角色在双人幕是圆形头像、在单人幕是全身，切幕时人物语言就跳了。\r\n *\r\n * 播放表抽出来之后，第二个角色不是特例，只是**同一个函数被调用第二次**。\r\n * ------------------------------------------------------------------ */\r\n\r\ntype Slice = {\r\n  input: MotionInput;\r\n  motion: MotionOp;\r\n  from: number;\r\n  durationFrames: number;\r\n  carry: Tri;\r\n};\r\n\r\n/** 一个角色的动作输入。主角色与副角色共用，不为\"第二个人\"另写一份解析 */\r\ntype ActorPart = {\r\n  motion: MotionOp;\r\n  sequence?: PuppetSegment[];\r\n  durationFrames: number;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n};\r\n\r\nfunction buildPlan(part: ActorPart): Slice[] {\r\n  const single: Slice = {\r\n    input: {\r\n      motion: part.motion,\r\n      durationFrames: Math.max(1, part.durationFrames),\r\n      start: part.start,\r\n      end: part.end,\r\n      steps: part.steps,\r\n      bounce: part.bounce,\r\n      ballRestY: part.ballRestY,\r\n    },\r\n    motion: part.motion,\r\n    from: 0,\r\n    durationFrames: Math.max(1, part.durationFrames),\r\n    carry: [0, 0, 0],\r\n  };\r\n\r\n  const plan: Slice[] = [];\r\n  if (part.sequence && part.sequence.length > 1) {\r\n    /**\r\n     * 拉伸系数：分镜给的时长是\"这一幕该演多久\"，而最终场景长度由**旁白音频**\r\n     * 决定（实测 8s 的幕会被拉到 8.8s）。不拉伸的后果很具体：动作在第 8 秒\r\n     * 演完，剩下的 0.8 秒角色僵在那里，而旁白还在说——观众看到的是\"卡住了\"。\r\n     * 只拉不压：场景比动作串短时宁可截掉尾巴，也不把动作挤到走形。\r\n     */\r\n    const planned = part.sequence.reduce((sum, seg) => sum + Math.max(1, seg.durationFrames), 0);\r\n    const stretch = part.durationFrames > planned ? part.durationFrames / planned : 1;\r\n\r\n    let cursor: Tri | null = null;\r\n    let from = 0;\r\n    for (const seg of part.sequence) {\r\n      const input: MotionInput = {\r\n        motion: seg.motion,\r\n        durationFrames: Math.max(1, Math.round(Math.max(1, seg.durationFrames) * stretch)),\r\n        start: seg.start,\r\n        end: seg.end,\r\n        steps: seg.steps,\r\n      };\r\n      /**\r\n       * 入场偏移 carry：walk 的默认轨迹是\"从画面左侧走到正中\"（-1.6 → 0）。\r\n       * 如果第二段 point 仍按自己的绝对原点（0）播放，角色会瞬移回原点；\r\n       * 反过来，如果第二段 walk 也按 -1.6 起，角色会瞬移回左侧重走一遍。\r\n       * 所以每段的**起点被安放到上一段的终点**。\r\n       */\r\n      const startPose = poseAt(input, 0);\r\n      const carry: Tri = cursor\r\n        ? [cursor[0] - startPose.root[0], cursor[1] - startPose.root[1], cursor[2] - startPose.root[2]]\r\n        : [0, 0, 0];\r\n      plan.push({ input, motion: seg.motion, from, durationFrames: input.durationFrames, carry });\r\n      const endPose = poseAt(input, input.durationFrames);\r\n      cursor = [\r\n        endPose.root[0] + carry[0],\r\n        endPose.root[1] + carry[1],\r\n        endPose.root[2] + carry[2],\r\n      ];\r\n      from += input.durationFrames;\r\n    }\r\n  }\r\n  if (!plan.length) plan.push(single);\r\n  return plan;\r\n}\r\n\r\n/** 取某一帧的姿态：定位当前段、做段落接缝混合、叠加入场偏移 */\r\nfunction playAt(plan: Slice[], frame: number) {\r\n  const active = plan.find((slice) => frame < slice.from + slice.durationFrames) ?? plan[plan.length - 1];\r\n  const localFrame = clamp(frame - active.from, 0, active.durationFrames);\r\n  const index = plan.indexOf(active);\r\n  const shift = (p: Pose, carry: Tri): Pose => ({\r\n    ...p,\r\n    root: [p.root[0] + carry[0], p.root[1] + carry[1], p.root[2] + carry[2]],\r\n  });\r\n\r\n  let pose: Pose = shift(poseAt(active.input, localFrame), active.carry);\r\n  /**\r\n   * 段落接缝混合。硬切的现象很具体：走路末帧手臂在体侧、point 首帧手臂已平举，\r\n   * 一帧内跳过去，看起来像掉帧。8 帧线性混合后是\"走两步，抬手指过去\"。\r\n   * 只混姿态不混位置——位置已在 carry 里保证了连续。\r\n   */\r\n  const BLEND_FRAMES = 8;\r\n  if (index > 0 && localFrame < BLEND_FRAMES) {\r\n    const prev = plan[index - 1];\r\n    const prevPose = shift(poseAt(prev.input, prev.durationFrames), prev.carry);\r\n    const t = localFrame / BLEND_FRAMES;\r\n    pose = blendPose(prevPose, pose, t * t * (3 - 2 * t));\r\n  }\r\n  return { active, localFrame, index, pose };\r\n}\r\n\r\n/**\r\n * 轨迹包围盒：每段取 5 个采样点。\r\n * 不能只看段落端点——`alongPath` 现在是线性的，但动作原语随时可能改成\r\n * 带弧线/弹跳的轨迹，那时端点就不再是极值，漏采样就会把角色裁掉半截。\r\n */\r\nfunction planBounds(plan: Slice[], drawScale: number): Bounds {\r\n  const half = (ACTOR.bodyWidth / 2) * drawScale;\r\n  let minX = Infinity;\r\n  let maxX = -Infinity;\r\n  let maxY = -Infinity;\r\n  for (const slice of plan) {\r\n    const n = 4;\r\n    for (let i = 0; i <= n; i++) {\r\n      const p = poseAt(slice.input, (slice.durationFrames * i) / n);\r\n      const x = p.root[0] + slice.carry[0];\r\n      const y = p.root[1] + slice.carry[1];\r\n      minX = Math.min(minX, x - half);\r\n      maxX = Math.max(maxX, x + half);\r\n      maxY = Math.max(maxY, actorHeadTop(y, drawScale));\r\n    }\r\n  }\r\n  return { minX, maxX, minY: 0, maxY };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 一个角色\r\n *\r\n * 角色之间**只共享相机**，不共享姿态、不共享缩放基准以外的任何东西。\r\n * 造型缩放（rig.scale）作用在角色自己身上：小松鼠比小熊矮，但两者的世界\r\n * 位置、与滑梯的比例都由同一个 ppu 决定——这正是\"比例一致\"的含义。\r\n * ------------------------------------------------------------------ */\r\n\r\nconst Figure2D: React.FC<{\r\n  rig: ActorRig;\r\n  pose: Pose;\r\n  facing: 1 | -1;\r\n  /** 统一相机：画面中心 x、地面行、每世界单位多少像素 */\r\n  camera: { cx: number; groundY: number; ppu: number };\r\n  /** 造型缩放（rig.scale） */\r\n  scale: number;\r\n  accent: string;\r\n  dribble: { ball: Tri; squash: number } | null;\r\n  /** 远景角色压暗一点，前后关系不用描边也读得出来 */\r\n  dim?: number;\r\n}> = ({ rig, pose, facing, camera, scale, accent, dribble, dim = 1 }) => {\r\n  const { cx, groundY, ppu } = camera;\r\n  const s = ppu * scale;\r\n  const root = pose.root;\r\n\r\n  /**\r\n   * 局部坐标（相对髋部）→ 屏幕。\r\n   *\r\n   * 两步张开的写法是必要的：**世界位置不镜像，只有角色自身的左右镜像**。\r\n   * 以前写成 `(root[0] + lx) * facing`，位置和形状一起翻——后果不是角色走反，\r\n   * 而是\"取景按世界坐标算、画面按镜像后的坐标画\"：\r\n   *   - 向左走的幕，包围盒算在左半边（平移把左半边让出来），角色却画在右半边，\r\n   *     半个身子出画；\r\n   *   - 布景和道具摆在角色旁边时，角色一转身它们就跳到另一侧。\r\n   * 现在 root 走世界坐标、local 走 facing，取景与绘制用的是同一套坐标。\r\n   */\r\n  const cosL = Math.cos(pose.rotZ);\r\n  const sinL = Math.sin(pose.rotZ);\r\n  const project: Projector = (p) => {\r\n    const lx = p[0] * cosL - p[1] * sinL;\r\n    const ly = p[0] * sinL + p[1] * cosL;\r\n    /**\r\n     * 横向：世界位置走 ppu，身体尺寸走 s。**两者不能混**。\r\n     *\r\n     * 上一版写的是 `root[0] * s`（s = ppu × rig.scale），于是\"体型缩小\"顺带把\r\n     * 站位也搬了：松鼠（0.82）站在世界 x=−1.6 时，画面上出现在 −1.31——离\r\n     * 画面中心近了 18%。单角色幕看不出来（root[0]=0），双人幕一眼就露馅：\r\n     * 站位是算出来的，两个人体型的差异却把间距压缩了。\r\n     */\r\n    return [cx + root[0] * ppu + lx * s * facing, groundY - (root[1] + ly) * s];\r\n  };\r\n\r\n  /**\r\n   * 世界物体（球、地上的影子）只做\"世界 → 屏幕\"，**不乘角色造型缩放**。\r\n   * 球不会因为拍球的是松鼠就变小：它不属于角色，属于世界。\r\n   */\r\n  const projectWorld: Projector = (p) => [cx + p[0] * ppu, groundY - p[1] * ppu];\r\n\r\n  const head = project([0, SPEC.headY, 0.02]);\r\n  const headR = SPEC.headR * s;\r\n  const bodyCenter = project([0, 0.15, 0]);\r\n  const bodyW = SPEC.torsoR * s * 0.95;\r\n  const bodyH = 0.33 * s;\r\n  const lean = (pose.rotZ * 180) / Math.PI;\r\n  const hipPoint = project([0, 0, 0]);\r\n  const torsoTransform = `rotate(${lean} ${hipPoint[0]} ${hipPoint[1]})`;\r\n  // 阴影永远在地面上，不参与角色旋转，也不参与镜像（它标的是世界里的落点）\r\n  const shadowX = cx + root[0] * ppu;\r\n\r\n  const legColor = shade(rig.fur, 0.84);\r\n  const armColor = rig.fur;\r\n\r\n  return (\r\n    <g opacity={dim}>\r\n      {/* 贴地假阴影：跟着髋部走，离地越高越淡（climb 时才明显） */}\r\n      <ellipse\r\n        cx={shadowX}\r\n        cy={groundY}\r\n        rx={Math.max(40, bodyW * 1.15)}\r\n        ry={Math.max(9, bodyW * 0.2)}\r\n        fill=\"#1b2a33\"\r\n        opacity={clamp(0.2 - (root[1] - SPEC.standHipY) * 0.26, 0.02, 0.2)}\r\n      />\r\n\r\n      {/* 远侧：先画 L，躯干与头压在上面，R 侧留到最后 */}\r\n      <Limb2D\r\n        pivot={[-SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        target={pose.footL}\r\n        bend={0.16}\r\n        maxLen={SPEC.legLen}\r\n        width={0.18 * s}\r\n        color={legColor}\r\n        capColor={legColor}\r\n        capRadius={0.105 * s}\r\n        capFlat={0.72}\r\n        project={project}\r\n      />\r\n      <g transform={torsoTransform}>\r\n        {/* 躯干 + 肚皮 */}\r\n        <ellipse\r\n          cx={bodyCenter[0]}\r\n          cy={bodyCenter[1]}\r\n          rx={bodyW}\r\n          ry={bodyH}\r\n          fill={rig.fur}\r\n          stroke={shade(rig.fur)}\r\n          strokeWidth={4}\r\n        />\r\n        <ellipse\r\n          cx={bodyCenter[0]}\r\n          cy={bodyCenter[1] + bodyH * 0.1}\r\n          rx={bodyW * 0.6}\r\n          ry={bodyH * 0.7}\r\n          fill={rig.belly}\r\n          opacity={0.95}\r\n        />\r\n        {/* 尾巴：从躯干侧后方露出一点，纯装饰但让剪影不平 */}\r\n        <ellipse\r\n          cx={bodyCenter[0] - facing * bodyW * 0.92}\r\n          cy={bodyCenter[1] + bodyH * 0.34 + pose.tailSwing * 10}\r\n          rx={bodyW * (rig.tail === 'bushy' ? 0.32 : 0.2)}\r\n          ry={bodyH * (rig.tail === 'bushy' ? 0.28 : 0.18)}\r\n          fill={rig.tail === 'stub' ? rig.belly : rig.fur}\r\n          stroke={shade(rig.fur)}\r\n          strokeWidth={3}\r\n        />\r\n      </g>\r\n\r\n      <Head2D rig={rig} head={head} r={headR} tilt={pose.headTilt} />\r\n\r\n      {/* 手臂统一画在头之后：攀爬时手要举过头顶，压在躯干下面等于没举手 */}\r\n      <Limb2D\r\n        pivot={[-SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        target={pose.handL}\r\n        bend={-0.16}\r\n        maxLen={SPEC.armLen}\r\n        width={0.17 * s}\r\n        color={armColor}\r\n        capColor={rig.belly}\r\n        capRadius={0.082 * s}\r\n        project={project}\r\n      />\r\n\r\n      {/* 近侧 */}\r\n      <Limb2D\r\n        pivot={[SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        target={pose.footR}\r\n        bend={0.16}\r\n        maxLen={SPEC.legLen}\r\n        width={0.18 * s}\r\n        color={legColor}\r\n        capColor={legColor}\r\n        capRadius={0.105 * s}\r\n        capFlat={0.72}\r\n        project={project}\r\n      />\r\n      <Limb2D\r\n        pivot={[SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        target={pose.handR}\r\n        bend={-0.16}\r\n        maxLen={SPEC.armLen}\r\n        width={0.17 * s}\r\n        color={armColor}\r\n        capColor={rig.belly}\r\n        capRadius={0.082 * s}\r\n        project={project}\r\n      />\r\n\r\n      {/* 球：画在近侧肢体之后——球在小熊身前，压住前臂才像\"手在球上\" */}\r\n      {dribble\r\n        ? (() => {\r\n            const bp = projectWorld(dribble.ball);\r\n            const r = BALL_RADIUS * ppu;\r\n            const groundP = projectWorld([dribble.ball[0], 0, dribble.ball[2]]);\r\n            return (\r\n              <g>\r\n                <ellipse\r\n                  cx={groundP[0]}\r\n                  cy={groundY}\r\n                  rx={r * (0.9 - (dribble.ball[1] - 0.27) * 0.3)}\r\n                  ry={r * 0.26}\r\n                  fill=\"#1b2a33\"\r\n                  opacity={clamp(0.2 - (dribble.ball[1] - 0.27) * 0.18, 0.04, 0.2)}\r\n                />\r\n                <g transform={`translate(${bp[0]} ${bp[1]}) scale(${1 / dribble.squash} ${dribble.squash})`}>\r\n                  <circle r={r} fill=\"#ef5f58\" stroke=\"#c8443e\" strokeWidth={5} />\r\n                  {/* 球缝画在球面内部：画成外圈的弧会被读成\"红色球带蓝边\" */}\r\n                  <path\r\n                    d={`M ${-r * 0.96} ${-r * 0.16} Q 0 ${r * 0.5} ${r * 0.96} ${-r * 0.16}`}\r\n                    fill=\"none\"\r\n                    stroke={accent}\r\n                    strokeWidth={r * 0.13}\r\n                    opacity={0.85}\r\n                  />\r\n                  <path\r\n                    d={`M ${-r * 0.18} ${-r * 0.97} Q ${r * 0.42} 0 ${-r * 0.18} ${r * 0.97}`}\r\n                    fill=\"none\"\r\n                    stroke={accent}\r\n                    strokeWidth={r * 0.13}\r\n                    opacity={0.85}\r\n                  />\r\n                </g>\r\n              </g>\r\n            );\r\n          })()\r\n        : null}\r\n    </g>\r\n  );\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 主组件\r\n * ------------------------------------------------------------------ */\r\n\r\nexport const Puppet2D: React.FC<{ scene: Puppet2DScene; frame: number }> = ({ scene, frame }) => {\r\n  const mainRig = scene.rig;\r\n  const accent = scene.accent || '#4d96ff';\r\n  const mainScale = mainRig.scale || 1;\r\n  const world = normalizeWorld(scene.world);\r\n\r\n  const coSpec = scene.coStar ?? null;\r\n  const coRig = coSpec ? coSpec.rig : null;\r\n  const coScale = coRig ? coRig.scale || 1 : 1;\r\n\r\n  // overlayFrom 是\"场景进度的比例\"，所以分母用场景帧数而不是动作串总帧数\r\n  const totalFrames = Math.max(1, scene.durationFrames);\r\n\r\n  /**\r\n   * 站位。双人幕的两个人不是\"各站各的\"：间距由手臂够得着决定，\r\n   * 有滑梯时整对挪到爬梯左侧的空地（见 world.duoStations）。\r\n   *\r\n   * 站位只依赖场地几何，与\"这一节课讲什么\"无关；算在渲染层是因为**场地几何\r\n   * 在渲染层**（后端的注册表只有滑梯坐标，没有\"空地\"这个概念）。\r\n   */\r\n  const stations = coSpec ? duoStations(world ?? { venue: 'meadow' }) : null;\r\n\r\n  const mainPlan = buildPlan({\r\n    motion: scene.motion,\r\n    sequence: scene.sequence,\r\n    durationFrames: totalFrames,\r\n    start: scene.start,\r\n    end: scene.end,\r\n    steps: scene.steps,\r\n    bounce: scene.bounce,\r\n    ballRestY: scene.ballRestY,\r\n  });\r\n  const coPlan = coSpec\r\n    ? buildPlan({\r\n        motion: coSpec.motion,\r\n        sequence: coSpec.sequence,\r\n        durationFrames: coSpec.durationFrames ?? totalFrames,\r\n        start: coSpec.start,\r\n        end: coSpec.end,\r\n        steps: coSpec.steps,\r\n      })\r\n    : null;\r\n\r\n  // 站位是\"整条播放表的平移\"：位置写在世界坐标里，不写进每个动作的默认轨迹\r\n  if (stations && coPlan) {\r\n    for (const slice of mainPlan) slice.carry[0] += stations[0];\r\n    for (const slice of coPlan) slice.carry[0] += stations[1];\r\n  }\r\n\r\n  /**\r\n   * 场地与\"梯子落点\"。\r\n   *\r\n   * 有了世界之后，爬梯的横向落点不再由动作注册表单独决定：梯子长在滑梯上，\r\n   * 位置由滑梯几何算（worldLadderX）。所以整条动作串被整体平移，让爬梯段\r\n   * 正好落在世界里的那把梯子上——平移量很可能只有 0.05 个单位，但它是\r\n   * **算式**，不是\"刚好差不多\"：改滑梯尺寸时手不会突然悬在梯子外面。\r\n   *\r\n   * 只对主角色做：梯子是这一幕主角色在用的装置，副角色不该被拽到梯子旁边。\r\n   */\r\n  const climbSlice = mainPlan.find((slice) => slice.motion === 'climb') ?? null;\r\n  const worldLadder = world ? worldLadderX(world) : null;\r\n  if (worldLadder !== null && climbSlice) {\r\n    const climbStartX = (climbSlice.input.start?.[0] ?? 0) + climbSlice.carry[0];\r\n    const dx = worldLadder - climbStartX;\r\n    for (const slice of mainPlan) slice.carry[0] += dx;\r\n  }\r\n\r\n  const main = playAt(mainPlan, frame);\r\n  const co = coPlan ? playAt(coPlan, frame) : null;\r\n  const pose = main.pose;\r\n  const activeMotion: MotionOp = main.active.motion;\r\n  const root = pose.root;\r\n\r\n  // 拍球需要球本体：球心由同一个 dribblePose 算出，所以\"掌搭球顶\"和 3D 一样\r\n  // 是同一个变量决定的，不靠两条时间线对齐。串演序列里不会有 dribble。\r\n  const dribble =\r\n    activeMotion === 'dribble'\r\n      ? dribblePose(main.active.input, main.localFrame)\r\n      : null;\r\n\r\n  // 朝向：向右走时镜像。没有 rotY 的动作按起点→终点决定，避免\"倒着走\"\r\n  const dirX = (main.active.input.end?.[0] ?? 0) - (main.active.input.start?.[0] ?? 0);\r\n  const facing: 1 | -1 =\r\n    pose.rotY > 0.2 ? 1 : pose.rotY < -0.2 ? -1 : dirX < -0.05 ? -1 : 1;\r\n  /**\r\n   * 副角色的朝向：默认**面对主角色**。\r\n   * 双人动作的语义是\"对着那个人做事\"，而双方都不动时（hold）位移方向为 0，\r\n   * 按位移推会取 +1——画出来是\"背对着对方递东西\"。\r\n   */\r\n  const coFacing: 1 | -1 = coSpec?.facing ?? (facing === 1 ? -1 : 1);\r\n\r\n  /** 串演里的攀爬段：哪怕不是当前段，取景与梯子也要按它算 */\r\n  const climb = !!climbSlice;\r\n  // 每上一阶的高度：横档间距与它同源，所以手/脚永远落在横档附近\r\n  const climbStep = climbSlice\r\n    ? (poseAt(climbSlice.input, climbSlice.durationFrames).root[1] -\r\n        (climbSlice.input.start?.[1] ?? SPEC.standHipY)) /\r\n      Math.max(1, climbSlice.input.steps ?? 4)\r\n    : 0.21;\r\n  // 梯子要高过举起的手（站地时手在 1.54）：否则爬到一半就没有横档可抓了\r\n  const climbEndY = climbSlice\r\n    ? poseAt(climbSlice.input, climbSlice.durationFrames).root[1] + climbSlice.carry[1]\r\n    : SPEC.standHipY + 0.84;\r\n  const ladderTop = ladderTopY(Math.min(MAX_STAND_Y, climbEndY));\r\n  /**\r\n   * 兜底路径（没有世界数据的旧分镜）的梯子位置：挂在爬梯段落点上。\r\n   * 有世界时梯子长在滑梯上，位置由 worldLadderX 给出，这里不参与。\r\n   */\r\n  const fallbackLadderX = climbSlice\r\n    ? (climbSlice.input.start?.[0] ?? 0) + climbSlice.carry[0]\r\n    : root[0];\r\n\r\n  /**\r\n   * 取景：分两条路。\r\n   *\r\n   * **有世界（新路径）**：缩放由 worldScale 决定，整节课一个值；景别只做\r\n   * 1.0~1.5 倍变焦，镜头按内容平移。于是熊在每一幕都是同一个大小，\r\n   * 熊与滑梯的比例永远是同一个比例——比例一致性来自\"世界只定义一次\"，\r\n   * 不来自\"每一幕都拟合一遍\"。\r\n   *\r\n   * **没有世界（旧分镜缓存）**：仍按这一幕自己的包围盒拟合。这条路只为\r\n   * 不崩而保留，画面与改动前一致。\r\n   *\r\n   * subjectHeight 只在旧路径里用：动作终点的头顶高度会把\"爬得高\"误当成\r\n   * \"角色很大\"，全景被无谓推远（实测梯子会缩到 365px，画面空一半）。\r\n   */\r\n  const subjectHeight = Math.max(\r\n    actorHeadTop(SPEC.standHipY, Math.max(1, mainScale)),\r\n    coRig ? actorHeadTop(SPEC.standHipY, Math.max(1, coScale)) : 0,\r\n  );\r\n\r\n  /** 两个人 + 道具 + 正在使用的装置，全都进焦点盒：谁都不能被裁 */\r\n  const actorBox = unionAll(\r\n    [\r\n      planBounds(mainPlan, Math.max(1, mainScale)),\r\n      ...(coPlan ? [planBounds(coPlan, Math.max(1, coScale))] : []),\r\n    ],\r\n  );\r\n\r\n  const shot = scene.shot ?? (coSpec ? 'medium' : shotForMotion(climb ? 'climb' : activeMotion));\r\n\r\n  /**\r\n   * 这一幕要装进画面的东西：角色轨迹 + 道具 + （如果这一幕在用滑梯）整座滑梯。\r\n   *\r\n   * 用滑梯时把滑梯框进来，是\"爬/指/滑\"这类幕的语义要求：孩子要同时看到\r\n   * \"他在哪\"和\"他在对什么做动作\"。其余幕只框角色，镜头就能稍微推近。\r\n   * 两者的缩放都夹在 [基准缩放, 基准缩放 × 焦距] 之间（见 cameraForWorld），\r\n   * 所以不存在\"这一幕为了装下滑梯把熊缩小\"那种比例漂移。\r\n   */\r\n  const focusBox = unionAll([\r\n    actorBox,\r\n    ...(scene.props || []).map(propBounds),\r\n    ...(world && world.slide && scene.setpiece === 'slide'\r\n      ? [slideBounds(world.slide.start, world.slide.end, Math.max(1, mainScale))]\r\n      : []),\r\n  ]);\r\n\r\n  const ladderX = worldLadder ?? fallbackLadderX;\r\n  const worldCamera = world ? cameraForWorld(world, shot, focusBox) : null;\r\n  const framing = worldCamera\r\n    ? worldCamera\r\n    : framingFor(\r\n        {\r\n          bounds: unionAll([\r\n            actorBox,\r\n            ...(climb ? [ladderBounds(fallbackLadderX, ladderTop)] : []),\r\n            ...(scene.props || []).map(propBounds),\r\n          ]),\r\n          subjectHeight,\r\n        },\r\n        shot,\r\n      );\r\n\r\n  const camera = {\r\n    cx: framing.originX,\r\n    groundY: framing.groundY,\r\n    ppu: framing.ppu,\r\n  };\r\n  const GROUND_Y = framing.groundY;\r\n  const s = framing.ppu * mainScale;\r\n\r\n  /**\r\n   * 布景投影：只做\"世界 → 屏幕\"，不施加躯干倾角、也不施加朝向镜像。\r\n   * 梯子如果跟着角色前倾，就成了\"整个梯子被推歪\"；跟着镜像，就成了\r\n   * \"角色一转身梯子瞬移到另一边\"。物理世界不会因为角色转向而重排。\r\n   *\r\n   * 用 ppu 而不是 s：布景属于世界，不随角色体型缩放（松鼠爬梯时梯子\r\n   * 不该跟着缩 18%）。\r\n   */\r\n  const ppu = framing.ppu;\r\n  const projectWorld: Projector = (p) => [camera.cx + p[0] * ppu, GROUND_Y - p[1] * ppu];\r\n\r\n  const mainTop = GROUND_Y - (root[1] + (SPEC.headY + SPEC.headR) * Math.cos(pose.rotZ)) * s;\r\n\r\n  /* ---------------- 手里的东西 ---------------- */\r\n\r\n  /**\r\n   * 递到对方手里 / 两人一起托着的道具。\r\n   *\r\n   * 挂点用的是**手**（pose.gripLocal），但算到最后一步是屏幕坐标，而且复用\r\n   * 绘制身体时的那条投影——不是\"先换成世界坐标、再投一次\"。原因是体型缩放：\r\n   * 身体的纵向按 s 画（小动物矮一点）、横向按 ppu 放（站位必须准），两次投影\r\n   * 差的那一点落在道具上就是\"苹果悬在掌心外半寸\"。\r\n   */\r\n  const pawOnScreen = (p: Pose, f: 1 | -1, scale: number): [number, number] => {\r\n    const g = gripLocal(p);\r\n    const c = Math.cos(p.rotZ);\r\n    const sn = Math.sin(p.rotZ);\r\n    const sx = camera.ppu * scale;\r\n    const lx = g[0] * c - g[1] * sn;\r\n    const ly = g[0] * sn + g[1] * c;\r\n    return [camera.cx + p.root[0] * camera.ppu + lx * sx * f, camera.groundY - (p.root[1] + ly) * sx];\r\n  };\r\n  const mainGrip = pawOnScreen(pose, facing, mainScale);\r\n  const coGrip = co && coRig ? pawOnScreen(co.pose, coFacing, coScale) : null;\r\n\r\n  let carryPos: [number, number] | null = null;\r\n  if (scene.carry) {\r\n    const by = scene.carry.by ?? (coGrip ? 'shared' : 'self');\r\n    if (by === 'self' || !coGrip) {\r\n      carryPos = mainGrip;\r\n    } else if (by === 'coStar') {\r\n      carryPos = coGrip;\r\n    } else if (by === 'shared') {\r\n      // 两人各托一侧：停在两手之间，随呼吸微微起伏（两只手是同一个姿态函数，所以是同步的）\r\n      carryPos = [\r\n        (mainGrip[0] + coGrip[0]) / 2,\r\n        (mainGrip[1] + coGrip[1]) / 2 + Math.sin(frame / 15) * 0.012 * camera.ppu,\r\n      ];\r\n    } else {\r\n      /**\r\n       * 递给：沿一条很浅的弧线从主角色的手移到副角色的手。\r\n       * 起点与终点都是**当帧的手**，所以两个人一边呼吸一边递，道具也不会脱手。\r\n       *\r\n       * 弧高只有 0.07：抬手 0.22（第一版）时，苹果在两人手之间飞到高处，\r\n       * 画面上是\"东西悬在半空\"——两只手都够不着它，读者就读不出\"在递\"。\r\n       * 递东西本来就是贴着手背过去，弧线只需要破掉直线平移的死板。\r\n       */\r\n      const t = smooth(clamp((frame / totalFrames - 0.18) / 0.46, 0, 1));\r\n      carryPos = [\r\n        mainGrip[0] + (coGrip[0] - mainGrip[0]) * t,\r\n        mainGrip[1] + (coGrip[1] - mainGrip[1]) * t + Math.sin(Math.PI * t) * 0.07 * camera.ppu,\r\n      ];\r\n    }\r\n  }\r\n\r\n  return (\r\n    <div style={{ position: 'absolute', inset: 0 }}>\r\n      {/* 场地：天、地、围栏、树、长椅、沙坑、摩天轮，以及整座滑梯（含爬梯）。\r\n          它用与角色同一个相机投影，所以放大缩小时\"熊和滑梯的比例\"不会变。 */}\r\n      {world && worldCamera ? <WorldLayer world={world} camera={worldCamera} frame={frame} /> : null}\r\n      <svg\r\n        width={1920}\r\n        height={1080}\r\n        viewBox=\"0 0 1920 1080\"\r\n        style={{ position: 'absolute', inset: 0, overflow: 'visible' }}\r\n      >\r\n        {/* 道具画在角色之前：被手指着的东西应该在身体后面，不然会挡住脸。\r\n            坐标是世界单位，和角色/布景走同一条投影——取景一旦平移（内容偏左\r\n            就整体右移），屏幕坐标的道具不会跟着动，角色和道具就会错位。 */}\r\n        {(scene.props || []).map((p, i) => {\r\n          const [px, py] = projectWorld([p.x, p.y, 0]);\r\n          const sizePx = p.size * ppu;\r\n          return (\r\n            <g key={`prop-${i}`} transform={`translate(${px} ${py})`}>\r\n              {/* node 的绘制盒子是 -80..80，按目标尺寸缩放 */}\r\n              <g transform={`scale(${sizePx / 160})`}>{p.node}</g>\r\n              {p.label ? (\r\n                // 标签放道具上方：地面线以下是字幕区，写在下面会被字幕压住\r\n                <text\r\n                  y={-sizePx / 2 - 14}\r\n                  textAnchor=\"middle\"\r\n                  fontSize={34}\r\n                  fontWeight={900}\r\n                  fill={accent}\r\n                  stroke=\"#ffffff\"\r\n                  strokeWidth={6}\r\n                  paintOrder=\"stroke\"\r\n                >\r\n                  {p.label}\r\n                </text>\r\n              ) : null}\r\n            </g>\r\n          );\r\n        })}\r\n\r\n        {/* 梯子必须在角色之前画（背景层），否则会盖住手脚。\r\n            有世界时梯子由 WorldLayer 画——它是滑梯的一部分，不是这一幕的道具；\r\n            这里只保留旧分镜（没有世界数据）的兜底。 */}\r\n        {climb && !worldCamera ? (\r\n          <Ladder\r\n            x={ladderX}\r\n            baseY={0}\r\n            topY={ladderTop}\r\n            spacing={Math.max(LADDER.minRungSpacing, climbStep)}\r\n            project={projectWorld}\r\n            s={ppu}\r\n          />\r\n        ) : null}\r\n\r\n        {/* 第二个人先画：双人幕的主角色是\"接受动作\"的那一侧，压在上面更清楚 */}\r\n        {co && coRig ? (\r\n          <Figure2D\r\n            rig={coRig}\r\n            pose={co.pose}\r\n            facing={coFacing}\r\n            camera={camera}\r\n            scale={coScale}\r\n            accent={accent}\r\n            dribble={null}\r\n            dim={0.97}\r\n          />\r\n        ) : null}\r\n\r\n        <Figure2D\r\n          rig={mainRig}\r\n          pose={pose}\r\n          facing={facing}\r\n          camera={camera}\r\n          scale={mainScale}\r\n          accent={accent}\r\n          dribble={dribble ? { ball: dribble.ball, squash: dribble.squash } : null}\r\n        />\r\n\r\n        {/* 手里的东西画在角色之后：捧在身前的东西压住肚皮才像\"拿着\" */}\r\n        {scene.carry && carryPos\r\n          ? (() => {\r\n              const [px, py] = carryPos;\r\n              const sizePx = scene.carry.size * ppu;\r\n              return (\r\n                <g transform={`translate(${px} ${py})`}>\r\n                  <g transform={`scale(${sizePx / 160})`}>{scene.carry.node}</g>\r\n                  {scene.carry.label ? (\r\n                    <text\r\n                      y={-sizePx / 2 - 14}\r\n                      textAnchor=\"middle\"\r\n                      fontSize={34}\r\n                      fontWeight={900}\r\n                      fill={accent}\r\n                      stroke=\"#ffffff\"\r\n                      strokeWidth={6}\r\n                      paintOrder=\"stroke\"\r\n                    >\r\n                      {scene.carry.label}\r\n                    </text>\r\n                  ) : null}\r\n                </g>\r\n              );\r\n            })()\r\n          : null}\r\n      </svg>\r\n\r\n      {/* 名条：与 3D 舞台同一位置（左上），不压地面也不压字幕 */}\r\n      {scene.label ? (\r\n        <div\r\n          style={{\r\n            position: 'absolute',\r\n            left: 64,\r\n            top: 132,\r\n            padding: '8px 26px',\r\n            borderRadius: 999,\r\n            background: accent,\r\n            color: '#fff',\r\n            fontSize: 34,\r\n            fontWeight: 900,\r\n            whiteSpace: 'nowrap',\r\n            boxShadow: '0 8px 18px rgba(0,0,0,0.16)',\r\n          }}\r\n        >\r\n          {scene.label}\r\n        </div>\r\n      ) : null}\r\n\r\n      {/* 覆盖层：对话气泡这类 HTML 元素挂在角色之上。\r\n          出场时刻可延后（overlayFrom）：多动作幕里，气泡从第一帧就挂着等于剧透，\r\n          孩子还没看到\"指\"，台词已经先出现了。 */}\r\n      {scene.overlay ? (\r\n        <div\r\n          style={{\r\n            position: 'absolute',\r\n            inset: 0,\r\n            opacity:\r\n              scene.overlayFrom === undefined\r\n                ? 1\r\n                : clamp((frame / totalFrames - scene.overlayFrom) / 0.04, 0, 1),\r\n          }}\r\n        >\r\n          {scene.overlay}\r\n        </div>\r\n      ) : null}\r\n\r\n      {/* 越界自检：climb 的参数如果给得太高，角色会顶出画面。\r\n          这里不做自动缩放（那会让同一部片子里角色忽大忽小），\r\n          只把状态暴露给上层——渲染服务的抽帧检查会看到这个标记。 */}\r\n      {mainTop < 90 ? <div data-puppet-warning=\"head-cropped\" style={{ display: 'none' }} /> : null}\r\n    </div>\r\n  );\r\n};\r\n"
  },
  {
    "path": "three/ThreeActionStage.tsx",
    "content": "/**\r\n * 三维动作舞台（方案 A：纯代码参数化 3D）\r\n *\r\n * 这份文件是 3D 舞台的唯一实现来源。它同时被两处使用：\r\n *  1. 后端生成的任务目录：buildGeneratedLessonTsx() 通过 three-stage-template.ts\r\n *     把它原样写进 .generated/remotion-tasks/task-<id>/three/ThreeActionStage.tsx，\r\n *     GeneratedLesson 再 import 进来；\r\n *  2. 本地预览：src/__preview3d 直接 import 本文件，用来抽帧验收。\r\n * 改完这里要跑 `npm run sync:three-stage`（backend）把模板串同步过去。\r\n *\r\n * 为什么全用几何体而不加载模型：\r\n * 滑梯和拍球的关键不是\"像不像真熊\"，而是\"身体贴着滑面\"\"掌球同帧接触\"。\r\n * 几何体拼出来的角色有真实的头/躯干/四肢与关节枢轴，四肢用\"从肩到目标点\"\r\n * 的定向算法定位，接触点因此是算出来的而不是画上去的。\r\n *\r\n * 确定性约束（Remotion 硬要求，改这个文件时务必守住）：\r\n *  - 只用 useCurrentFrame() 推帧，禁止 useFrame / requestAnimationFrame / delta；\r\n *  - 禁止 Math.random()、Date.now()、performance.now()；\r\n *  - 禁止自带时钟的 drei helper（Float / Sparkles / Stars / Trail …）；\r\n *  - 阴影不用实时阴影贴图（无头 WebGL 下帧序与耗时都不可控），用贴地圆片假阴影。\r\n */\r\n\r\nimport React from \"react\";\r\nimport { ThreeCanvas } from \"@remotion/three\";\r\nimport { useVideoConfig } from \"remotion\";\r\n// 姿态解算在 character/pose.ts（与渲染器无关）。这个文件只负责\"把关节目标点\r\n// 画成圆柱和四元数\"，不负责\"角色该怎么动\"——那是 pose 层的事。\r\nimport {\r\n  ACTOR,\r\n  BALL_RADIUS,\r\n  SPEC,\r\n  clamp,\r\n  dribblePose,\r\n  slidePose,\r\n  type Pose,\r\n  type Tri,\r\n} from \"../character/pose\";\r\n// 取景规则与布景几何都在 character/ 下：相机不再是\"每个动作一组魔法数字\"，\r\n// 而是由内容包围盒 + 景别反推，地面永远落在 STAGE.groundY。\r\nimport {\r\n  framingFor,\r\n  shotForMotion,\r\n  STAGE,\r\n  unionAll,\r\n  type Bounds,\r\n  type Shot,\r\n} from \"../character/stage-layout\";\r\nimport { LADDER, SLIDE, actorHeadTop, ladderRungYs, slideBounds, slideLadderX } from \"../character/setpiece\";\r\nimport { WorldLayer } from \"../character/WorldLayer\";\r\nimport { cameraForWorld, normalizeWorld } from \"../character/world\";\r\n\r\nexport type ThreeRig = {\r\n  fur: string;\r\n  belly: string;\r\n  ears: \"round\" | \"long\" | \"pointy\" | \"flap\" | \"none\";\r\n  tail: \"stub\" | \"long\" | \"bushy\";\r\n  scale: number;\r\n};\r\n\r\nexport type ThreeStageScene = {\r\n  motion: \"slide\" | \"dribble\";\r\n  /** GLB 分支用；程序化分支只拿它做日志与标签 */\r\n  actorId: string;\r\n  rig: ThreeRig;\r\n  start: [number, number, number];\r\n  end: [number, number, number];\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  durationFrames: number;\r\n  accent: string;\r\n  label?: string;\r\n};\r\n\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 取景\r\n *\r\n * 相机不再有\"按动作写死的一套参数\"（曾经是 slide: z=8/lookY=1.55、\r\n * dribble: z=6.2/lookY=1.15）。那套写法有两个后果：地面行跟着动作跳\r\n * （2D 856、3D 827），以及\"结构再高一点就出画\"无法自动处理。\r\n *\r\n * 现在只由取景定律给一个 ppu，相机距离与 lookY/lookX 反推：\r\n *   屏幕Y = 540 + lookY * ppu ⇒ lookY = (地面行 − 540) / ppu\r\n *   屏幕X = 960 − (lookX − x) * ppu ⇒ lookX = 内容中心的世界 x\r\n *   z = 1080 / (2 * ppu * tan(fov/2))\r\n *\r\n * 注意：不能用 camera.position.y 抬高视角——R3F 的默认相机会 lookAt(0,0,0)，\r\n * 抬高相机等于让画面俯视，地面会被拉到中线。相机留在 y=0，把世界下移 lookY。\r\n * 横向同理：相机不动，世界整体平移 lookX。\r\n * ------------------------------------------------------------------ */\r\n\r\n/**\r\n * 非滑梯幕的内容范围：角色轨迹 + 球。\r\n *\r\n * 为什么采样而不是只取末帧：拍球是往复运动，末帧多半不是极值；改了动作\r\n * 曲线之后\"末帧即极值\"这个假设也不成立。采样是通用的——新增动作不用改这里。\r\n */\r\nfunction actorBounds(scene: ThreeStageScene, scale: number): Bounds {\r\n  const n = 12;\r\n  const dur = Math.max(1, scene.durationFrames);\r\n  const half = (ACTOR.bodyWidth / 2) * scale;\r\n  let minX = Infinity;\r\n  let maxX = -Infinity;\r\n  let maxY = -Infinity;\r\n  for (let i = 0; i <= n; i++) {\r\n    const d = dribblePose(scene, (dur * i) / n);\r\n    const root = d.pose.root;\r\n    minX = Math.min(minX, root[0] - half, d.ball[0] - BALL_RADIUS);\r\n    maxX = Math.max(maxX, root[0] + half, d.ball[0] + BALL_RADIUS);\r\n    maxY = Math.max(maxY, actorHeadTop(root[1], scale), d.ball[1] + BALL_RADIUS);\r\n  }\r\n  return { minX, maxX, minY: 0, maxY };\r\n}\r\n\r\n\r\n/**\r\n * 把一根肢体从 from 指向 to：返回中点位置、四元数（+Y 轴指向目标方向）、\r\n * 圆柱段长度。用四元数解析式而不是逐帧建 Object3D.lookAt，\r\n * 省掉一份可变的场景对象，也保证同样输入永远同样结果。\r\n */\r\nfunction limb(from: Tri, to: Tri) {\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const dz = to[2] - from[2];\r\n  const len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 0.0001;\r\n  const ux = dx / len;\r\n  const uy = dy / len;\r\n  const uz = dz / len;\r\n  // q ∝ (cross(a,b), 1 + a·b)，其中 a=(0,1,0)\r\n  const cx = uz;\r\n  const cz = -ux;\r\n  const w = 1 + uy;\r\n  const n = Math.sqrt(cx * cx + w * w + cz * cz) || 1;\r\n  const quaternion: [number, number, number, number] =\r\n    w < 1e-6 ? [1, 0, 0, 0] : [cx / n, 0, cz / n, w / n];\r\n  return {\r\n    position: [(from[0] + to[0]) / 2, (from[1] + to[1]) / 2, (from[2] + to[2]) / 2] as Tri,\r\n    quaternion,\r\n    length: len,\r\n  };\r\n}\r\n\r\n/** 一段肢体：胶囊体（圆柱段留出两端半球，避免关节处露缝） */\r\nconst Limb: React.FC<{\r\n  from: Tri;\r\n  to: Tri;\r\n  radius: number;\r\n  color: string;\r\n  /** 末端球（手掌/脚掌） */\r\n  capColor?: string;\r\n  capRadius?: number;\r\n  /**\r\n   * 最大长度。目标点超出这个距离时沿方向钳制——手要够球，但手臂不能被拉长：\r\n   * 拉长的手臂在画面上是\"橡皮人\"，比够不到更糟。当前动作的目标点都在\r\n   * 0.45 以内，这里只是安全网（斜接道具或极端时长时才起作用）。\r\n   */\r\n  maxLength?: number;\r\n}> = ({ from, to, radius, color, capColor, capRadius, maxLength }) => {\r\n  let target: Tri = to;\r\n  if (maxLength) {\r\n    const dx = to[0] - from[0];\r\n    const dy = to[1] - from[1];\r\n    const dz = to[2] - from[2];\r\n    const len = Math.sqrt(dx * dx + dy * dy + dz * dz);\r\n    if (len > maxLength) {\r\n      const k = maxLength / len;\r\n      target = [from[0] + dx * k, from[1] + dy * k, from[2] + dz * k];\r\n    }\r\n  }\r\n  const g = limb(from, target);\r\n  const bodyLen = Math.max(0.01, g.length - radius * 1.4);\r\n  const cap = capRadius ?? radius * 1.25;\r\n  return (\r\n    <group>\r\n      <mesh position={g.position} quaternion={g.quaternion}>\r\n        <capsuleGeometry args={[radius, bodyLen, 6, 14]} />\r\n        <meshStandardMaterial color={color} roughness={0.85} metalness={0} />\r\n      </mesh>\r\n      {capColor ? (\r\n        <mesh position={target}>\r\n          <sphereGeometry args={[cap, 12, 12]} />\r\n          <meshStandardMaterial color={capColor} roughness={0.8} metalness={0} />\r\n        </mesh>\r\n      ) : null}\r\n    </group>\r\n  );\r\n};\r\n\r\nconst Ears: React.FC<{ rig: ThreeRig; headY: number; headR: number }> = ({ rig, headY, headR }) => {\r\n  const y = headY + headR * 0.72;\r\n  const x = headR * 0.62;\r\n  const color = rig.fur;\r\n  if (rig.ears === \"none\") return null;\r\n  if (rig.ears === \"long\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh key={side} position={[side * x * 0.7, y + 0.2, -0.02]} scale={[1, 1, 0.55]}>\r\n            <capsuleGeometry args={[0.075, 0.26, 5, 10]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  if (rig.ears === \"pointy\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh key={side} position={[side * x * 0.9, y, -0.01]} rotation={[0, 0, side * 0.32]}>\r\n            <coneGeometry args={[0.1, 0.22, 10]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  if (rig.ears === \"flap\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh\r\n            key={side}\r\n            position={[side * (headR + 0.12), headY + 0.02, 0]}\r\n            scale={[0.5, 1, 1]}\r\n          >\r\n            <sphereGeometry args={[0.19, 14, 14]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  return (\r\n    <group>\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={side} position={[side * x, y, 0]} scale={[1, 1, 0.6]}>\r\n          <sphereGeometry args={[0.115, 14, 14]} />\r\n          <meshStandardMaterial color={color} roughness={0.85} />\r\n        </mesh>\r\n      ))}\r\n    </group>\r\n  );\r\n};\r\n\r\nconst Tail: React.FC<{ rig: ThreeRig; swing: number }> = ({ rig, swing }) => {\r\n  if (rig.tail === \"stub\") {\r\n    return (\r\n      <mesh position={[0, -0.02, -0.28]}>\r\n        <sphereGeometry args={[0.11, 12, 12]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.9} />\r\n      </mesh>\r\n    );\r\n  }\r\n  if (rig.tail === \"bushy\") {\r\n    return (\r\n      <mesh position={[0, 0.12, -0.36]} rotation={[0.5, 0, swing * 0.4]} scale={[0.8, 1.2, 0.9]}>\r\n        <sphereGeometry args={[0.17, 14, 14]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.9} />\r\n      </mesh>\r\n    );\r\n  }\r\n  return (\r\n    <mesh position={[0.03, 0.1, -0.3]} rotation={[0.7, 0, swing * 0.5]} scale={[0.55, 1, 0.55]}>\r\n      <capsuleGeometry args={[0.06, 0.22, 5, 10]} />\r\n      <meshStandardMaterial color={rig.fur} roughness={0.9} />\r\n    </mesh>\r\n  );\r\n};\r\n\r\n\r\nconst ProceduralChar: React.FC<{ rig: ThreeRig; pose: Pose }> = ({ rig, pose }) => {\r\n  const s = rig.scale;\r\n  return (\r\n    <group position={pose.root} rotation={[0, pose.rotY, pose.rotZ]} scale={[s, s, s]}>\r\n      {/* 躯干 */}\r\n      <mesh position={[0, 0.16, 0]} scale={[1, 1.05, 0.85]}>\r\n        <capsuleGeometry args={[SPEC.torsoR, 0.24, 8, 18]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.88} />\r\n      </mesh>\r\n      {/* 肚皮 */}\r\n      <mesh position={[0, 0.1, 0.2]} scale={[0.72, 0.82, 0.4]}>\r\n        <sphereGeometry args={[SPEC.torsoR, 16, 16]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.9} />\r\n      </mesh>\r\n      {/* 头 */}\r\n      <mesh position={[0, SPEC.headY, 0.02]} rotation={[pose.headTilt, 0, 0]}>\r\n        <sphereGeometry args={[SPEC.headR, 20, 20]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.88} />\r\n      </mesh>\r\n      {/* 口鼻 + 鼻头 + 眼睛 */}\r\n      <mesh position={[0, SPEC.headY - 0.07, SPEC.headR * 0.82]} scale={[1, 0.78, 0.85]}>\r\n        <sphereGeometry args={[0.135, 16, 16]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.92} />\r\n      </mesh>\r\n      <mesh position={[0, SPEC.headY - 0.03, SPEC.headR * 1.12]}>\r\n        <sphereGeometry args={[0.058, 12, 12]} />\r\n        <meshStandardMaterial color=\"#3b2a20\" roughness={0.7} />\r\n      </mesh>\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={side} position={[side * 0.108, SPEC.headY + 0.075, SPEC.headR * 0.9]}>\r\n          <sphereGeometry args={[0.036, 10, 10]} />\r\n          <meshStandardMaterial color=\"#241812\" roughness={0.6} />\r\n        </mesh>\r\n      ))}\r\n      <Ears rig={rig} headY={SPEC.headY} headR={SPEC.headR} />\r\n      <Tail rig={rig} swing={pose.tailSwing} />\r\n      {/* 四肢：肩/髋为共同枢轴，末端用目标点定向 */}\r\n      <Limb\r\n        from={[-SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        to={pose.handL}\r\n        radius={0.082}\r\n        color={rig.fur}\r\n        capColor={rig.belly}\r\n        capRadius={0.095}\r\n        maxLength={SPEC.armLen}\r\n      />\r\n      <Limb\r\n        from={[SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        to={pose.handR}\r\n        radius={0.082}\r\n        color={rig.fur}\r\n        capColor={rig.belly}\r\n        capRadius={0.095}\r\n        maxLength={SPEC.armLen}\r\n      />\r\n      <Limb\r\n        from={[-SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        to={pose.footL}\r\n        radius={0.095}\r\n        color={rig.fur}\r\n        capColor={rig.fur}\r\n        capRadius={0.11}\r\n        maxLength={SPEC.legLen}\r\n      />\r\n      <Limb\r\n        from={[SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        to={pose.footR}\r\n        radius={0.095}\r\n        color={rig.fur}\r\n        capColor={rig.fur}\r\n        capRadius={0.11}\r\n        maxLength={SPEC.legLen}\r\n      />\r\n    </group>\r\n  );\r\n};\r\n\r\n/** 贴地假阴影：一个压扁的圆片，无实时阴影贴图，帧序无关 */\r\nconst Blob: React.FC<{ x: number; z: number; y?: number; r: number; opacity: number }> = ({\r\n  x,\r\n  z,\r\n  y = 0.012,\r\n  r,\r\n  opacity,\r\n}) => (\r\n  <mesh position={[x, y, z]} rotation={[-Math.PI / 2, 0, 0]} scale={[r, r * 0.55, 1]}>\r\n    <circleGeometry args={[1, 24]} />\r\n    <meshBasicMaterial color=\"#1b2a33\" transparent opacity={opacity} />\r\n  </mesh>\r\n);\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 道具：滑梯\r\n *\r\n * 几何全部来自 character/setpiece.ts。这里只做\"参数 → mesh\"的翻译，\r\n * 因为\"平台多厚、护边多高\"同时决定取景高度（见 slideWorldHeight），\r\n * 两处各写一份，就会出现\"画面装下了结构、取景却算矮了\"的分裂。\r\n * ------------------------------------------------------------------ */\r\nconst SlideRig: React.FC<{ start: readonly [number, number, number]; end: readonly [number, number, number] }> = ({ start, end }) => {\r\n  const dx = end[0] - start[0];\r\n  const dy = end[1] - start[1];\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 1;\r\n  const angle = Math.atan2(dy, dx);\r\n  const mid: Tri = [(start[0] + end[0]) / 2, (start[1] + end[1]) / 2, 0];\r\n  // 爬梯的位置与横档高度都从 setpiece 取，和二维 WorldLayer 是同一份：\r\n  // 同一个梯子不能有两种密度，否则切换渲染器时梯子会整个换一个样子。\r\n  const ladderX = slideLadderX(start, end);\r\n  const rungYs = ladderRungYs(start[1]);\r\n  const deckColor = \"#ffb347\";\r\n  const railColor = \"#ff8f4d\";\r\n  const postColor = \"#cf9a63\";\r\n  return (\r\n    <group>\r\n      {/* 滑面 */}\r\n      <mesh position={mid} rotation={[0, 0, angle]}>\r\n        <boxGeometry args={[len, SLIDE.deckThickness, SLIDE.deckWidth]} />\r\n        <meshStandardMaterial color={deckColor} roughness={0.7} />\r\n      </mesh>\r\n      {/* 两侧护边 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={side}\r\n          position={[mid[0], mid[1] + SLIDE.railLift, side * SLIDE.railHalf]}\r\n          rotation={[0, 0, angle]}\r\n        >\r\n          <boxGeometry args={[len, SLIDE.railHeight, SLIDE.railThickness]} />\r\n          <meshStandardMaterial color={railColor} roughness={0.65} />\r\n        </mesh>\r\n      ))}\r\n      {/* 顶端平台 */}\r\n      <mesh position={[start[0] - Math.cos(angle) * SLIDE.platformInset, start[1] + SLIDE.platformThickness / 2, 0]}>\r\n        <boxGeometry args={[SLIDE.platformWidth, SLIDE.platformThickness, SLIDE.deckWidth]} />\r\n        <meshStandardMaterial color={deckColor} roughness={0.7} />\r\n      </mesh>\r\n      {/* 顶端支柱：只留两根，四根会把左侧糊成一片栅栏 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={`post-${side}`}\r\n          position={[start[0] - Math.cos(angle) * SLIDE.topPostInset, start[1] / 2 - SLIDE.postLift, side * SLIDE.topPostHalfZ]}\r\n        >\r\n          <cylinderGeometry args={[SLIDE.topPostRadius, SLIDE.topPostRadius, Math.max(0.3, start[1] - SLIDE.topPostFoot), 10]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {/* 底端支柱：滑道末端离地 0.3，不撑起来就是一块悬空的板 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={`end-post-${side}`} position={[end[0] - SLIDE.endPostInset, end[1] / 2, side * SLIDE.endPostHalfZ]}>\r\n          <cylinderGeometry args={[SLIDE.endPostRadius, SLIDE.endPostRadius, Math.max(0.12, end[1] - SLIDE.endPostFoot), 10]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {/* 爬梯：两根立杆（左右分开，正面才看得出是梯子）+ 横档。\r\n          杆距 = 横档长的一半，与 2D 梯子同一个宽度（setpiece.LADDER 导出）。 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={`ladder-${side}`}\r\n          position={[ladderX + side * LADDER.railHalf, start[1] / 2 - SLIDE.postLift, 0]}\r\n        >\r\n          <cylinderGeometry args={[LADDER.sidePostRadius, LADDER.sidePostRadius, Math.max(0.5, start[1] - SLIDE.ladderFoot), 8]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {rungYs.map((y, i) => (\r\n        <mesh\r\n          key={`rung-${i}`}\r\n          position={[ladderX, y, 0]}\r\n          rotation={[0, 0, Math.PI / 2]}\r\n        >\r\n          <cylinderGeometry args={[LADDER.sideRungRadius, LADDER.sideRungRadius, LADDER.sideRungLength, 8]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n    </group>\r\n  );\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 道具：球\r\n *\r\n * 缝线不是\"套一个环\"：torus 的管心落在球面上，就会有一半管子突出轮廓，\r\n * 从侧面看是一圈蓝边（之前那版 radius*0.99 + tube 0.05*radius 就是这个问题，\r\n * 视觉上像给红球描了个蓝边，而不是缝）。正确做法是让 torus 外缘正好等于\r\n * 球半径：major = r - tube，管子嵌进表面，只露出贴近表面的一段。\r\n * ------------------------------------------------------------------ */\r\nconst Ball: React.FC<{ position: Tri; radius: number; squash: number; spin: number }> = ({\r\n  position,\r\n  radius,\r\n  squash,\r\n  spin,\r\n}) => (\r\n  <group position={position} rotation={[spin, 0, 0]} scale={[1 / squash, squash, 1 / squash]}>\r\n    <mesh>\r\n      <sphereGeometry args={[radius, 32, 24]} />\r\n      <meshStandardMaterial color=\"#ef5f58\" roughness={0.55} />\r\n    </mesh>\r\n    {[0, Math.PI / 2].map((rot) => (\r\n      <mesh key={rot} rotation={[rot, 0, 0]}>\r\n        <torusGeometry args={[radius * 0.955, radius * 0.045, 8, 48]} />\r\n        <meshStandardMaterial color=\"#b8382f\" roughness={0.5} />\r\n      </mesh>\r\n    ))}\r\n  </group>\r\n);\r\n\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 舞台\r\n * ------------------------------------------------------------------ */\r\nexport const ThreeActionStage: React.FC<{\r\n  scene: ThreeStageScene;\r\n  /** 场景局部帧（由 GeneratedLesson 的 useLocalFrame 传入，不用 useCurrentFrame：\r\n   *  收尾窗口里画面要被钉在冻结帧上，否则最后一秒会自己动起来） */\r\n  frame: number;\r\n  /** 景别覆盖。不给就按动作判定：slide → wide，dribble → medium */\r\n  shot?: Shot;\r\n  /**\r\n   * 场地（与二维同源）。给了它，相机缩放就是整节课的基准缩放 × 景别变焦，\r\n   * 而不是\"这一幕装得下就多大\"——三维幕和二维幕的熊才是同一个大小。\r\n   */\r\n  world?: unknown;\r\n}> = ({ scene, frame, shot: shotOverride, world: rawWorld }) => {\r\n  const { width, height } = useVideoConfig();\r\n  const accent = scene.accent || \"#4d96ff\";\r\n  const isSlide = scene.motion === \"slide\";\r\n  const scale = scene.rig.scale || 1;\r\n\r\n  /**\r\n   * 滑梯的位置由**场地**说了算，不由分镜说了算。\r\n   *\r\n   * 分镜也可能带 start/end（模型偶尔照抄坐标，旧任务缓存的是上一版默认值）。\r\n   * 它一旦和场地里的滑梯不一致，画面就成了\"熊在这座滑梯上滑、背景里是另一座\"。\r\n   * 动作只表达\"在滑梯上滑\"，几何永远来自 world.slide。\r\n   */\r\n  const world = normalizeWorld(rawWorld);\r\n  const slideGeom =\r\n    isSlide && world && world.slide\r\n      ? { start: world.slide.start, end: world.slide.end }\r\n      : { start: scene.start, end: scene.end };\r\n  const stageScene = isSlide\r\n    ? {\r\n        ...scene,\r\n        start: slideGeom.start as [number, number, number],\r\n        end: slideGeom.end as [number, number, number],\r\n      }\r\n    : scene;\r\n\r\n  /**\r\n   * 取景：观众要看到的是\"这一幕占了世界上哪一块\"，不是\"某个动作该配哪个\r\n   * 机位\"。滑梯横跨数米、平台上的坐姿角色还比结构更高，两者都必须整块进画；\r\n   * 而\"角色该画多大\"只看站立身高。\r\n   *\r\n   * 用包围盒而不是只报高度：横向范围决定 ppu 与平移。以前只报高度，\r\n   * 滑梯的左端贴到 x=115px、右端空出 437px —— 看起来像左边被裁了，\r\n   * 其实是画面没按内容中心对齐。\r\n   */\r\n  const subjectHeight = actorHeadTop(SPEC.standHipY, Math.max(1, scale));\r\n  const content = isSlide\r\n    ? slideBounds(slideGeom.start, slideGeom.end, Math.max(1, scale))\r\n    : actorBounds(scene, Math.max(1, scale));\r\n  const shot = shotOverride ?? shotForMotion(scene.motion);\r\n  /**\r\n   * 有世界时用世界镜头：缩放固定、只按内容中心平移。三维幕因此与同一节课的\r\n   * 二维幕共用一个标尺——以前三维幕按\"整条滑梯装得下\"算，二维幕按\"这一幕\r\n   * 内容装得下\"算，同一个角色在两类幕里大小不同，切换时像换了个人。\r\n   */\r\n  const worldCamera = world ? cameraForWorld(world, shot, content) : null;\r\n  const view = worldCamera ? worldCamera.camera : framingFor({ bounds: content, subjectHeight }, shot).camera;\r\n\r\n  const slide = isSlide ? slidePose(stageScene, frame) : null;\r\n  const dribble = isSlide ? null : dribblePose(scene, frame);\r\n  const pose = slide || dribble!.pose;\r\n\r\n  return (\r\n    <div style={{ position: \"absolute\", inset: 0 }}>\r\n      {/* 场地背景：与二维同一份世界。滑梯在这里不画——三维舞台自己用 mesh 建，\r\n          这样它才能参与光照与前后遮挡，而不会被一张平面图压在后面。 */}\r\n      {world && worldCamera ? <WorldLayer world={world} camera={worldCamera} frame={frame} withSlide={false} /> : null}\r\n      <ThreeCanvas\r\n        width={width}\r\n        height={height}\r\n        camera={{ position: [0, 0, view.z], fov: view.fov, near: 0.1, far: 100 }}\r\n        style={{ position: \"absolute\", inset: 0, background: \"transparent\" }}\r\n      >\r\n        <ambientLight intensity={0.95} />\r\n        <directionalLight position={[4, 7, 6]} intensity={1.15} />\r\n        <directionalLight position={[-5, 3, -4]} intensity={0.35} />\r\n\r\n        {/* 世界整体下移 lookY、左移 lookX：相机留在原点方向，靠平移把地面压到\r\n            STAGE.groundY、把内容中心对到画面中线。2D 用 originX 表达同一件事，\r\n            两边算出的屏幕位置逐像素相同。 */}\r\n        <group position={[-view.lookX, -view.lookY, 0]}>\r\n          <ProceduralChar rig={scene.rig} pose={pose} />\r\n\r\n          {isSlide ? <SlideRig start={slideGeom.start} end={slideGeom.end} /> : null}\r\n\r\n          {dribble ? (\r\n            <>\r\n              <Ball\r\n                position={dribble.ball}\r\n                radius={BALL_RADIUS}\r\n                squash={dribble.squash}\r\n                spin={dribble.spin}\r\n              />\r\n              <Blob\r\n                x={dribble.ball[0]}\r\n                z={dribble.ball[2]}\r\n                r={clamp(0.42 - (dribble.ball[1] - 0.27) * 0.12, 0.18, 0.42)}\r\n                opacity={clamp(0.3 - (dribble.ball[1] - 0.27) * 0.12, 0.06, 0.3)}\r\n              />\r\n              <Blob x={pose.root[0]} z={pose.root[2]} r={0.5} opacity={0.22} />\r\n            </>\r\n          ) : null}\r\n        </group>\r\n      </ThreeCanvas>\r\n\r\n      {/* 角色名条：3D 里画不了可读文字，用 DOM 覆盖。\r\n          贴在标题带下沿（不是写死 132）：角色名和标题是同一条信息带的\r\n          两级，摆在不同来源的坐标上，改标题字号就会撞。 */}\r\n      {scene.label ? (\r\n        <div\r\n          style={{\r\n            position: \"absolute\",\r\n            left: 64,\r\n            top: STAGE.titleBandBottom + 8,\r\n            padding: \"8px 26px\",\r\n            borderRadius: 999,\r\n            background: accent,\r\n            color: \"#fff\",\r\n            fontSize: 34,\r\n            fontWeight: 900,\r\n            whiteSpace: \"nowrap\",\r\n            boxShadow: \"0 8px 18px rgba(0,0,0,0.16)\",\r\n          }}\r\n        >\r\n          {scene.label}\r\n        </div>\r\n      ) : null}\r\n    </div>\r\n  );\r\n};\r\n"
  }
];
